/* ═══════════ 与电脑版一致的数据层 ═══════════ */
const DB_NAME='InternalBeyondDB',DB_VER=15;/* v72-m：+feed（Internet Beyond 动态流），两端同轮 14→15 */
const IB_STORES=['posts','categories','about','music','apiSettings','chatMessages','letters','apiConfigs','groups','blogComments','memories','chatThreads','chatSummaries','uploadedFiles','blogAnnotations','projects','projectFiles','autoMemory','calEvents','calNotes','calLedger','feed'];
let db=null;
function openDB(){return new Promise((resolve,reject)=>{
  const req=indexedDB.open(DB_NAME,DB_VER);
  req.onupgradeneeded=e=>{
    const d=e.target.result;
    IB_STORES.forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:s==='categories'?'name':'id'})});
    try{const st=e.target.transaction.objectStore('chatMessages');if(!st.indexNames.contains('byFriend'))st.createIndex('byFriend','friendId',{unique:false})}catch(ex){}
    try{const pf=e.target.transaction.objectStore('projectFiles');if(!pf.indexNames.contains('byProject'))pf.createIndex('byProject','projectId',{unique:false})}catch(ex){}
    try{const am=e.target.transaction.objectStore('autoMemory');if(!am.indexNames.contains('byFriend'))am.createIndex('byFriend','friendId',{unique:false})}catch(ex){}
  };
  req.onsuccess=()=>{db=req.result;resolve(db)};
  req.onerror=()=>reject(req.error);
})}
function dbGet(s,k){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function dbGetAll(s){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function dbEach(s,cb){return new Promise((res,rej)=>{try{const req=db.transaction(s).objectStore(s).openCursor();req.onsuccess=ev=>{const c=ev.target.result;if(!c){res();return}try{cb(c.value)}catch(e){}c.continue()};req.onerror=()=>rej(req.error)}catch(e){rej(e)}})}
function _dbEachByFriend(fid,cb){return new Promise((res,rej)=>{try{const st=db.transaction('chatMessages').objectStore('chatMessages');let src=null;try{src=st.index('byFriend')}catch(e){}const req=src?src.openCursor(IDBKeyRange.only(fid)):st.openCursor();req.onsuccess=ev=>{const c=ev.target.result;if(!c){res();return}const v=c.value||{};if(src?true:v.friendId===fid){try{cb(v)}catch(e){}}c.continue()};req.onerror=()=>rej(req.error)}catch(e){rej(e)}})}
function dbCount(s){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).count();r.onsuccess=()=>res(r.result||0);r.onerror=()=>rej(r.error)})}
function dbGetRange(s,lo,hi){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).getAll(IDBKeyRange.bound(lo,hi));r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function dbGetByIndex(s,idx,val){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).index(idx).getAll(IDBKeyRange.only(val));r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
function dbPut(s,v){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).put(v);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function dbPutAll(s,arr){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');const st=tx.objectStore(s);arr.forEach(v=>{try{st.put(v)}catch(e){}});tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function dbDelete(s,k){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).delete(k);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function dbDeleteMany(s,keys){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');const st=tx.objectStore(s);keys.forEach(k=>{try{st.delete(k)}catch(e){}});tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
/* 好友最近一条主线消息（游标逆序，不整仓读取） */
function dbLastByFriend(fid){return new Promise((res,rej)=>{
  const idx=db.transaction('chatMessages').objectStore('chatMessages').index('byFriend');
  const req=idx.openCursor(IDBKeyRange.only(fid),'prev');
  req.onsuccess=()=>{const c=req.result;if(!c){res(null);return}
    const v=c.value;if(v&&!v.threadId){res(v)}else c.continue()};
  req.onerror=()=>rej(req.error);
})}
/* 按页取好友主线消息（逆序游标翻页；beforeKey 为上一页最旧一条的主键） */
let _pgThread=null;
function dbPageByFriend(fid,beforeKey,limit,threadId){const _tid=threadId||null;_pgThread=_tid;return new Promise((res,rej)=>{
  const out=[];
  const idx=db.transaction('chatMessages').objectStore('chatMessages').index('byFriend');
  const req=idx.openCursor(IDBKeyRange.only(fid),'prev');
  req.onsuccess=()=>{
    const c=req.result;
    if(!c){res({items:out.slice().reverse(),nextBefore:null,more:false});return}
    if(beforeKey!=null&&indexedDB.cmp(c.primaryKey,beforeKey)>=0){c.continue();return}
    const v=c.value;
    const _ok=v&&(_tid?v.threadId===_tid:!v.threadId);
    if(_ok){
      out.push(v);
      if(out.length>=limit){res({items:out.slice().reverse(),nextBefore:c.primaryKey,more:true});return}
    }
    c.continue();
  };
  req.onerror=()=>rej(req.error);
})}


const _histCnt={};
async function _apiHistSrcM(fid,threadId,keep){
  keep=Math.max(1,keep|0);const tid=threadId||null;const step=Math.max(6,Math.min(24,Math.ceil(keep/2)));const ck=String(fid)+'|'+String(tid||'');const cache=_histCnt[ck]||null;const max=keep+step;
  return new Promise(res=>{let out=[],fresh=0,top=null,done=false,base=cache?(cache.total|0):0;const topKey=cache?cache.top:null;
    function fin(){if(done)return;done=true;const total=cache?base+fresh:Math.max(base,out.length);const n=total<=keep?out.length:Math.min(out.length,keep+((total-keep)%step));
      const list=out.slice(0,n).reverse().sort((a,b)=>(a.timestamp||0)-(b.timestamp||0));_histCnt[ck]={total:total,top:top||topKey||null};res(list)}
    try{const idx=db.transaction('chatMessages').objectStore('chatMessages').index('byFriend');
      const walk=function(){const req=idx.openCursor(IDBKeyRange.only(fid),'prev');
        req.onsuccess=function(){const c=req.result;if(!c){fin();return}if(top==null)top=c.primaryKey;const old=topKey!=null&&indexedDB.cmp(c.primaryKey,topKey)<=0;const v=c.value;const ok=v&&(tid?v.threadId===tid:!v.threadId);
          if(ok){if(!old)fresh++;if(out.length<max)out.push(v)}
          if(out.length>=max&&(topKey==null||old)){fin();return}c.continue()};
        req.onerror=function(){fin()}};
      if(cache)walk();else{const cq=idx.count(IDBKeyRange.only(fid));cq.onsuccess=function(){base=cq.result||0;walk()};cq.onerror=function(){walk()}}
    }catch(e){fin()}})}
function _dbLastAnyByFriend(fid){return new Promise(res=>{try{const req=db.transaction('chatMessages').objectStore('chatMessages').index('byFriend').openCursor(IDBKeyRange.only(fid),'prev');req.onsuccess=()=>{const c=req.result;res(c&&c.value?c.value:null)};req.onerror=()=>res(null)}catch(e){res(null)}})}/* v211-p：该好友最新一条（不分频道），只读一条 */

