const MP_DEF={id:'mobilePrefs',perAi:{},chat:{mdMode:'full',bubbleSplit:false},mcp:{enabled:false,confirm:true,servers:[]},bt:{aiTools:false},profile:{},lock:{on:true}};/* v101-m：新装/无锁屏字段时默认开启上滑锁屏 */
let _mp=null,_mpFromDb=false;
try{document.addEventListener('visibilitychange',function(){if(!document.hidden)_mpFromDb=false});window.addEventListener('focus',function(){_mpFromDb=false})}catch(e){}/* v84-m r11：回前台失效缓存（审查 P1-6） */

function _mpNorm(m){
  if(!m.perAi)m.perAi={};
  if(!m.chat)m.chat={mdMode:'full',bubbleSplit:false};
  if(!m.bt)m.bt={aiTools:false};if(!Array.isArray(m.bt.manuals))m.bt.manuals=[];/* v137-p 任务2 */
  if(!m.mcp)m.mcp={enabled:false,confirm:true,servers:[]};
  if(!Array.isArray(m.mcp.servers))m.mcp.servers=[];
  if(!m.profile)m.profile={};
  if(!m.lock)m.lock={on:true};else if(typeof m.lock.on!=='boolean')m.lock.on=true;/* v101-m：旧记录没有 lock 字段时按新默认开启；显式 false 保留 */
  m.id='mobilePrefs';
  return m;
}
async function loadMP(){
  if(_mp&&_mpFromDb)return _mp;
  let r=null,ok=false;
  try{r=await dbGet('apiSettings','mobilePrefs');ok=true}catch(e){ok=false}
  if(ok){_mp=_mpNorm(r&&typeof r==='object'?r:JSON.parse(JSON.stringify(MP_DEF)));_mpFromDb=true}
  else if(!_mp){_mp=_mpNorm(JSON.parse(JSON.stringify(MP_DEF)))}
  return _mp;
}
async function saveMP(){
  if(!_mp)return;
  if(!_mpFromDb){
    
    let r=null,ok=false;
    try{r=await dbGet('apiSettings','mobilePrefs');ok=true}catch(e){ok=false}
    if(!ok){toast('设置保存失败，请重试');return}
    if(r&&typeof r==='object'){
      const mem=_mp;
      Object.keys(mem).forEach(k=>{
        if(k==='id')return;
        const v=mem[k];
        if(v&&typeof v==='object'&&!Array.isArray(v))r[k]=Object.assign({},r[k]||{},v);
        else r[k]=v;
      });
      _mp=_mpNorm(r);
    }
    _mpFromDb=true;
  }
  try{await dbPut('apiSettings',_mp)}catch(e){toast('设置保存失败')}
}

