let _wxLastTry=0;
async function _wxCityName(la,lo){
  try{const g=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+la+'&longitude='+lo+'&localityLanguage=zh');const gj=await g.json();const c1=(gj&&(gj.city||gj.locality||gj.principalSubdivision))||'';if(c1)return c1}catch(e){}
  try{const g2=await fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat='+la+'&lon='+lo+'&accept-language=zh-CN,zh&zoom=10',{headers:{'Accept':'application/json'}});const j2=await g2.json();const a2=(j2&&j2.address)||{};const c2=a2.city||a2.town||a2.county||a2.state_district||a2.state||'';if(c2)return c2}catch(e){}
  try{const mc=String((_mp&&_mp.perms&&_mp.perms.city)||'').trim();if(mc)return mc}catch(e){}
  return '';
}
async function _wxRefresh(force){
  if(_wxBusy)return;
  await loadMP();
  if(!(_mp.ui&&_mp.ui.wxOn))return;
  const cache=_mp.ui&&_mp.ui.wxCache;
  if(cache&&Date.now()-(cache.t||0)<45*60*1000&&isFinite(cache.temp)){_wxPaint(cache);return}
  if(!force&&Date.now()-_wxLastTry<90*1000)return;
  _wxLastTry=Date.now();
  _wxBusy=true;
  let done=false;
  const _wxGo=async(la,lo,cityHint)=>{
    try{
      const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&current_weather=true');
      const j=await r.json();
      const cw=j&&j.current_weather;if(!cw)throw new Error('no data');
      let city=cityHint||'';
      if(!city)city=await _wxCityName(la,lo);
      const c={t:Date.now(),temp:cw.temperature,code:cw.weathercode,city:city};
      _mp.ui=_mp.ui||{};_mp.ui.wxCache=c;try{await saveMP()}catch(e){}
      _wxPaint(c);done=true;
    }catch(e){}
  };
  try{
    let loc=null;
    try{if(typeof _ibNatLoc==='function')loc=await _ibNatLoc(9000)}catch(e){}/* App 壳内：原生定位（首次会弹系统授权） */
    if(!loc&&navigator.geolocation){
      loc=await new Promise(res=>{let fin=false;const end=v=>{if(!fin){fin=true;res(v)}};
        try{navigator.geolocation.getCurrentPosition(p=>end({lat:p.coords.latitude,lng:p.coords.longitude}),()=>end(null),{enableHighAccuracy:false,timeout:9000,maximumAge:300000})}catch(e){end(null)}
        setTimeout(()=>end(null),30000);
      });
    }
    if(loc&&isFinite(+loc.lat)&&isFinite(+loc.lng))await _wxGo((+loc.lat).toFixed(3),(+loc.lng).toFixed(3),'');
    if(!done){try{const c=await _ibCityGeo();if(c)await _wxGo(c.lat.toFixed(3),c.lng.toFixed(3),c.city)}catch(e){}}
  }catch(e){}
  _wxBusy=false;
  if(!done)_wxPlaceholder();
}
