      if(pp[0]==='kind'){d.kind=pp[1];var mx=_DD_MAXIMG[d.kind]||0;if(d.imgs.length>mx)d.imgs=d.imgs.slice(0,mx)}
      else if(pp[0]==='size')d.size=pp[1];
      else if(pp[0]==='who')d.who=pp[1];
