  _uvBind('uv-scale','uv-scale-v',()=>u.uiScale||1,v=>{_mp.ui.uiScale=v},pc);
  try{_heroMeetUI()}catch(e){}/* v193-p */
  const _pct=v=>Math.round(v)+'%';_uvBind('uv-drawer','uv-drawer-v',()=>u.drawerAlpha||100,v=>{_mp.ui.drawerAlpha=v},_pct);_uvBind('uv-input','uv-input-v',()=>u.inputAlpha||100,v=>{_mp.ui.inputAlpha=v},_pct);_uvBind('uv-line','uv-line-v',()=>(u.lineAlpha==null?100:u.lineAlpha),v=>{_mp.ui.lineAlpha=v},_pct);_uvBind('uv-sitebl','uv-sitebl-v',()=>u.bgBlur||0,v=>{_mp.ui.bgBlur=v},v=>Math.round(v)+'px');/* v190-p：更多绑定 */
  _uvBind('uv-alpha','uv-alpha-v',()=>u.panelAlpha||100,v=>{_mp.ui.panelAlpha=v},v=>Math.round(v)+'%');
  _uvBind('uv-scrim','uv-scrim-v',()=>u.scrimAlpha||100,v=>{_mp.ui.scrimAlpha=v},v=>Math.round(v)+'%');
  _uvBind('uv-blur','uv-blur-v',()=>u.blurPx!=null?u.blurPx:20,v=>{_mp.ui.blurPx=v},v=>u.blurPx==null&&v===20?'默认':Math.round(v)+'px');
  _uvBind('uv-bgblur','uv-bgblur-v',()=>u.bgBlur||0,v=>{_mp.ui.bgBlur=v},v=>Math.round(v)+'px');/* v70-m r1 */
  [['uv-sztop','szTop'],['uv-szdock','szDock'],['uv-szbrv','szBrv'],['uv-szcvh','szCvh'],['uv-szcvi','szCvi']].forEach(p=>{_uvBind(p[0],p[0]+'-v',()=>u[p[1]]||1,v=>{if(v===1)delete _mp.ui[p[1]];else _mp.ui[p[1]]=v},pc)});/* v128 任务1：五区尺寸滑杆 */
  const _scv=$('uv-scrimc-v');if(_scv)_scv.textContent=u.scrimColor||'主题默认';/* v72-m r6 */
  const _gbv=$('uv-gb-v');if(_gbv)_gbv.textContent=u.glassBase==='b'?'黑':(u.glassBase==='w'?'白':'主题默认');
  const _gbs=$('uv-gb');if(_gbs)_gbs.querySelectorAll('button').forEach(b=>b.classList.toggle('on',(u.glassBase||'')===b.dataset.v));
  try{_uvScrimDraw()}catch(e){}
  try{_uvPrevSync()}catch(e){}
  const _txv=$('uv-txc-v');if(_txv)_txv.textContent=u.txColor==='dark'?'黑':(u.txColor==='light'?'白':'主题默认');/* v70-m r2 */
  const seg=$('uv-txc');
  if(seg)seg.querySelectorAll('button').forEach(b=>{
    b.classList.toggle('on',(u.txColor||'')===b.dataset.v);
    if(!b._uv){b._uv=1;b.addEventListener('click',async()=>{
      await loadMP();_mp.ui=_mp.ui||{};
      if(b.dataset.v)_mp.ui.txColor=b.dataset.v;else delete _mp.ui.txColor;
      await saveMP();_uiApply();_uvSync();
    })}
  });
  const tsw=$('uv-txsh');
  if(tsw){sw2(tsw,!!u.txShadow);
    if(!tsw._uv){tsw._uv=1;tsw.addEventListener('click',async()=>{
      await loadMP();_mp.ui=_mp.ui||{};
      _mp.ui.txShadow=!_mp.ui.txShadow;await saveMP();
      sw2(tsw,!!_mp.ui.txShadow);_uiApply();
    })}
  }
  await loadBgs();_uvBgLabels();_uvAccDraw();_uvMateSync();try{_uvThemesDraw()}catch(e){}/* v69-m t12 ＋ v78-m r15：主题方案槽位 */
  const bs=$('uvbg-site-pick');
  if(bs&&!bs._uv){bs._uv=1;
    bs.addEventListener('click',()=>_pickBg('siteBg','网站背景'));
    $('uvbg-chat-pick').addEventListener('click',()=>_pickBg('chatBg','聊天背景'));
    const mkClear=(key)=>async()=>{const bg=await loadBgs();if(bg._volatile){toast('设置读取失败，请稍后再试');return}
      delete bg[key];await saveBgs();_uiApplyBg();_uvBgLabels();toast('已恢复默认')};
    $('uvbg-site-clear').addEventListener('click',mkClear('siteBg'));
    $('uvbg-chat-clear').addEventListener('click',mkClear('chatBg'));
  }
