function _hasCJK(s){return/[\u4e00-\u9fff\u3400-\u4dbf\u3000-\u303f\uff00-\uffef]/.test(s)}

/* ── Markdown → HTML 渲染器 ── */
function mdRenderHtml(text,partial){
  if(!text)return'';
  var lines=String(text).split('\n'),html=[],inFence=false,fenceLang='',fenceBuf=[];
  var inList=false,listType='',listDepth=0;
  var inBlockquote=false,bqBuf=[];
  var inTable=false,tableBuf=[];
  function closeList(){if(inList){html.push('</'+listType+'>');inList=false;listType='';listDepth=0}}
  function closeBq(){if(inBlockquote){var joined=bqBuf.join('\n');var cls=_hasCJK(joined)?' md-bq-cjk':'';html.push('<blockquote class="'+cls.trim()+'">'+inlineRender(joined)+'</blockquote>');inBlockquote=false;bqBuf=[]}}
  function closeTable(){
    if(!inTable)return;
    var rows=tableBuf.map(function(r){return r.split('|').map(function(c){return c.trim()}).filter(function(c,i,a){return i>0||c!==''})});
    /* 去掉末尾空列 */
    rows=rows.map(function(r){while(r.length&&r[r.length-1]==='')r.pop();return r});
    if(rows.length<2){html.push(tableBuf.map(function(l){return'<p>'+inlineRender(l)+'</p>'}).join(''));inTable=false;tableBuf=[];return}
    /* 第二行判断分隔行 */
    var sep=rows[1];var isSep=sep.every(function(c){return/^[\s:]*-{2,}[\s:]*$/.test(c)});
    if(!isSep){html.push(tableBuf.map(function(l){return'<p>'+inlineRender(l)+'</p>'}).join(''));inTable=false;tableBuf=[];return}
    var cols=rows[0].length;
    html.push('<table><thead><tr>');
    rows[0].forEach(function(c){html.push('<th>'+inlineRender(c)+'</th>')});
    html.push('</tr></thead><tbody>');
    for(var ri=2;ri<rows.length;ri++){
      html.push('<tr>');for(var ci=0;ci<cols;ci++)html.push('<td>'+inlineRender(rows[ri]&&rows[ri][ci]||'')+'</td>');
      html.push('</tr>');
    }
    html.push('</tbody></table>');
    inTable=false;tableBuf=[];
  }
  function inlineRender(s){
    if(!s)return'';
    s=s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');/* XSS 修复：双引号必须转义，否则链接 URL 可越出 href="..." 注入事件属性 */
    /* 行内代码 */
    s=s.replace(/`([^`\n]+)`/g,'<code class="md-il">$1</code>');
    if(!partial){
      /* 加粗+斜体 */
      s=s.replace(/\*\*\*([^*]+)\*\*\*/g,function(_,t){var cls=_hasCJK(t)?' md-em-cjk':'';return'<strong><em class="'+cls.trim()+'">'+t+'</em></strong>'});
      s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
      s=s.replace(/(^|[^\w*])\*([^*\n]+)\*(?!\*)/g,function(_,pre,t){var cls=_hasCJK(t)?' md-em-cjk':'';return pre+'<em class="'+cls.trim()+'">'+t+'</em>'});
      s=s.replace(/__([^_]+)__/g,'<strong>$1</strong>');
      s=s.replace(/(^|[^\w_])_([^_\n]+)_(?![\w_])/g,function(_,pre,t){var cls=_hasCJK(t)?' md-em-cjk':'';return pre+'<em class="'+cls.trim()+'">'+t+'</em>'});
      s=s.replace(/~~([^~]+)~~/g,'<del>$1</del>');
      /* 图片/链接 */
      s=s.replace(/!\[([^\]]*)\]\(([^)]*)\)/g,'<span title="$1">[$1]</span>');
      s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,function(_,t,u){u=String(u).trim();if(!/^(https?:|mailto:)/i.test(u))return '['+t+']('+u+')';/* XSS 修复：协议白名单，javascript: 等伪协议降级为纯文本 */return '<a href="'+u+'" target="_blank" rel="noopener noreferrer" style="color:var(--acc);text-decoration:underline">'+t+'</a>'});
    }
    return s;
  }
  for(var i=0;i<lines.length;i++){
    var L=lines[i];
    /* 围栏代码块 */
    if(/^\s*(```|~~~)/.test(L)){
      if(!inFence){closeBq();closeList();closeTable();inFence=true;fenceLang=L.replace(/^\s*(```|~~~)/,'').trim().replace(/[<>&"']/g,'');fenceBuf=[];continue}
      else{var code=fenceBuf.join('\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        html.push('<pre class="md-cb">'+(fenceLang?'<span class="md-cb-lang">'+fenceLang+'</span>':'')+'<code>'+code+'</code></pre>');
        inFence=false;fenceLang='';fenceBuf=[];continue}
    }
    if(inFence){fenceBuf.push(L);continue}
    /* 表格行 */
    if(/^\|/.test(L)){closeBq();closeList();if(!inTable)inTable=true;tableBuf.push(L);continue}
    if(inTable){closeTable()}
    /* 分割线 */
    if(!partial&&/^\s*([-*_])(\s*\1){2,}\s*$/.test(L)){closeBq();closeList();html.push('<hr>');continue}
    /* 引用 */
    if(!partial&&/^\s*>\s?/.test(L)){closeList();if(!inBlockquote)inBlockquote=true;bqBuf.push(L.replace(/^\s*>\s?/,''));continue}
    if(inBlockquote){closeBq()}
    /* 标题 */
    if(!partial){
      var hm=L.match(/^\s*(#{1,4})[ \t]+(.*?)[ \t]*#*[ \t]*$/);
      if(hm){closeList();var lvl=Math.min(hm[1].length+1,4);html.push('<h'+lvl+'>'+inlineRender(hm[2])+'</h'+lvl+'>');continue}
    }
    /* 无序列表 */
    var ulm=L.match(/^(\s*)[-*+]\s+(.*)/);
    if(ulm){closeBq();if(!inList||listType!=='ul'){closeList();html.push('<ul>');inList=true;listType='ul'}
      html.push('<li>'+inlineRender(ulm[2])+'</li>');continue}
    /* 有序列表 */
    var olm=L.match(/^(\s*)\d+\.\s+(.*)/);
    if(olm){closeBq();if(!inList||listType!=='ol'){closeList();html.push('<ol>');inList=true;listType='ol'}
      html.push('<li>'+inlineRender(olm[2])+'</li>');continue}
    /* 普通行 */
    closeList();
    if(L.trim()===''){html.push('');continue}
    html.push('<p>'+inlineRender(L)+'</p>');
  }
  /* 收尾 */
  if(inFence){var code=fenceBuf.join('\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    html.push('<pre class="md-cb">'+(fenceLang?'<span class="md-cb-lang">'+fenceLang+'</span>':'')+'<code>'+code+'</code></pre>')}
  closeList();closeBq();closeTable();
  return html.join('\n').replace(/(<p>\s*<\/p>\n?){2,}/g,'<p></p>\n');
}


function mdSoften(text){
  if(!text)return text;
  var lines=String(text).split('\n'),out=[],inFence=false;
  for(var i=0;i<lines.length;i++){
    var L=lines[i];
    if(/^\s*(```|~~~)/.test(L)){inFence=!inFence;continue}
    if(inFence){out.push(L);continue}
    if(/^\s*([-*_])(\s*\1){2,}\s*$/.test(L))continue;
    L=L.replace(/^(\s*)#{1,6}[ \t]+(.*?)[ \t]*#*[ \t]*$/,function(_m,sp,b){return b?sp+'【'+b+'】':sp});
    L=L.replace(/^(\s*)>\s?/,'$1');
    L=L.replace(/^(\s*)[-*+]\s+/,'$1');
    L=L.replace(/!\[([^\]]*)\]\(([^)]*)\)/g,'$1');
    L=L.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'$1');
    L=L.replace(/\*\*\*([^*]+)\*\*\*/g,'「$1」');
    L=L.replace(/\*\*([^*]+)\*\*/g,'「$1」');
    L=L.replace(/(^|[^\w*])\*([^*\n]+)\*(?!\*)/g,'$1$2');
    L=L.replace(/__([^_]+)__/g,'「$1」');
    L=L.replace(/(^|[^\w_])_([^_\n]+)_(?![\w_])/g,'$1$2');
    L=L.replace(/~~([^~]+)~~/g,'$1');
    L=L.replace(/`([^`\n]+)`/g,'$1');
    out.push(L);
  }
  return out.join('\n').replace(/\n{3,}/g,'\n\n');
}

/* ═══════════ 电脑版工作台指令的宽容解析（展示 + ws_tool 可执行）═══════════ */
const WS_OPEN_RE=/<ws_(help|project|read|create|edit|run|tool|gen_image|make_docx|make_pdf|make_xlsx|ask|mem_search|mem_write|blog_write|cal_add|cal_edit|cal_del|cal_meet|cal_list|beyond_view|post|comment|repost|sig|music|weather|loc|phone|payreq|beyond_inbox|search|ctx|call)\b([^>]*)>|```file:([^\n]+)\n/gi;/* v74-m r5：+mem_write */
function wsAttr(attrs,name){
  const s=String(attrs||'');
  let m=s.match(new RegExp(name+'\\s*=\\s*"([^"]*)"','i'));
  if(!m)m=s.match(new RegExp(name+"\\s*=\\s*'([^']*)'",'i'));
  if(!m)m=s.match(new RegExp(name+'\\s*=\\s*[\u201c\u201d]([^\u201c\u201d]*)[\u201c\u201d]','i'));
  if(!m)m=s.match(new RegExp(name+'\\s*=\\s*([^\\s>]+)','i'));
  return m?m[1].trim():'';
}
function segmentAiText(text){
  const segs=[];let last=0;const src=String(text||'').replace(/<ws_(?:vgift|vsnap)\b[^>]*?\/?>(?:\s*<\/ws_(?:vgift|vsnap)\s*>)?/gi,'');
  WS_OPEN_RE.lastIndex=0;let m;
  while((m=WS_OPEN_RE.exec(src))){
    const tag=m[1]?m[1].toLowerCase():null;
    const start=m.index;
    if(start>last){const t=src.slice(last,start);if(t.trim())segs.push({type:'text',text:t})}
    if(!tag){/* ```file:名字 代码块 → 下载卡 */
      const fname=(m[3]||'').trim();
      const bodyStart=m.index+m[0].length;
      const endFence=src.indexOf('\n```',bodyStart);
      const body=endFence===-1?src.slice(bodyStart):src.slice(bodyStart,endFence);
      segs.push({type:'file',name:fname||'file.txt',content:body});
      last=endFence===-1?src.length:endFence+4;
      WS_OPEN_RE.lastIndex=last;
      continue;
    }
    const attrs=m[2]||'';
    const selfClose=/\/\s*>$/.test(m[0]);
    let body='',closed=true,end=m.index+m[0].length;
    if(!selfClose){
      const closeTag='</ws_'+tag+'>';
      const ci=src.indexOf(closeTag,end);
      if(ci===-1){body=src.slice(end);closed=false;end=src.length}
      else{body=src.slice(end,ci);end=ci+closeTag.length}
    }
    const op={type:tag,attrs:attrs,body:body,truncated:!closed};
    if(tag==='tool'){op.name=wsAttr(attrs,'name');op.args=wsAttr(attrs,'args')||body.trim()}
    else if(tag==='ask'){op.title=wsAttr(attrs,'title')}
    else if(tag==='project'){op.name=wsAttr(attrs,'name')}
    else if(tag==='run'){op.lang=wsAttr(attrs,'lang');op.entry=wsAttr(attrs,'entry')}
    else if(tag==='gen_image'){op.prompt=wsAttr(attrs,'prompt')||body.trim();op.file=wsAttr(attrs,'file')}
    else if(tag==='mem_search'){op.q=wsAttr(attrs,'q')||wsAttr(attrs,'query')||body.trim()}
    else if(tag==='mem_write'){}
    else if(tag==='blog_write'){op.title=wsAttr(attrs,'title')}/* v187-p：<ws_blog_write title>Markdown 正文</ws_blog_write> */
    else if(tag==='beyond_view'){op.n=wsAttr(attrs,'n')}/* v76-m r7：主动查看 Beyond 动态流 */
    else if(tag==='post'){op.vis=wsAttr(attrs,'vis');op.img=wsAttr(attrs,'img')}
    else if(tag==='comment'){op.pid=wsAttr(attrs,'id')}
    else if(tag==='repost'){op.pid=wsAttr(attrs,'id')}/* v84-m r3 */
    else if(tag==='sig'||tag==='music'||tag==='weather'||tag==='loc'||tag==='phone'||tag==='payreq'){}
    else if(tag.indexOf('cal_')===0){op.calId=wsAttr(attrs,'id');op.calKind=wsAttr(attrs,'kind');op.date=wsAttr(attrs,'date');op.title=wsAttr(attrs,'title');op.end=wsAttr(attrs,'end');op.note=wsAttr(attrs,'note')}
    else if(tag==='search'){op.q=wsAttr(attrs,'q')||wsAttr(attrs,'query')||body.trim();op.path=wsAttr(attrs,'path')}
    else if(tag==='ctx'){op.path=wsAttr(attrs,'path');op.line=wsAttr(attrs,'line');op.span=wsAttr(attrs,'span');op.from=wsAttr(attrs,'from');op.to=wsAttr(attrs,'to');op.outline=wsAttr(attrs,'outline')}/* v221-p：+from/to/outline */
    else if(tag==='create'){op.path=wsAttr(attrs,'path');op.overwrite=/^(true|1|yes|是)$/i.test(wsAttr(attrs,'overwrite'))}
    else if(tag==='call'){op.say=wsAttr(attrs,'say')||wsAttr(attrs,'reason')}
    else{op.path=wsAttr(attrs,'path')}
    segs.push({type:'op',op:op});
    last=end;WS_OPEN_RE.lastIndex=last;
  }
  if(last<src.length){const t=src.slice(last);if(t.trim())segs.push({type:'text',text:t})}
  if(!segs.length)segs.push({type:'text',text:src});
  return segs;
}
/* 分段拆分（移植电脑版 _bsSplit 规则：按空行；含代码块/指令/表格不拆；段数与段长受限）*/
function bsSplit(text){
  const t=String(text||'');
  if(/```|<ws_|(^|\n)\s*\|.*\|/.test(t))return null;
  const parts=t.split(/\n{2,}/).map(function(s){return s.trim()}).filter(Boolean);
  if(parts.length<2||parts.length>12)return null;
  for(const p of parts){
    if(p.length>900)return null;
    if(/^\s*([>|#]|[-*+]\s|\d+[.、]\s)/.test(p))return null;
  }
  return parts;
}


var _ibBfIO=null;
function _ibBfObs(el){
  if(!el)return;
  if(typeof IntersectionObserver==='undefined'){try{document.body.classList.add('ibbf-all')}catch(e){}return}
  if(!_ibBfIO){
    try{
      _ibBfIO=new IntersectionObserver(function(es){
        for(var i=0;i<es.length;i++){var t=es[i].target;
          if(!t.isConnected){try{_ibBfIO.unobserve(t)}catch(e){}continue}
          t.classList.toggle('ibbf',es[i].isIntersecting);
        }
      },{root:document.getElementById('cv-msgs')||null,rootMargin:'150% 0px 150% 0px'});
    }catch(e){try{document.body.classList.add('ibbf-all')}catch(e2){}_ibBfIO='off'}
  }
  if(_ibBfIO&&_ibBfIO!=='off'){try{_ibBfIO.observe(el)}catch(e){}}
}
function _ibBfReset(){if(_ibBfIO&&_ibBfIO!=='off'){try{_ibBfIO.disconnect()}catch(e){}}}/* 列表整体重建前松开旧元素，防观察表越挂越长 */

/* ═══════════ 基础组件 ═══════════ */
function esc(s){if(s==null)return'';const d=document.createElement('div');d.textContent=String(s);return d.innerHTML}
function $(id){return document.getElementById(id)}
let _toastTmr=null;
function toast(t){const el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(_toastTmr);_toastTmr=setTimeout(()=>el.classList.remove('show'),2400)}
function fmtTime(ts){if(!ts)return'';const d=new Date(ts),n=new Date();
  const hm=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
  return d.toDateString()===n.toDateString()?hm:(d.getMonth()+1)+'/'+d.getDate()+' '+hm}
function openSheet(id){$(id).classList.add('open');$('sheet-scrim').classList.add('show')}
function closeSheets(){document.querySelectorAll('.sheet.open').forEach(s=>s.classList.remove('open'));$('sheet-scrim').classList.remove('show')}
$('sheet-scrim').addEventListener('click',closeSheets);
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeSheets));
function openSub(id){document.body.classList.add('on-sub');$(id).classList.add('open')}
function closeSub(id){document.body.classList.remove('on-sub');$(id).classList.remove('open')}
document.querySelectorAll('[data-subback]').forEach(b=>b.addEventListener('click',()=>closeSub(b.getAttribute('data-subback'))));
let _dlgRes=null;
function confirmDlg(msg,okLabel){return new Promise(res=>{
  _dlgRes=res;
  $('dlg-msg').textContent=msg;
  $('dlg-ok').textContent=okLabel||'确定';
  $('dlg').classList.add('show');$('dlg-scrim').classList.add('show');
})}
function _dlgEnd(v){$('dlg').classList.remove('show');$('dlg-scrim').classList.remove('show');if(_dlgRes){const r=_dlgRes;_dlgRes=null;r(v)}}
$('dlg-ok').addEventListener('click',()=>_dlgEnd(true));
$('dlg-no').addEventListener('click',()=>_dlgEnd(false));
$('dlg-scrim').addEventListener('click',()=>_dlgEnd(false));
function actionSheet(items){
  const body=$('act-body');body.innerHTML='';
  items.concat([{label:'取消'}]).forEach(it=>{
    const d=document.createElement('div');d.className='act-item'+(it.danger?' danger':'');d.textContent=it.label;
    d.addEventListener('click',()=>{closeSheets();if(it.fn)it.fn()});
    body.appendChild(d);
  });
  openSheet('sheet-act');
}
function pressable(el,fn){
  let tmr=null;
  el.addEventListener('touchstart',()=>{tmr=setTimeout(()=>{tmr=null;fn()},550)},{passive:true});
  ['touchmove','touchend','touchcancel'].forEach(ev=>el.addEventListener(ev,()=>{if(tmr){clearTimeout(tmr);tmr=null}},{passive:true}));
  el.addEventListener('contextmenu',e=>{e.preventDefault();fn()});
}
function copyText(t){
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(()=>toast('已复制'),()=>fallbackCopy(t))}
  else fallbackCopy(t);
}
function fallbackCopy(t){const x=document.createElement('textarea');x.value=t;document.body.appendChild(x);x.select();
  try{document.execCommand('copy');toast('已复制')}catch(e){toast('复制失败')}x.remove()}
async function _imgDecodeScaled(file,max){
  max=max||1600;
  if(window.createImageBitmap){try{
    var bmp=await createImageBitmap(file);
    var sc=Math.min(1,max/Math.max(bmp.width,bmp.height));
    var cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(bmp.width*sc));cv.height=Math.max(1,Math.round(bmp.height*sc));
    cv.getContext('2d').drawImage(bmp,0,0,cv.width,cv.height);
    try{bmp.close()}catch(e){}
    return cv;
  }catch(e){}}
  var url=URL.createObjectURL(file);
  try{
    var img=await new Promise(function(res,rej){var im=new Image();im.onload=function(){res(im)};im.onerror=rej;im.src=url});
    var sc2=Math.min(1,max/Math.max(img.width,img.height));
    var cv2=document.createElement('canvas');cv2.width=Math.max(1,Math.round(img.width*sc2));cv2.height=Math.max(1,Math.round(img.height*sc2));
    cv2.getContext('2d').drawImage(img,0,0,cv2.width,cv2.height);
    return cv2;
  }finally{try{URL.revokeObjectURL(url)}catch(e){}}
}
function compressImg(file,max,q){return _imgDecodeScaled(file,max).then(function(c){return c.toDataURL('image/jpeg',q)})}/* v116-p：签名与输出格式不变，仅解码内核换新 */
function downloadBlob(blob,name){
  try{
    const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href),200);return true;
  }catch(e){toast('此环境暂不支持下载');return false}
}
function sw2(el,on){if(el)el.classList.toggle('on',!!on)}
document.addEventListener('click',function(ev){try{var el=ev.target&&ev.target.closest?ev.target.closest('.sw2'):null;if(!el)return;var t=Date.now();if(el._swT&&t-el._swT<320){ev.stopImmediatePropagation();ev.preventDefault();return}el._swT=t}catch(e){}},true);
function rangeFill(el){
  if(!el)return;
  const mn=parseFloat(el.min||0),mx=parseFloat(el.max||100),v=parseFloat(el.value||0);
  el.style.setProperty('--p',(mx>mn?((v-mn)/(mx-mn)*100):0)+'%');
}
document.querySelectorAll('.ib-range').forEach(r=>{rangeFill(r);r.addEventListener('input',()=>rangeFill(r))});

/* ═══════════ 主题（水滴键，与电脑版一致地记忆选择）═══════════ */
var _LOWEND_M=null;
function _lowEndM(){
  if(_LOWEND_M!==null)return _LOWEND_M;
  var c=0,m=0,rm=false;
  try{c=navigator.hardwareConcurrency||0}catch(e){}
  try{m=navigator.deviceMemory||0}catch(e){}
  try{rm=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)}catch(e){}
  _LOWEND_M=rm||(c>0&&c<=4)||(m>0&&m<=4);return _LOWEND_M;
}
function applyTheme(dark){
  
  const first=!document.body.dataset.themed;
  if(!first&&!_lowEndM()){
    document.documentElement.classList.add('theme-anim');
    clearTimeout(applyTheme._t);
    applyTheme._t=setTimeout(()=>document.documentElement.classList.remove('theme-anim'),380);
  }
  document.body.dataset.themed='1';

  var _md=dark?'infernal':'internal';window._ibThemeMode=_md;
  document.body.classList.toggle('theme-infernal',!!dark);
  try{localStorage.setItem('ib_m_theme',_md)}catch(e){}
  /* APP 适配：状态栏颜色跟随主题 */
  try{
    var _pc=(typeof _mp==='object'&&_mp&&_mp.pwa)||{};var mc=document.getElementById('meta-theme-color');if(mc)mc.setAttribute('content',dark?(_pc.c2||'#181e32'):(_pc.c1||'#dfe9f6'));
    var sb=document.querySelector('meta[name="apple-mobile-web-app-status-bar-style"]');if(sb)sb.setAttribute('content',dark?'black-translucent':'default');
  }catch(e){}
  /* 双主题素材：切主题即换用对应主题的头像/封面/作品集 */
  try{if(currentPage==='profile'&&_sec.profile==='card')renderProfile()}catch(e){}
  try{_tbUserDraw()}catch(e){}
}
$('theme-drop').addEventListener('click',()=>applyTheme(!document.body.classList.contains('theme-infernal')));

