    w.addEventListener('touchend',e=>{const t=e.changedTouches[0];const dx=t.clientX-sx,dy=t.clientY-sy;
      if(Math.abs(dx)>44&&Math.abs(dx)>Math.abs(dy)*1.4){_amIdx+=dx<0?1:-1;_bxPgFrd=1;renderAiWall()}},{passive:true});
