  w.innerHTML='';
  const feedHost=$('bx-friend-feed');if(feedHost){feedHost.innerHTML='';feedHost.className='bx-feed'}/* v78-m r13：空态先还原普通样式，选中好友后由 bxRenderFriendFeed 换连体续接样式 */
  if(!_cfgs.length){
    w.innerHTML='<div class="pf-card"><div class="pf-cover nocover"></div>'
      +'<div class="pf-head"><div class="pf-avatar"></div><div class="pf-hmain"><div class="pf-name">None</div><div class="bxp-at"><span class="ibn-int">@InternalBeyond.com</span><span class="ibn-inf">@InfernalBeyond.com</span></div></div></div>'
      +'<div class="bxp-rows"><p class="hint" style="margin:6px 0 4px">尚未配置任何 API。添加后，每一位好友都会在这里拥有自己的资料页与动态。</p></div></div>';
    return;
  }
  const cfg=_cfgs[_amIdx];
  const per=(_mp.perAi[cfg.id]=_mp.perAi[cfg.id]||{});
  const nav=document.createElement('div');nav.className='aiw-nav';
  const l=document.createElement('button');l.textContent='‹';l.addEventListener('click',()=>{_amIdx--;_bxPgFrd=1;renderAiWall()});
  const dots=document.createElement('div');dots.className='am-dots';
