  if(duo){var _ep='M26 44 H'+(cx-5)+' l2 -9 l3 13 l2 -6 l1 2 H'+(w-26);beat='<path class="duo-beat" d="'+_ep+'"/><path class="duo-sweep" d="'+_ep+'" pathLength="120"/>'}
  host.innerHTML='<div class="duo'+(duo?'':' solo')+(small?' small':'')+'"><svg class="duo-line" viewBox="0 0 '+w+' '+(duo?82:78)+'">'+beat+'</svg>'
