function buildSheet(y,m){
  var sheet=document.createElement('div');sheet.className='cal-sheet calx2';
  var selD=null;try{if(_calSel)selD=new Date(_calSel+'T00:00:00')}catch(e){}
  if(!selD||isNaN(selD))selD=new Date();
  var h='<button class="sn-btn sn-prev" data-nav="-1" title="上一月"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10 3 5 8l5 5"/></svg></button>'
    +'<div class="c2-card c2-left"><div class="calx2-dt"><span class="c2-yr">'+y+'</span><span class="c2-mo">'+MEN[m]+'</span><span class="c2-wd">'+WEN[selD.getDay()]+'</span></div></div>'
    +'<div class="calx-med"><i class="calx-ring"></i><b class="calx-ava" id="calx-ava"></b></div>';
  h+='<div class="c2-card c2-right"><div class="cal-main"><div class="sheet-dow">';
  var DW=['S','M','T','W','T','F','S'];/* v70-m r9：半宽下周标改首字母 */
  for(var i=0;i<7;i++){var dwi=(i+WEEKSTART)%7;h+='<span'+((dwi===0||dwi===6)?' class="wknd"':'')+'>'+DW[dwi]+'</span>'}
  h+='</div><div class="sheet-grid">';
  var start=(new Date(y,m,1).getDay()-WEEKSTART+7)%7, dim=new Date(y,m+1,0).getDate(), prevDim=new Date(y,m,0).getDate();
  for(var c=0;c<42;c++){
    var dnum,cm=m,dimc=false;
    if(c<start){dnum=prevDim-start+1+c;cm=m-1;dimc=true}
    else if(c>=start+dim){dnum=c-start-dim+1;cm=m+1;dimc=true}
    else dnum=c-start+1;
    var dd=new Date(y,cm,dnum);
    var iso=isoOf(dd);
    var dots='',seen={};
    if(!dimc){
      dayItems(dd).forEach(function(it){
        var cl=dotCls(it);
        if(seen[cl])return;seen[cl]=1;dots+='<i class="dt '+cl+'"></i>'});
      if(HOLIDAY_ON&&holsOn(dd).length)dots+='<i class="dt hd"></i>';
    }
    var isToday=dd.getTime()===TODAY.getTime();
    h+='<button class="cal-cell'+(dimc?' dim':'')+(isToday?' today':'')+'" data-date="'+iso+'">'
      +'<span class="dn">'+dnum+'</span>'
      +'<span class="dots">'+dots+'</span></button>';
  }
  h+='</div></div></div>';/* cal-main 与右卡收口（v86-m r3：+c2-right 外壳） */
  h+='<button class="sn-btn sn-next" data-nav="1" title="下一月"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3l5 5-5 5"/></svg></button>';/* v86-m：右翻页裸箭头（任务 3） */
  sheet.innerHTML=h;
  return sheet;
}
function mountSheet(){
  const host=$('cal-host');if(!host)return;
  host.innerHTML='';
  const sheet=buildSheet(_calY,_calM);
  sheet.querySelectorAll('.sn-btn').forEach(b=>b.addEventListener('click',()=>{
    const nv=parseInt(b.getAttribute('data-nav'))||0;
    _calM+=nv;if(_calM<0){_calM=11;_calY--}if(_calM>11){_calM=0;_calY++}
    mountSheet();
  }));
  host.appendChild(sheet);
  try{_calxBanner()}catch(e){}/* v86-m：每次重挂都补填表盘头像（顺带修掉 v84/v85 翻月后头卡消失的旧疾） */
}

