function wsFileCard(name,content){
  const d=document.createElement('div');d.className='ws-file-card';
  d.innerHTML='<span class="wf-ico"><svg viewBox="0 0 24 24" style="width:11px;height:11px;vertical-align:-1px" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M21.4 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.2-9.19a4 4 0 0 1 5.65 5.66L9.4 17.4a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg></span><span class="wf-name">'+esc(name)+'</span><span class="wf-hint">'+fmtBytes((content||'').length)+' · 点按下载</span>';
  d.addEventListener('click',e=>{e.stopPropagation();
    try{
      const blob=new Blob([content||''],{type:'text/plain;charset=utf-8'});
      const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name||'file.txt';
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(a.href),200);
    }catch(err){toast('此环境暂不支持下载')}
  });
  return d;
}
