/* 微信式钉底：同步 + 下一帧 + 图片撑高后各钉一次（真实高度已恢复，不再有"假底部"）*/
function pinBottom(){try{_tmCollapseAll()}catch(e){}
  const box=convEl('cv-msgs');
  const pin=()=>{box.scrollTop=box.scrollHeight};
  pin();
  requestAnimationFrame(pin);
  setTimeout(pin,60);
  box.querySelectorAll('img').forEach(img=>{
    if(!img.complete)img.addEventListener('load',()=>{
      if(box.scrollHeight-box.scrollTop-box.clientHeight<300)pin();
    },{once:true});
  });
}
