  const box=convEl('cv-msgs');
  let pg={items:[],nextBefore:null,more:false};
  try{pg=await dbPageByFriend(_activeCfg.id,_before,PAGE,_tid0)}catch(e){}
  loadEarlier._busy=false;
  if(_seq0!==_convSeq)return;
  const btn=document.getElementById('cv-more');
