    if(text.length>300000)text=text.slice(0,300000);
    
    let _bad=0;const _hd=text.slice(0,4096);
    for(let _bi=0;_bi<_hd.length;_bi++){const _bc=_hd.charCodeAt(_bi);
      if(_bc===0||_bc===0xFFFD){_bad=_hd.length;break}
      if((_bc<9||(_bc>13&&_bc<32))&&_bc!==27)_bad++}
    if(_hd.length&&_bad/_hd.length>0.05){toast(f.name+'：看起来是二进制文件，读不出文字');continue}
