function vtUrl(ep){
  let u=(ep||'https://api.openai.com/v1').trim().replace(/\/+$/,'');
  if(!/\/audio\/transcriptions$/.test(u)){
    if(!/\/v\d+$/.test(u))u+='/v1';
    u+='/audio/transcriptions';
  }
  return u;
}
function _vtChatAudioM(vt){return /^qwen[\w.-]*(asr|omni)/i.test(String((vt&&vt.model)||''))}/* v178-p：千问 ASR / Omni 在百炼 compatible-mode 只以 chat 音频输入形态提供，按模型名自动切路径 */
async function _vtViaChatM(vt,blob,mime,ext){
  const b64=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(String(fr.result).split(',')[1]||'');fr.onerror=rej;fr.readAsDataURL(blob)});
  let base=String(vt.endpoint||'https://dashscope.aliyuncs.com/compatible-mode/v1').trim().replace(/\/+$/,'').replace(/\/audio\/transcriptions$/,'').replace(/\/chat\/completions$/,'');if(!/\/v\d+$/.test(base))base+='/v1';
  const body={model:vt.model,stream:false,messages:[{role:'user',content:[{type:'input_audio',input_audio:{data:'data:'+String(mime||'audio/webm').split(';')[0]+';base64,'+b64,format:ext}}]}]};
  const ac=new AbortController();const tmr=setTimeout(()=>ac.abort(),45000);
  try{const res=await fetch(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+vt.apiKey},body:JSON.stringify(body),signal:ac.signal});clearTimeout(tmr);
    const raw=await res.text();if(!res.ok)throw new Error('HTTP '+res.status+'：'+raw.slice(0,120));
    let j=null;try{j=JSON.parse(raw)}catch(e){return raw.trim()}
    const c=j&&j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content;
    return String(typeof c==='string'?c:(Array.isArray(c)?c.map(x=>(x&&(x.text||''))).join(''):'')).trim();
  }catch(err){clearTimeout(tmr);throw err}
}
async function vtTranscribe(blob,mime){
  const vt=await loadVT();
  const ext=/mp4/.test(mime)?'mp4':(/ogg/.test(mime)?'ogg':'webm');
  if(_vtChatAudioM(vt))return _vtViaChatM(vt,blob,mime,ext);/* v178-p：千问系走 chat 音频输入 */
  const fd=new FormData();
  fd.append('file',blob,'voice.'+ext);
  fd.append('model',vt.model||'whisper-1');
  const ac=new AbortController();const tmr=setTimeout(()=>ac.abort(),30000);
  try{
    const res=await fetch(vtUrl(vt.endpoint),{method:'POST',headers:{'Authorization':'Bearer '+vt.apiKey},body:fd,signal:ac.signal});
    clearTimeout(tmr);
    const raw=await res.text();
    if(!res.ok)throw new Error('HTTP '+res.status+'：'+raw.slice(0,120));
    try{const j=JSON.parse(raw);return j.text||(j.data&&j.data.text)||''}catch(e){return raw.trim()}
  }catch(err){clearTimeout(tmr);throw err}
}
