function _parseThinking(raw){
  var thinking='', reply=raw||'';
  var lead=reply.match(/^\s*<\/think(?:ing)?>\s*/i);
  if(lead)reply=reply.slice(lead[0].length);
  var openMatch=reply.match(/^\s*<think(?:ing)?>/i);
  if(openMatch){
    var rest=reply.slice(openMatch[0].length);
    var closeMatch=rest.match(/<\/think(?:ing)?>/i);
    if(closeMatch){
      thinking=rest.slice(0,closeMatch.index).trim();
      reply=rest.slice(closeMatch.index+closeMatch[0].length);
    }else{
      var splitIdx=rest.search(/\n\s*\n/);
      if(splitIdx>0){
        thinking=rest.slice(0,splitIdx).trim();
        reply=rest.slice(splitIdx);
      }else{
        reply=rest;
      }
    }
  }
  return {thinking:thinking,reply:reply.trim()};
}
/* 流式期间的实时截流：整串还是 <thinking 前缀时先按住不显示 */
function _splitThinkLive(raw){
  raw=raw||'';
  if(/^\s*<$|^\s*<\/?t(h(i(n(k(i(n(g)?)?)?)?)?)?)?$/i.test(raw))return{thinking:'',reply:''};
  const m=raw.match(/^\s*<think(?:ing)?>/i);
  if(!m)return{thinking:'',reply:raw};
  const rest=raw.slice(m[0].length);
  const c=rest.match(/<\/think(?:ing)?>/i);
  if(c)return{thinking:rest.slice(0,c.index).trim(),reply:rest.slice(c.index+c[0].length).replace(/^\s+/,'')};
  return{thinking:rest,reply:''};
}

function _splitThinkAnyLive(raw){
  raw=raw||'';
  var OPEN=/<think(?:ing)?\b[^>]*>/i,CLOSE=/<\/think(?:ing)?\s*>/i;
  var reply='',thinking='',buf=raw;
  for(;;){
    var op=buf.match(OPEN);
    if(!op){
      var half=buf.match(/<\/?(?:t(?:h(?:i(?:n(?:k(?:i(?:n(?:g)?)?)?)?)?)?)?)?$/);
      if(half&&half[0])buf=buf.slice(0,half.index);
      reply+=buf;break;
    }
    reply+=buf.slice(0,op.index);
    var rest=buf.slice(op.index+op[0].length);
    var cl=rest.match(CLOSE);
    if(!cl){thinking+=(thinking?'\n':'')+rest.replace(/^\s+/,'');buf='';break}
    thinking+=(thinking?'\n':'')+rest.slice(0,cl.index).trim();
    buf=rest.slice(cl.index+cl[0].length);
    var jt=(reply.match(/\s+$/)||[''])[0],jl=(buf.match(/^\s+/)||[''])[0];/* 缝合处：块两侧原有换行→并成一个空行；纯行内出现→原样拼回，不添不减 */
    if(reply.trim()&&/\n/.test(jt+jl)){reply=reply.slice(0,reply.length-jt.length)+'\n\n';buf=buf.slice(jl.length)}
    else if(!reply.trim()){reply='';buf=buf.replace(/^\s+/,'')}
  }
  return{thinking:thinking,reply:reply.replace(/^\s+/,'')};
}
function _parseThinkAny(raw){
  var p=_splitThinkAnyLive(String(raw||''));
  return{thinking:(p.thinking||'').trim(),reply:(p.reply||'').trim()};
}

const _ST_TAGS='ws_help|ws_create|ws_edit|ws_read|ws_project|ws_run|ws_tool|ws_gen_image|ws_make_docx|ws_make_pdf|ws_make_xlsx|ws_ask|ws_post|ws_comment|ws_music|ws_weather|ws_sig|ws_mem_write|ws_blog_write|ws_mem_search|ws_cal_add|ws_cal_edit|ws_cal_del|ws_cal_meet|ws_cal_list|ws_beyond_view|ws_repost|ws_loc|ws_phone|ws_payreq|ws_beyond_inbox|ws_search|ws_ctx|cal_note|mem_create|mem_update|mem_delete|ws_call|ibvoice';/* v81-m r7：+ws_sig；v72-m：+Beyond/播放器/天气；v74-m r5：+记忆库写入/检索 */
