const _contBusyM=new Set();
function _buildContinuePillM(msgId){
  const c=document.createElement('div');c.className='ws-op-card ws-continue-pill';c.dataset.contFor=msgId||'';
  const t=document.createElement('span');t.className='ws-op-text';t.textContent='回复因输出上限被截断';
  const b=document.createElement('button');b.className='ws-file-btn';b.style.flexShrink='0';b.textContent='▸ 继续生成';
  b.addEventListener('click',ev=>{ev.stopPropagation();continueTruncatedMsgM(msgId,c)});
  c.appendChild(t);c.appendChild(b);
  return c;
}
async function continueTruncatedMsgM(msgId,pillEl){
  if(!msgId||_contBusyM.has(msgId))return;
  let m=null;try{m=await dbGet('chatMessages',msgId)}catch(e){}
  if(!m||!m.content){toast('原消息不存在');return}
  /* 续写会把原 assistant 文本再次发给 API；封档线之前的消息必须禁止 */
  {let _seal=0;/* v174：⑧频道消息对账频道自己的封档线 */
    if(m.threadId){let _thr=(_activeThread&&_activeThread.id===m.threadId)?_activeThread:null;if(!_thr){try{_thr=await dbGet('chatThreads',m.threadId)}catch(e){}}_seal=Number((_thr&&_thr.sealTimestamp)||0)}
    else _seal=(_activeCfg&&_activeCfg.id===m.friendId&&_activeCfg.sealTimestamp)||0;
    if(_seal&&(m.timestamp||0)<=_seal){toast('该消息在封档线之前，不能再发给 API');return}
  }
  /* 找回该消息的 API 配置：群聊按 senderName 反查成员，1对1按 friendId */
  let cfg=null;
  if(String(m.friendId||'').indexOf('group_')===0){
    try{
      const g=await dbGet('groups',m.friendId);
      if(g&&Array.isArray(g.members))cfg=g.members.map(id=>_cfgs.find(a=>a.id===id)).filter(Boolean).find(a=>cfgName(a)===m.senderName);
    }catch(e){}
  }else cfg=_cfgs.find(a=>a.id===m.friendId);
  if(!cfg||!cfg.apiKey){toast('找不到可用的 API 配置');return}
  _contBusyM.add(msgId);
  const btn=pillEl&&pillEl.querySelector('button');
  if(btn){btn.disabled=true;btn.textContent='续写中…'}
  /* 页面上这条气泡的正文节点，用来直播续写文本 */
  const host=convEl('cv-msgs').querySelector('.m[data-id="'+msgId+'"] .m-text');
  const live=document.createElement('span');
  if(host)host.appendChild(live);
  const old=String(m.content||'');
  const sys=(cfg.systemPrompt||'').trim()+'\n\n'+_WS_INSTR_BLOCK.replace(/^\n+/,'');
  const hist=[{role:'assistant',content:old},{role:'user',content:_WS_CONT_PROMPT_M}];
  let piece='',fin='';
  try{
    await loadMP();
    const r=await callAIC(_cfgFmtM(cfg)==='anthropic'?cfg:Object.assign({},cfg,{thinkingEnabled:false}),hist,sys,
      t=>{if(t&&t.length>=120)live.textContent=_wsDedupSeamM(old,t)},null,mpAi(cfg));
    piece=_wsDedupSeamM(old,r.t||'');fin=r.fin||'';
  }catch(e){
    live.remove();
    if(btn){btn.disabled=false;btn.textContent='▸ 继续生成'}
    _contBusyM.delete(msgId);
    toast('续写失败：'+String((e&&e.message)||e).slice(0,60));
    return;
  }
  live.remove();
  _contBusyM.delete(msgId);
  if(!piece.trim()){
    if(btn){btn.disabled=false;btn.textContent='▸ 继续生成'}
    toast('没有续写出新内容');return;
  }
  m.content=old+piece;
  if(_finTruncM(fin))m.truncated=true;else delete m.truncated;/* 还截断就留着药丸，可以接着点 */
  try{await dbPut('chatMessages',m)}catch(e){toast('保存失败');return}
  const i=_msgs.findIndex(x=>x.id===msgId);
  if(i>=0){_msgs[i]=m;const row=convEl('cv-msgs').querySelector('.m[data-id="'+msgId+'"]');const wrap=row?_rowOf(row):null;if(wrap)wrap.replaceWith(buildMsgEl(m))}
  try{_tmCollapseAll()}catch(e){}/* v97-m 任务3 */
  toast(m.truncated?'已续写（仍未写完，可再点一次）':'已续写完成');
}
