function _ibToolFill(tpl,args,forUrl){
  return String(tpl||'').replace(/\{\{\s*([\w.]+)\s*\}\}/g,function(mm,k){
    let v=args;
    k.split('.').forEach(function(p){if(v&&typeof v==='object')v=v[p];else v=undefined});
    if(v==null)v='';
    v=typeof v==='object'?JSON.stringify(v):String(v);
    return forUrl?encodeURIComponent(v):v.replace(/"/g,'\\"');
  });
}
async function ibToolFetch(tool,args){
  const url=_ibToolFill(tool.url,args,true);
  const method=(tool.method||'GET').toUpperCase();
  let headers={};
  try{if(tool.headers&&String(tool.headers).trim())headers=JSON.parse(tool.headers)}catch(e){}
  const opt={method:method,headers:headers};
  if(method!=='GET'&&method!=='HEAD'){
    if(tool.body&&String(tool.body).trim()){
      opt.body=_ibToolFill(tool.body,args,false);
      if(!headers['Content-Type'])headers['Content-Type']='application/json';
    }else if(args&&Object.keys(args).length){
      opt.body=JSON.stringify(args);
      if(!headers['Content-Type'])headers['Content-Type']='application/json';
    }
  }
  const ac=new AbortController();const tmr=setTimeout(()=>ac.abort(),15000);
  opt.signal=ac.signal;
  try{
    const res=await fetch(url,opt);
    clearTimeout(tmr);
    const raw=await res.text();
    return{ok:res.ok,status:res.status,detail:'HTTP '+res.status+' · '+raw.slice(0,600)};
  }catch(err){
    clearTimeout(tmr);
    return{ok:false,status:0,detail:err&&err.name==='AbortError'?'超时（15s）':('请求失败：'+String((err&&err.message)||err).slice(0,200))};
  }
}
function parseArgs(s){
  if(!s)return{};
  if(typeof s==='object')return s;
  try{return JSON.parse(s)}catch(e){}
  try{return JSON.parse(String(s).replace(/[\u201c\u201d]/g,'"').replace(/'/g,'"'))}catch(e){}
  return{_raw:String(s)};
}
async function execToolOp(op){
  if(op&&op._btCap)return{ok:false,detail:'已达本条回复的蓝牙读写上限（可在 API → 全局设置 → 工具调用 调整），本次未执行'};/* v135-p：#5 */
  const args=parseArgs(op.args);
  const name=op.name||'';
  if(/^mcp\./i.test(name))return await IBMCP.call(name,args);
  if(/^bt_/i.test(name))return await btToolExec(name,args);/* v49i-m 蓝牙工具 */
  await loadIBT();
  if(_ibt.enabled===false)return{ok:false,detail:'外部工具当前处于停用状态'};
  const tool=(_ibt.tools||[]).find(t=>t.name===name);
  if(!tool)return{ok:false,detail:'未找到名为「'+name+'」的工具'};
  return await ibToolFetch(tool,args);
}
