var _bticProj=null;
async function bticOpen(){_bticProj=null;await bticDraw();openSheet('sheet-btic')}
function bticClose(){const s=$('sheet-btic');if(s)s.classList.remove('open')}/* 只收起取文层，编辑层与遮罩保持 */
async function bticDraw(){
  const box=$('btic-list');if(!box)return;box.innerHTML='';
  $('btic-back').style.display=_bticProj?'':'none';
  $('btic-title').textContent=_bticProj?(_bticProj.name||'项目'):'从 ICode 选择文本文件';
  if(!_bticProj){
    await icEnsureFixed();let projs=[];try{projs=await dbGetAll('projects')}catch(e){}
    projs.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'zh-CN'));
    if(!projs.length){box.innerHTML='<div class="empty" style="padding:14px">工作区还没有项目</div>';return}
    projs.forEach(pj=>{
      const d=document.createElement('div');d.className='btlib-row';
      d.innerHTML='<div class="btlib-m"><b>'+esc(pj.name||'项目')+'</b></div><span class="hint" style="margin:0">›</span>';
      d.addEventListener('click',async()=>{_bticProj=pj;await bticDraw()});box.appendChild(d);
    });
    return;
  }
  const files=(await icMetaOf(_bticProj.id)).sort((a,b)=>(b.lastModified||0)-(a.lastModified||0));
  if(!files.length){box.innerHTML='<div class="empty" style="padding:14px">这个项目还没有文件</div>';return}
  files.forEach(f=>{
    const nm=f.path||f.name||'未命名';
    const d=document.createElement('div');d.className='btlib-row';
    d.innerHTML='<div class="btlib-m"><b>'+esc(nm)+'</b><small>'+icFmtSize(f.size||0)+'</small></div>';
    d.addEventListener('click',async()=>{
      let full=null;try{full=await dbGet('projectFiles',f.id)}catch(e){}
      const c=full&&typeof full.content==='string'?full.content:'';
      if(!c){toast('文件为空或读取失败');return}
      if(/^data:/.test(c)){toast('这是二进制文件（图片等），说明书只能用文本');return}
      const cur=$('btm-text').value||'';
      if(cur.trim()&&!await confirmDlg('导入将替换当前编辑框内容，继续？','替换'))return;
      if(!$('btm-name').value.trim())$('btm-name').value=String(nm).replace(/\.[a-z0-9]{1,8}$/i,'').slice(0,48);
      $('btm-text').value=c.slice(0,10000);_btmCount();
      if(c.length>8000)toast('内容超过 8000 字，保存前请精简');
      bticClose();
    });
    box.appendChild(d);
  });
}
function _btHex(dv){let h='';for(let i=0;i<dv.byteLength;i++)h+=dv.getUint8(i).toString(16).padStart(2,'0');return h}
async function btToolExec(name,args){
  await loadMP();
  if(!(_mp.bt&&_mp.bt.aiTools))return{ok:false,detail:'蓝牙工具未开启（设置页 → 蓝牙设备）'};
  if(!_btList().length)return{ok:false,detail:'尚未连接蓝牙设备。请让用户在设置页手动点「连接设备」（浏览器要求连接必须由用户发起）。'};
  try{
    if(name==='bt_status')return{ok:true,label:'蓝牙状态',detail:_btStatusText()};
    const uu=args&&(args.uuid||args.char);
    const pk=_btPick(args,uu);if(pk.err)return{ok:false,detail:pk.err};
    const d=pk.d,c=_btFindIn(d,uu);
    if(!c)return{ok:false,detail:'设备「'+(d.name||'未命名')+'」上找不到该特征值，请先用 bt_status 查看可用列表'};
    const tag=(_btList().length>1?(d.name||'设备')+' · ':'')+_btShort(c.uuid);
    if(name==='bt_read'){
      const v=await _btTimeout(c.ch.readValue(),12000,'读取');let txt='';try{txt=new TextDecoder().decode(v)}catch(e){}
      return{ok:true,label:'蓝牙读取 · '+tag,detail:'hex: '+_btHex(v)+(/[\x20-\x7e\u4e00-\u9fff]{2,}/.test(txt)?'\ntext: '+txt:'')};
    }
    if(name==='bt_write'){
      let bytes;
      if(args&&args.hex){const h=String(args.hex).replace(/[^0-9a-f]/gi,'');bytes=new Uint8Array((h.match(/../g)||[]).map(x=>parseInt(x,16)))}
      else bytes=new TextEncoder().encode(String((args&&args.text)||''));
      await _btTimeout(c.ch.properties.write?c.ch.writeValue(bytes):c.ch.writeValueWithoutResponse(bytes),12000,'写入');
      return{ok:true,label:'蓝牙写入 · '+tag,detail:bytes.byteLength+' 字节已发送'};
    }
    return{ok:false,detail:'未知蓝牙操作'};
  }catch(e){return{ok:false,detail:'蓝牙操作失败：'+String(e&&e.message||e).slice(0,120)}}
}
