async function buildToolsBlock(){
  await loadIBT();await loadMP();
  const list=[];
  if(_ibt.enabled&&(_ibt.tools||[]).length){
    _ibt.tools.forEach(t=>{list.push('- '+t.name+(t.desc?'：'+t.desc:'')+(t.params?'（参数：'+t.params+'）':''))});
  }
  if(_mp.mcp.enabled){
    (_mp.mcp.servers||[]).forEach(sv=>{
      if(sv.enabled===false)return;
      (sv.tools||[]).forEach(t=>{
        if(t.enabled===false)return;
        
        let sc='';try{if(t.inputSchema)sc=JSON.stringify(t.inputSchema)}catch(e){}
        list.push('- mcp.'+sv.alias+'.'+t.name+'：'+_ibCut(String(t.description||'').replace(/\s+/g,' '),2000)+(sc?'\n  参数 schema：'+_ibCut(sc,3000):''));
      });
    });
  }
  if(navigator.bluetooth&&_mp.bt&&_mp.bt.aiTools){
    list.push('- bt_status：查看已连接的全部蓝牙设备（可多台）及各自的特征值');
    list.push('- bt_read：读取一个特征值的当前值（参数：uuid*；连了多台时加 dev＝设备名或序号）');
    list.push('- bt_write：向一个特征值写入（参数：uuid*，hex 或 text 二选一；连了多台时加 dev＝设备名或序号）');/* v132-p：多设备 */
  }
  if(!list.length)return'';
  const confirmNote=(_ibt.confirm!==false||_mp.mcp.confirm!==false)?'（用户开启了调用确认，发起后需等用户点执行）':'';
  return '【外部工具】需要实时数据或触发外部动作时，输出：<ws_tool name="工具名" args=\'{"参数":"值"}\'/>（mcp. 开头的是 MCP 服务器工具；只能调用列表内工具；同一条回复里可以连续输出多个 <ws_tool>，也可与查定位、读日历、检索记忆等其它标签混用——系统会按输出顺序逐个执行并各回一张操作卡，需要同时做几件事时请一次写全，不必分成多轮；结果会在之后的消息注入给你'+confirmNote+'）。可用工具：\n'+list.join('\n')+_btManualBlock();/* v137-p 任务2：已连接设备的说明书随连接状态整块注入（连/断一次重建一次缓存，之后稳定命中） */
}
/* 公开日志注入（AI 读取范围·每 AI 独立；锁定日记绝不注入）*/
async function buildPostsBlock(limit){
  const mode=parseInt(limit,10);
  if(isNaN(mode)||mode===0)return'';/* 0：Blog 列表与 blog_read 能力说明整块不发送 */
  if(mode===-1)return '【用户最近的 Blog】你可以申请阅读用户的公开 Blog：<blog_read name="日志标题"/>。标题可由用户提供；阅读需用户授权，未获授权前不要声称已读。';
  limit=Math.max(0,mode);
  let posts=[];try{posts=await dbGetAll('posts')}catch(e){}
  posts=posts.filter(p=>p&&!isLockedPost(p)&&!p.aiWritten)/* v187-p：AI 写的日志不进列表注入 */
    .sort((a,b)=>(b.created||b.timestamp||0)-(a.created||a.timestamp||0))
    .slice(0,limit);
  const lines=[];
  for(const p of posts){
    const raw=String(p.content||'').replace(/\s+/g,' ').trim();
    lines.push('《'+(p.title||'无标题')+'》：'+raw.slice(0,40)+(raw.length>40?'……':''));
  }
  let out='【用户最近的 Blog】\n以下为权限范围内用户近期的 Blog，本次可见 '+posts.length+' 篇：\n';
  out+=lines.length?'\n'+lines.join('\n'):'\n（目前没有可见的公开 Blog）';
  out+='\n\n你可以申请阅读完整内容。需要阅读某篇日志时输出：\n<blog_read name="日志标题"/>\n规则：标题从上方日志列表获得，或由用户提供；提交后界面会向用户展示该篇字数并请求授权，用户点击允许后，全文才会在下一条消息注入给你；未收到注入前不要声称已经读过；一次只申请一篇；被拒绝后不要重复申请同一篇，除非用户主动要求。长文可加 from="起始字符位"（1 起）与 chars="长度" 分段申请。';
  return out;
}


var _blogReqRegM={};
var _blogPendingReadsM=[];/* {fid,title,content,range,total} */
var _blogReadFeedbackM=[];/* {fid,text} */

async function _blogAllowedM(cfg){
  try{await loadMP();var n=parseInt(cfg&&mpAi(cfg).postsLimit,10);return !isNaN(n)&&n!==0}catch(e){return false}
}
function _parseBlogReadOpsM(text){
  var ops=[];if(!text||String(text).indexOf('<blog_read')===-1)return{clean:text,ops:ops};
  var clean=String(text).replace(/<blog_read\b([^>]*?)(?:\/>|>\s*<\/blog_read\s*>)/gi,function(_m,attrStr){
    var attrs={};String(attrStr||'').replace(/(\w+)\s*=\s*"([^"]*)"/g,function(__,k,v){attrs[k]=v;return''});
    ops.push({name:(attrs.name||'').trim(),from:parseInt(attrs.from,10)||0,chars:parseInt(attrs.chars,10)||0});
    return'';
  }).replace(/\n{3,}/g,'\n\n');
  return{clean:clean,ops:ops};
}
function _blogTokenEstM(s){s=String(s||'');var cjk=0,other=0;for(var i=0;i<s.length;i++){var c=s.charCodeAt(i);if((c>=0x4e00&&c<=0x9fff)||(c>=0x3400&&c<=0x4dbf)||(c>=0x3040&&c<=0x30ff)||(c>=0xac00&&c<=0xd7af)||(c>=0xf900&&c<=0xfaff))cjk++;else other++}return cjk+Math.ceil(other/4)}
async function _blogFindPostM(name){
  var q=String(name||'').trim();if(!q)return{status:'notfound',name:q};
  var posts=[];try{posts=(await dbGetAll('posts')).filter(function(p){return p&&!isLockedPost(p)})}catch(e){}
  var exact=posts.filter(function(p){return String(p.title||'').trim()===q});
  if(exact.length===1)return{status:'ok',post:exact[0]};
  var pool=exact.length>1?exact:posts.filter(function(p){return String(p.title||'').indexOf(q)!==-1});
  if(pool.length===1)return{status:'ok',post:pool[0]};
  if(pool.length>1)return{status:'multi',name:q,titles:pool.slice(0,8).map(function(p){return p.title||'无标题'})};
  return{status:'notfound',name:q};
}
async function _execBlogReadOpsM(ops,cfg,threadId){
  var cards=[];var fid=cfg&&cfg.id||'';
  if(!await _blogAllowedM(cfg)){
    for(var z=0;z<Math.min((ops||[]).length,3);z++)cards.push({kind:'info',text:'Blog 阅读权限已关闭，本次申请未执行'});
    return cards;
  }
  for(var i=0;i<ops.length&&i<3;i++){
    var op=ops[i],r=await _blogFindPostM(op.name);
    if(r.status==='ok'){
      var full=String(r.post.content||''),from=Math.max(0,(op.from||0)-1);
      if(from>=full.length&&full.length>0){_blogReadFeedbackM.push({fid:fid,text:'《'+(r.post.title||'无标题')+'》全文共 '+full.length+' 字符，from='+op.from+' 超出范围'});cards.push({kind:'info',text:'申请的起始位置超出《'+(r.post.title||'无标题')+'》的全文范围'});continue}
      var segLen=op.chars>0?Math.min(op.chars,full.length-from):(full.length-from),segTxt=full.slice(from,from+segLen);
      if(r.post.aiWritten)_blogReadFeedbackM.push({fid:fid,text:'《'+(r.post.title||'无标题')+'》这篇日志是 '+(r.post.authorName||'TA')+' 写的，不是用户写的'});/* v187-p */
      var uid='brm_'+Date.now()+'_'+Math.floor(Math.random()*100000);
      _blogReqRegM[uid]={state:'pending',fid:fid,threadId:threadId||'',postId:r.post.id,title:r.post.title||'无标题',from:op.from||0,chars:op.chars||0,charCount:segTxt.length,total:full.length,tokens:_blogTokenEstM(segTxt)};
      cards.push({kind:'req',uid:uid});
    }else if(r.status==='multi'){
      _blogReadFeedbackM.push({fid:fid,text:'日志名称「'+r.name+'」匹配到多篇：《'+r.titles.join('》《')+'》，请向用户确认是哪一篇后重新申请'});
      cards.push({kind:'info',text:'「'+r.name+'」匹配到多篇日志，已请 AI 与你确认'});
    }else{
      _blogReadFeedbackM.push({fid:fid,text:'日志「'+r.name+'」不存在，可向用户确认名称'});
      cards.push({kind:'info',text:'未找到名为「'+r.name+'」的日志'});
    }
  }
  return cards;
}
function _brBuildCardM(c){
  if(c.kind==='info'){
    var d=document.createElement('div');d.className='ws-op-card';d.innerHTML=WS_ICON.read+'<span class="ws-op-text">'+esc(c.text)+'</span>';return d;
  }
  var el=document.createElement('div');el.className='ws-op-card';el.dataset.blogreq=c.uid;el.style.flexWrap='wrap';_brRenderCardM(el,c.uid);return el;
}
function _brRenderCardM(el,uid){
  var req=_blogReqRegM[uid];if(!req)return;
  var rangeTxt=(req.from>1||req.chars>0)?('第 '+Math.max(1,req.from||1)+' 字符起 '+req.charCount+' 字符（全文 '+req.total+' 字符）'):(req.charCount+' 字符');
  var head=WS_ICON.read+'<span class="ws-op-text"><b>阅读申请</b> · 《'+esc(req.title)+'》 · '+rangeTxt+' · 约 '+req.tokens.toLocaleString()+' tokens<br><span style="opacity:0.65;font-size:0.9em">允许后，全文将随下一条消息发送。</span></span>';
  if(req.state==='pending'){
    el.innerHTML=head;
    var ok=document.createElement('button');ok.className='ws-file-btn';ok.style.flexShrink='0';ok.textContent='允许阅读';ok.onclick=function(ev){ev.stopPropagation();_brAllowM(uid)};
    var no=document.createElement('button');no.className='ws-file-btn';no.style.cssText='flex-shrink:0;opacity:0.7';no.textContent='拒绝';no.onclick=function(ev){ev.stopPropagation();_brDenyM(uid)};
    el.appendChild(ok);el.appendChild(no);
  }else if(req.state==='allowed')el.innerHTML=head+'<span class="ws-op-text" style="flex-basis:100%;opacity:0.75">已允许 · 内容随下一条消息注入</span>';
  else el.innerHTML=head+'<span class="ws-op-text" style="flex-basis:100%;opacity:0.75">已拒绝 · 内容未发送</span>';
}
function _brUpdateCardsM(uid){document.querySelectorAll('[data-blogreq="'+uid+'"]').forEach(function(el){_brRenderCardM(el,uid)})}
async function _brAllowM(uid){
  var req=_blogReqRegM[uid];if(!req||req.state!=='pending')return;
  var cfg=(_activeCfg&&_activeCfg.id===req.fid)?_activeCfg:null;
  if(!cfg||((_activeThread?_activeThread.id:'')!==(req.threadId||''))){toast('请回到发起申请的对话后再允许阅读');return}
  if(_sendKeys.has(_convKey(cfg))){toast('对方正在回复中，请稍后再点允许');return}
  if(!await _blogAllowedM(cfg)){req.state='denied';_brUpdateCardsM(uid);toast('Blog 阅读权限已关闭，申请作废');return}
  var p=null;try{p=await dbGet('posts',req.postId)}catch(e){}
  if(!p||isLockedPost(p)){req.state='denied';_brUpdateCardsM(uid);_blogReadFeedbackM.push({fid:req.fid,text:'《'+req.title+'》已不可读（被删除或转为私密），申请作废'});toast('该日志已不可读，申请作废');return}
  var full=String(p.content||''),from=Math.max(0,(req.from||0)-1),segLen=req.chars>0?Math.min(req.chars,Math.max(0,full.length-from)):Math.max(0,full.length-from),seg=full.slice(from,from+segLen);
  var range=(req.from>1||req.chars>0)?{from:from+1,to:from+seg.length,total:full.length}:null;
  _blogPendingReadsM.push({fid:req.fid,title:p.title||req.title,content:seg,range:range,total:full.length});
  req.state='allowed';_brUpdateCardsM(uid);
  await sendQuickText('请继续');/* 与电脑端一致：用户允许后自动续答一轮；sendQuickText 不碰输入框草稿/附件 */
}
function _brDenyM(uid){
  var req=_blogReqRegM[uid];if(!req||req.state!=='pending')return;
  req.state='denied';_brUpdateCardsM(uid);_blogReadFeedbackM.push({fid:req.fid,text:'用户拒绝了阅读《'+req.title+'》的申请，内容未注入，请勿再次申请，除非用户主动要求'});
}
async function _getBlogReadInjectionM(cfg){
  var fid=cfg&&cfg.id||'';if(!fid)return'';
  if(!await _blogAllowedM(cfg)){
    _blogPendingReadsM=_blogPendingReadsM.filter(function(r){return r.fid!==fid});
    _blogReadFeedbackM=_blogReadFeedbackM.filter(function(r){return r.fid!==fid});
    return'';
  }
  var reads=_blogPendingReadsM.filter(function(r){return r.fid===fid}),feeds=_blogReadFeedbackM.filter(function(r){return r.fid===fid});
  _blogPendingReadsM=_blogPendingReadsM.filter(function(r){return r.fid!==fid});
  _blogReadFeedbackM=_blogReadFeedbackM.filter(function(r){return r.fid!==fid});
  if(!reads.length&&!feeds.length)return'';
  var ctx='',MAX=100000;
  if(reads.length){
    ctx+='【Blog 日志内容（用户已允许阅读；仅本轮注入，后续轮次不再携带）】';
    reads.forEach(function(r){
      var body=r.content.length>MAX?r.content.slice(0,MAX)+'\n[…超过注入上限，已截断（本段原为 '+r.content.length+' 字符）；如需后续部分，请用 <blog_read name="'+r.title+'" from="'+(MAX+1)+'"/> 重新申请，仍需用户允许]':r.content;
      ctx+='\n--- 《'+r.title+'》'+(r.range?'（第 '+r.range.from+'–'+r.range.to+' 字符，全文共 '+r.range.total+' 字符）':'（全文 '+r.total+' 字符）')+' ---\n'+body;
      if(r.range&&r.range.to<r.range.total)ctx+='\n[后续内容未注入：继续阅读请用 <blog_read name="'+r.title+'" from="'+(r.range.to+1)+'"/> 重新申请，仍需用户允许]';
    });
  }
  if(feeds.length){ctx+=(ctx?'\n\n':'')+'【Blog 阅读申请结果】';feeds.forEach(function(f){ctx+='\n- '+f.text})}
  return ctx;
}

const IBMCP={
  PROTO:'2025-03-26',
  _sess:{},
  _sv(alias){return ((_mp&&_mp.mcp.servers)||[]).find(s=>s.alias===alias)||null},
  _pickFromSSE(text){
    let out=null;
    String(text||'').split('\n').forEach(line=>{
      line=line.trim();
      if(line.indexOf('data:')!==0)return;
      const d=line.slice(5).trim();
      if(!d)return;
      try{const j=JSON.parse(d);if(j&&(j.result!==undefined||j.error!==undefined))out=j}catch(e){}
    });
    return out;
  },
  async _rpc(sv,method,params,retried){
    const id=Date.now()+Math.floor(Math.random()*1000);
    const headers={'Content-Type':'application/json','Accept':'application/json, text/event-stream'};
    if(this._sess[sv.alias])headers['Mcp-Session-Id']=this._sess[sv.alias];
    let svq=sv;try{const kq=MCP_KEY_IN_URL.find(k=>k.re.test(String(sv.url||'')));if(kq&&sv.token&&!(new RegExp('[?&]'+kq.p+'=')).test(String(sv.url||''))){svq=Object.assign({},sv,{url:sv.url+(sv.url.indexOf('?')===-1?'?':'&')+kq.p+'='+encodeURIComponent(String(sv.token).replace(/^bearer\s+/i,'').trim())})}}catch(e){}
      if(sv.token&&svq===sv)headers['Authorization']=(/^bearer\s/i.test(sv.token)?sv.token:'Bearer '+sv.token);/* v131 需求③：官方 MCP 鉴权 */
    const tmo=method==='tools/call'?60000:20000;/* v131-p：联网搜索 / 抓网页一次常要十几秒，tools/call 放宽到 60s；握手与列工具仍 20s */
    const res=await this._post(svq,headers,{jsonrpc:'2.0',id:id,method:method,params:params||{}},tmo);
    if((res.status===404||res.status===400)&&this._sess[sv.alias]&&!retried){
      delete this._sess[sv.alias];
      await this._init(sv);
      return this._rpc(sv,method,params,true);
    }
    const sid=res.headers.get('Mcp-Session-Id');
    if(sid)this._sess[sv.alias]=sid;
    const raw=await res.text();
    if(!res.ok)throw new Error('HTTP '+res.status+' · '+raw.slice(0,120));
    let j=null;
    try{j=JSON.parse(raw)}catch(e){j=this._pickFromSSE(raw)}
    if(!j)throw new Error('响应无法解析');
    if(j.error)throw new Error(j.error.message||'服务器返回错误');
    return j.result;
  },

  _proxyFor(u){var p='';try{p=String((_mp&&_mp.mcp&&_mp.mcp.proxy)||'').trim()}catch(e){}if(!p)return'';if(p.indexOf('{url}')>=0)return p.replace('{url}',encodeURIComponent(u));return p+encodeURIComponent(u)},
  async _post(sv,headers,bodyObj,tmo){
    var ac=new AbortController();var tmr=setTimeout(function(){ac.abort()},tmo);
    try{
      var res=await fetch(sv.url,{method:'POST',headers:headers,signal:ac.signal,body:JSON.stringify(bodyObj)});
      clearTimeout(tmr);return res;
    }catch(err){
      clearTimeout(tmr);
      if(err&&err.name==='AbortError')throw new Error('超时');
      var px=this._proxyFor(sv.url);
      if(px){
        var ac2=new AbortController();var tmr2=setTimeout(function(){ac2.abort()},tmo);
        try{var res2=await fetch(px,{method:'POST',headers:headers,signal:ac2.signal,body:JSON.stringify(bodyObj)});clearTimeout(tmr2);return res2}
        catch(e2){clearTimeout(tmr2);throw new Error(e2&&e2.name==='AbortError'?'超时（跨域中转）':'网络错误：直连与跨域中转均未通（'+String((e2&&e2.message)||e2).slice(0,80)+'）')}
      }
      throw new Error('网络错误（可能是 CORS 未放行）'+(/mcp\.mcd\.cn|lkcoffee\.com/i.test(String(sv.url||''))?'：麦当劳 / 瑞幸官方端点未对浏览器放行跨域，浏览器无法直连——请在 MCP 卡「跨域中转」栏填自建转发后重试（部署方法见 GUIDE → DIY）':''));/* v145-p：#3 提示词浏览器版 */
    }
  },
  async _init(sv){
    await this._rpc(sv,'initialize',{protocolVersion:this.PROTO,capabilities:{},clientInfo:{name:'InternalBeyond-Mobile',version:'2'}});
    try{
      const headers={'Content-Type':'application/json'};
      if(this._sess[sv.alias])headers['Mcp-Session-Id']=this._sess[sv.alias];
      if(sv.token)headers['Authorization']=(/^bearer\s/i.test(sv.token)?sv.token:'Bearer '+sv.token);/* v131 需求③：官方 MCP 鉴权 */
      await this._post(sv,headers,{jsonrpc:'2.0',method:'notifications/initialized'},15000);/* v143-p：#1 通知同走统一传输层 */
    }catch(e){}
  },
  async connect(sv){
    delete this._sess[sv.alias];
    await this._init(sv);
    const tools=[];let cursor=null,page=0;
    do{
      const r=await this._rpc(sv,'tools/list',cursor?{cursor:cursor}:{});
      ((r&&r.tools)||[]).forEach(t=>{
        const old=(sv.tools||[]).find(x=>x.name===t.name);
        tools.push({name:t.name,description:String(t.description||'').slice(0,6000)/* v147-p：#1 已连服务器需重连一次刷新落库描述 */,inputSchema:t.inputSchema||null,enabled:old?old.enabled!==false:true});
      });
      cursor=(r&&r.nextCursor)||null;page++;
    }while(cursor&&page<20&&tools.length<200);
    sv.tools=tools;sv.status='ok';sv.lastConnect=Date.now();
    return tools.length;
  },
  _extract(result){
    let text='';
    (((result&&result.content))||[]).forEach(b=>{
      if(!b)return;
      if(b.type==='text'&&b.text)text+=(text?'\n':'')+b.text;
      else if(b.type==='resource'&&b.resource&&b.resource.text)text+=(text?'\n':'')+b.resource.text;
      else if(b.type==='image')text+=(text?'\n':'')+'[图片返回]';
    });
    try{if(result&&result.structuredContent!==undefined&&result.structuredContent!==null){
      var sc9=typeof result.structuredContent==='string'?result.structuredContent:JSON.stringify(result.structuredContent);
      if(sc9&&sc9!=='null'&&sc9!=='{}'&&text.indexOf(sc9)===-1)text=(text?text+'\n':'')+sc9;
    }}catch(e){}
    return _ibCut(text,20000);
  },
  async call(fullName,args){
    const mm=String(fullName||'').match(/^mcp\.([\w-]+)\.(.+)$/i);
    if(!mm)return{ok:false,detail:'工具名格式应为 mcp.别名.工具名'};
    await loadMP();
    const sv=this._sv(mm[1]);
    if(!sv)return{ok:false,detail:'未找到别名为「'+mm[1]+'」的 MCP 服务器'};
    if(sv.enabled===false||_mp.mcp.enabled===false)return{ok:false,detail:'MCP 当前处于停用状态'};
    const tool=(sv.tools||[]).find(t=>t.name===mm[2]);
    if(tool&&tool.enabled===false)return{ok:false,detail:'该工具已被禁用'};
    try{
      if(!this._sess[sv.alias])await this._init(sv);
      const r=await this._rpc(sv,'tools/call',{name:mm[2],arguments:args||{}});
      const tx=this._extract(r);
      const bad=r&&r.isError;
      return{ok:!bad,detail:tx||(bad?'调用失败':'（无文本返回）')};
    }catch(err){
      return{ok:false,detail:String((err&&err.message)||err).slice(0,300)};
    }
  }
};

/* ── 引用 / 选择消息 / 封档线 / 生成记忆 ── */
let _quote=null,_selMode=false;const _selIds=new Set();

const PRES_KEY='ibm_lastActive';
let _presGap=null;
function _presTouch(){try{localStorage.setItem(PRES_KEY,String(Date.now()))}catch(e){}}
async function _presCheck(){
  let last=0;try{last=parseInt(localStorage.getItem(PRES_KEY))||0}catch(e){}
  _presTouch();
  if(!last)return;
  if(!_activeCfg||_activeCfg._group)return;
  let ss=null;try{ss=await getSummarySettingsM()}catch(e){}
  if(!ss||!ss.welcomeEnabled)return;
  const now=Date.now(),gap=now-last;
  if(gap<((ss.welcomeInterval||2)*3600000))return;
  const h=Math.floor(gap/3600000),mi=Math.floor((gap%3600000)/60000);
  let dur='';if(h>0)dur+=h+' 小时';if(mi>0)dur+=(h>0?' ':'')+mi+' 分钟';
  if(!dur)dur='0 分钟';
  const d1=new Date(last),d2=new Date(now);
  const same=d1.getFullYear()===d2.getFullYear()&&d1.getMonth()===d2.getMonth()&&d1.getDate()===d2.getDate();
  const fd=d=>((d.getMonth()+1)+'月'+d.getDate()+'日');
  const ft=d=>(pad2(d.getHours())+':'+pad2(d.getMinutes()));
  _presGap={fid:_activeCfg.id,
    text:'TA在 '+(same?'':fd(d1)+' ')+ft(d1)+' 离开，'+(same?'':fd(d2)+' ')+ft(d2)+' 回来，离开了 '+dur+'。'};
}
document.addEventListener('visibilitychange',function(){
  if(document.visibilityState==='hidden')_presTouch();
  else _presCheck();
});
window.addEventListener('pagehide',_presTouch);
setTimeout(function(){_presCheck()},2500);/* 开站补一次：上次关站的时刻还留在本机 */
function setQuote(m){
  if(!m){_quote=null;$('cv-quote-bar').classList.remove('show');return}
  const name=m.role==='user'?((_about&&_about.name)||'你'):(m.senderName||(_activeCfg&&cfgName(_activeCfg))||'AI');
  _quote={name:name,text:String(m.content||'').replace(/\s+/g,' ').trim().slice(0,120)};
  $('cv-quote-t').textContent=name+'：'+_quote.text;
  $('cv-quote-bar').classList.add('show');
}
$('cv-quote-x').addEventListener('click',()=>setQuote(null));
function sealOf(cfg,thread){return thread?Number((thread&&thread.sealTimestamp)||0):Number((cfg&&cfg.sealTimestamp)||0)}
function sealTs(){return sealOf(_activeCfg,_activeThread)}
function ensureSealLine(){
  const box=convEl('cv-msgs');if(!box)return;
  const old=box.querySelector('.seal-line');if(old)old.remove();/* v174：⑧频道也画自己的封档线 */
  const ts=sealTs();if(!ts)return;
  let target=null;
  for(const m of _msgs){if((m.timestamp||0)<=ts)target=m;else break}
  if(!target)return;
  let el=box.querySelector('.m[data-id="'+target.id+'"]');if(!el)return;el=_rowOf(el);
  const d=document.createElement('div');d.className='seal-line';d.textContent=_activeThread?'封档线 · 本频道以上内容不再发送给 API':'封档线 · 以上内容不再发送给 API';
  el.after(d);
}
function selCount(){$('sel-n').textContent='已选 '+_selIds.size}
function setSelMode(on){
  _selMode=!!on;_selIds.clear();
  convEl('conv').classList.toggle('sel-mode',_selMode);
  convEl('cv-msgs').querySelectorAll('.m.selected').forEach(el=>el.classList.remove('selected'));
  selCount();
}
convEl('cv-msgs').addEventListener('click',e=>{
  if(!_selMode)return;
  const el=e.target.closest('.m');if(!el||!el.dataset.id)return;
  e.preventDefault();e.stopPropagation();
  const id=el.dataset.id;
  if(_selIds.has(id)){_selIds.delete(id);el.classList.remove('selected')}
  else{_selIds.add(id);el.classList.add('selected')}/* v202-p：选择不设上限 */
  selCount();
},true);
$('sel-cancel').addEventListener('click',()=>setSelMode(false));
$('sel-del').addEventListener('click',async()=>{
  if(!_selIds.size){toast('先选择消息');return}
  if(!await confirmDlg('删除选中的 '+_selIds.size+' 条消息？','删除'))return;
  const ids=[..._selIds];
  try{for(const _mid9 of ids){const _mm9=_msgs.find(x=>x.id===_mid9);if(_mm9&&_mm9.callEnd)await _ibclUnfoldOnDelM(_mm9)}}catch(e){}/* v167-p ①：批删含结束卡时同样解除 */
  try{await dbDeleteMany('chatMessages',ids)}catch(e){toast('删除失败');return}
  _msgs=_msgs.filter(m=>!_selIds.has(m.id));
  setSelMode(false);drawConv();toast('已删除');
});
$('sel-seal').addEventListener('click',async()=>{
  const cfg=_activeCfg;if(!cfg)return;
  if(cfg._group){toast('群聊暂不支持封档线');return}
  const thr=_activeThread,tgt=thr||cfg,store=thr?'chatThreads':'apiConfigs',sumKey='sum_'+(thr?thr.id:cfg.id);
  if(_sendKeys.has(_keyOf(cfg.id,thr?thr.id:''))){toast('等这轮回复结束再调整封档线');return}
  if(_selIds.size===0){
    if(!sealTs()){toast('选中一条消息作为封档截止点');return}
    if(!await confirmDlg(thr?'解除本频道的封档线？此后本频道全部历史重新参与发送。':'解除封档线？此后全部历史重新参与发送。','解除'))return;
    delete tgt.sealTimestamp;
    try{await dbPut(store,tgt)}catch(e){toast('保存失败');return}
    try{await dbDelete('chatSummaries',sumKey)}catch(e){}
    ensureSealLine();setSelMode(false);toast('已解除封档');return;
  }
  if(_selIds.size!==1){toast('封档只能选择一条消息');return}
  const m=_msgs.find(x=>_selIds.has(x.id));if(!m)return;
  tgt.sealTimestamp=m.timestamp||Date.now();
  try{await dbPut(store,tgt)}catch(e){toast('保存失败');return}
  try{await dbDelete('chatSummaries',sumKey)}catch(e){}
  ensureSealLine();setSelMode(false);toast(thr?'已封档：本频道该消息及之前不再发送':'已封档：该消息及之前不再发送');
});
async function _moveMsgsToThreadM(cfg,ids,t){
  const set=new Set(ids),src=_activeThread?_activeThread.id:'';let n=0;
  for(const id of ids){let m=_msgs.find(x=>x.id===id);if(!m){try{m=await dbGet('chatMessages',id)}catch(e){m=null}}if(!m||m.friendId!==cfg.id)continue;m.threadId=t.id;try{await dbPut('chatMessages',m);n++}catch(e){}}
  _msgs=_msgs.filter(m=>!set.has(m.id));
  if(n){try{await dbDelete('chatSummaries','sum_'+(src||cfg.id))}catch(e){}}
  return n;
}
$('sel-move').addEventListener('click',()=>{
  const cfg=_activeCfg;if(!cfg)return;
  if(cfg._group){toast('群聊没有话题频道');return}
  if(!_selIds.size){toast('先选择要搬走的消息');return}
  if(_sendKeys.has(_keyOf(cfg.id,_activeThread?_activeThread.id:''))){toast('等这轮回复结束再搬');return}
  const ids=[..._selIds];openThreadEdit(null);_theMoveIds=ids;$('the-title').textContent='移到新频道（'+ids.length+' 条）';
});
$('sel-mem').addEventListener('click',()=>{
  if(_selIds.size<2){toast('至少选择 2 条消息');return}
  const list=_msgs.filter(m=>_selIds.has(m.id));
  setSelMode(false);
  saveMemoryFrom(list);
});

