let _grpEdit=null,_grpSel=new Set(),_grpSil=new Set(),_grpAva='';/* v62-m t8：群头像暂存（保存时写 mobilePrefs.groupAva） */
function _grpChips(){
  const mb=$('grp-members'),sb=$('grp-silent');
  mb.innerHTML='';sb.innerHTML='';
  _cfgs.forEach(c=>{
    const ch=document.createElement('div');ch.className='th-chip'+(_grpSel.has(c.id)?' on':'');ch.textContent=cfgName(c);
    ch.addEventListener('click',()=>{
      if(_grpSel.has(c.id)){_grpSel.delete(c.id);_grpSil.delete(c.id)}else _grpSel.add(c.id);
      _grpChips();
    });
    mb.appendChild(ch);
  });
  const mems=_cfgs.filter(c=>_grpSel.has(c.id));
  if(!mems.length){sb.innerHTML='<p class="hint" style="margin:0">先选择成员。</p>';return}
  mems.forEach(c=>{
    const ch=document.createElement('div');ch.className='th-chip'+(_grpSil.has(c.id)?' on':'');ch.textContent=cfgName(c);
    ch.addEventListener('click',()=>{if(_grpSil.has(c.id))_grpSil.delete(c.id);else _grpSil.add(c.id);_grpChips()});
    sb.appendChild(ch);
  });
}
