  g.thinkingEnabled=$('grp-think').classList.contains('on');
  g.director=$('grp-dir').classList.contains('on');g.shuffle=$('grp-shuf').classList.contains('on');g.idleMin=$('grp-idle').classList.contains('on')?5:0;/* 手机端 */
