$('grp-del').addEventListener('click',async()=>{
  if(!_grpEdit)return;
  const g=_grpEdit;
  if(!await confirmDlg('删除群聊「'+(g.name||'')+'」？聊天记录将一并删除。','删除'))return;
  try{
    await dbDelete('groups',g.id);
    const arr=await dbGetByIndex('chatMessages','byFriend',g.id);
    await dbDeleteMany('chatMessages',arr.map(m=>m.id));
    try{await dbDelete('chatSummaries','sum_'+g.id)}catch(e){}
    try{await loadMP();if(_mp.groupAva&&_mp.groupAva[g.id]){delete _mp.groupAva[g.id];await saveMP()}}catch(e){}
  }catch(e){toast('删除失败');return}
  closeSheets();
  if(_activeCfg&&_activeCfg._group&&_activeCfg._group.id===g.id)convEl('conv').classList.remove('open');
  renderFriends();toast('已删除');
});
function collapseSameRoleM(msgs){
  const out=[];
  msgs.forEach(m=>{
    const _hi=!!(Array.isArray(m.images)&&m.images.length);
    if(out.length&&out[out.length-1].role===m.role&&!_hi&&!(out[out.length-1].images&&out[out.length-1].images.length))out[out.length-1].content+='\n\n'+m.content;
    else out.push(_hi?{role:m.role,content:m.content,images:m.images}:{role:m.role,content:m.content});/* 手机端：带图消息不合并、图片随行（与 buildHist 同口径） */
  });
  while(out.length&&out[0].role!=='user')out.shift();
  return out;
}
function sanitizeGroupReply(text,selfName){
  let t=String(text||'');
  const esc1=selfName.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  t=t.replace(new RegExp('^\\s*\\['+esc1+'\\]\\s*'),'');
  t=t.replace(new RegExp('^\\s*'+esc1+'\\s*[:：]\\s*'),'');
  return t;
}
