  byLen9.forEach(function(c){var n=cfgName(c)||'';if(!n)return;var at=scan9.indexOf('@'+n);if(at<0)at=scan9.indexOf('＠'+n);var i=at;if(i<0&&n.length>=2)i=scan9.indexOf(n);if(i<0)return;var hl9=(at>=0&&i===at)?n.length+1:n.length;scan9=scan9.slice(0,i)+new Array(hl9+1).join('\u0000')+scan9.slice(i+hl9);if(!sil.has(c.id)||at>=0)men.push({c:c,i:i})});
