const MEM_FIELD_KEYS_M=['标题','概括','内容','领域','标签','效价','唤醒度','重要性','是否已解决','可见性'];
function parseMemoryFieldsM(resp){/* 与电脑端 parseMemoryFields 逐字同源 */
  const out={};
  if(!resp)return out;
  const hits=[];
  MEM_FIELD_KEYS_M.forEach(k=>{
    const re=new RegExp('(^|\\n)\\s*'+k+'\\s*[：:]');
    const m=re.exec(resp);
    if(m)hits.push({key:k,valStart:m.index+m[0].length,labelStart:m.index});
  });
  hits.sort((a,b)=>a.labelStart-b.labelStart);
  hits.forEach((h,i)=>{
    const end=i+1<hits.length?hits[i+1].labelStart:resp.length;
    out[h.key]=resp.slice(h.valStart,end).trim();
  });
  return out;
}
async function _ibGenMemCore(cfg,userText,sysTail,meta){
  meta=meta||{};
  const aiN=cfgName(cfg);
  const sys=String(sysTail||'').trim()
    +'\n\n【输出格式要求（严格按字段逐行输出，不要输出其他内容，不要用代码块围栏）】\n'
    +'标题：（这段记忆的名字，像日记标题一样自然，15字以内）\n'
    +'概括：（一两句话，这段内容意味着什么，50字以内）\n'
    +'内容：（100-300字。以'+aiN+'的视角回忆——发生了什么、有什么触动的瞬间或变化。用名字称呼，不要用代词。）\n'
    +'领域：（从"情感""日常""创作""思考"中选一个）\n'
    +'标签：（2-4个关键词，逗号分隔）\n'
    +'效价：（0-1之间的数字，可精确到两位小数；0=消极，1=积极）\n'
    +'唤醒度：（0-1之间的数字，0=平静，1=激烈）\n'
    +'重要性：（1-10之间的整数）\n'
    +'是否已解决：（是/否）\n'
    +'可见性：（"公开"或"私密"——涉及亲密、身体、私人情感等内容应选私密）';
  const test=Object.assign({},cfg,{streaming:false,thinkingEnabled:false,promptCache:false});
  const r=await callAI(test,[{role:'user',content:userText}],sys,()=>{},null,null);
  let raw=String((r&&typeof r==='object')?(r.t||''):(r||''));
  if(!raw.trim()&&r&&r.k)raw=String(r.k);/* 个别中转把正文塞进 reasoning_content（k）：正文为空时回捞思考段 */
  raw=raw.replace(/```[a-zA-Z]*[ \t]*/g,'').trim();
  if(!raw)throw new Error('返回为空'+((r&&r.fin)?('（finish='+r.fin+'）'):''));
  const fields=parseMemoryFieldsM(raw);const get=k=>fields[k]||'';
  const title=(get('标题')||meta.titleFallback||'记忆').replace(/^[「『"“']+|[」』"”']+$/g,'');
  const sm0=get('概括');
  const content=get('内容')||raw.slice(0,300);
  const domain=['情感','日常','创作','思考'].find(d=>get('领域').includes(d))||(meta.domainFallback||'日常');
  const tags=(get('标签')||'').split(/[,，、]/).map(t=>t.trim()).filter(Boolean);
  const valence=(v=>isNaN(v)?0.5:Math.max(0,Math.min(1,v)))(parseFloat(get('效价')));
  const arousal=(v=>isNaN(v)?0.3:Math.max(0,Math.min(1,v)))(parseFloat(get('唤醒度')));
  const _v0=meta.forceVisibility||(get('可见性').includes('私密')?'private':'all'),_so=(_v0==='private');
  const mem={
    id:'mem_'+Date.now()+'_'+Math.floor(Math.random()*10000),
    title:String(title).slice(0,40),
    oneLine:'',
    summary:(String(sm0).trim()||(String(content).replace(/\s+/g,' ').match(/^[^。！？!?\n]*[。！？!?]?/)||[''])[0].trim()).slice(0,100),
    content:String(content).slice(0,600),
    domain:domain,
    tags:tags.slice(0,4).map(t=>String(t).slice(0,12)),
    importance:Math.max(1,Math.min(10,parseInt(get('重要性'))||5)),
    valence:valence,
    arousal:arousal,
    pinned:false,resolved:get('是否已解决').includes('是'),
    visibility:_so?'only':_v0,visibleTo:_so?[cfg.id]:[],excludeFrom:[],/* 手机端：#1 通话记忆强制私密 */
    rawSource:meta.rawSource||'chat',sourceId:meta.sourceId||'',activationCount:0,
    created:Date.now(),lastActivated:Date.now(),
    createdBy:cfg.id,createdByName:cfgName(cfg),editedByUser:false
  };
  await dbPut('memories',mem);
  try{if(document.querySelector('#page-memory.active'))renderMemLib()}catch(e){}
  return mem;
}
async function saveMemoryFrom(list){
  const cfg0=_activeCfg;let cfg=cfg0;if(!cfg)return;
  const isGroup=!!cfg._group;
  if(isGroup){
    const util=pickGroupUtilCfg(cfg._group);
    if(!util){toast('群内没有可用的 API 成员');return}
    cfg=util;
  }
  if(!cfg.apiKey){toast('该 API 未配置 Key');return}
  await loadMP();
  const pa=mpAi(cfg);
  
  const cap=Math.max(2,Math.min(50,parseInt(isGroup?pa.grpLimit:pa.histLimit,10)||(isGroup?30:40)));
  const seal=isGroup?0:sealOf(cfg0,_activeThread);/* v174：⑧频道用自己的封档线 */
  let src=list;
  if(!src){
    src=_msgs.filter(m=>(m.timestamp||0)>seal).slice(-cap);
    if(src.length<2){toast('聊天记录太少，无法生成记忆');return}
  }else{
    const kept=src.filter(m=>(m.timestamp||0)>seal);
    if(kept.length!==src.length){toast('选中内容包含封档线之前的消息，已阻止发送');return}
    src=kept.slice(-50);
    if(src.length<2){toast('选中的消息太少');return}
  }
  src=src.slice().sort((a,b)=>(a.timestamp||0)-(b.timestamp||0));
  const userName=(_about&&_about.name)||'用户';
  const aiName=cfgName(cfg);
  
  let ls=src.map(m=>{
    const speaker=m.role==='user'?userName:(isGroup?(m.senderName||aiName):aiName);
    let t=String(m.content||'').trim();
    if(!t&&m.voice)t=String((m.voice.transcript||'')).trim()||'（语音消息）';
    if(m.gift)return _giftLineM(m);/* 手机端 */
    return speaker+'：'+t.slice(0,300);
  });
  let transcript=ls.join('\n');
  while(ls.length>2&&transcript.length>4000){ls.shift();transcript=ls.join('\n')}/* 超预算丢最旧、保最近（电脑端保头，此处修正为保最近） */
  if(transcript.length>4200)transcript=transcript.slice(-4200);
  let context='';
  if(cfg.systemPrompt)context+='【AI的人设背景】'+String(cfg.systemPrompt).slice(0,500)+'\n\n';
  if(cfg.relationship)context+='【与用户的关系】'+String(cfg.relationship).slice(0,200)+'\n\n';
  const userText=context+(list?'【选中的对话记录】':'【对话记录】')+'\n'+transcript;
  
  const task='你正在为你和'+userName+'之间的记忆库写下一条新的记忆。\n'
    +'写作规则：用「'+aiName+'」来称呼你自己，用「'+userName+'」来称呼对方。不要使用"我""你""对方""用户"这类代词——因为这条记忆可能会被其他人读到，只有使用名字才不会产生混淆。\n'
    +'写的时候像在翻开一页日记，而不是在做会议纪要。你是这段经历的参与者，不是旁观者。';
  toast('正在生成记忆…');
  try{
    const mem=await _ibGenMemCore(cfg,userText,task,{rawSource:'chat',sourceId:(cfg0&&cfg0.id)||cfg.id,titleFallback:'来自对话的记忆',grp:isGroup});
    toast((list?'记忆已从选中的消息中生成：':'记忆已从对话中生成：')+mem.title);
  }catch(e){toast('生成记忆失败：'+String((e&&e.message)||e).slice(0,80))}
}

/* ═══════════ Auto Memory：注入块与标签执行（移植电脑版）═══════════ */
function _amFmtEntry(e){return '['+(e.category||'personal_context')+'] (id:'+e.id+') '+(e.content||'')}/* v90-m 拍板③：条目行统一为电脑端格式（原始英文分类键名） */
function _amUserName(){return (_about&&_about.name)||'用户'}
function _amInstrBlock(cfg){/* v90-m 拍板③：指令措辞统一为电脑端版本（与电脑端逐字同文）；开 automem 的会话冷启动一次缓存 */
  const u=_amUserName();
  if(cfg.amRecordOnly){
    return '【记忆系统 · 静默模式】\n'
      +'你可以为'+u+'维护长期记忆档案。当前为静默模式：不注入已有档案。\n'
      +'仅当'+u+'明确要求你记住某事时，才使用以下标签写入（系统拦截执行，对方可见卡片通知）：\n'
      +'<mem_create category="分类" priority="优先级">记忆内容</mem_create>\n'
      +'分类：work_context｜personal_context｜top_of_mind｜brief_history｜long_term_background｜user_instructions\n'
      +'优先级：always｜normal｜low\n'
      +'未收到明确指示时不执行任何记忆操作。';
  }
  return '【记忆系统】\n'
    +'你可以维护一份关于'+u+'的长期记忆档案。在回复正文中插入以下标签即可操作（系统会自动拦截执行，标签本身不会显示给对方）：\n'
    +'<mem_create category="分类" priority="优先级">记忆内容</mem_create>\n'
    +'<mem_update id="条目id">修改后的完整内容</mem_update>\n'
    +'<mem_delete id="条目id"/>\n'
    +'分类：work_context｜personal_context｜top_of_mind（近期关注，过时即更新）｜brief_history｜long_term_background（仅限反复呈现的模式）｜user_instructions（仅限对方的明确指令）。\n'
    +'优先级：always（核心事实，全档≤3条）｜normal｜low（仅相关时浮现）。\n'
    +'写入原则：提炼而非转录，1~3句独立可读。不写闲聊、不稳定的情绪表态、重复信息。每轮至多3次操作，多数对话无需操作。\n'
    +'档案对'+u+'完全可见且可编辑。遇到过时记忆时自行修正或删除。';
}
function _amScore(content,keywords){if(!keywords||!keywords.length)return 0;const low=String(content||'').toLowerCase();let s=0;keywords.forEach(k=>{if(k&&low.indexOf(String(k).toLowerCase())!==-1)s++});return s}
function _extractKeywords(text){
  if(!text)return[];
  const keywords=[];
  const cleaned=String(text).replace(/[\[\]()（）【】「」《》、，。！？；：\s]/g,' ').trim();
  const enWords=cleaned.match(/[a-zA-Z]{3,}/g);if(enWords)enWords.forEach(w=>keywords.push(w.toLowerCase()));
  const zhOnly=cleaned.replace(/[a-zA-Z0-9\s]+/g,'');
  for(let i=0;i<zhOnly.length-1;i++){keywords.push(zhOnly.slice(i,i+2));if(i<zhOnly.length-2)keywords.push(zhOnly.slice(i,i+3))}
  return[...new Set(keywords)];
}
const AM_BUDGET_MAX=6000;/* v209-p：Auto Memory 档案字数上限（与电脑端同值） */
async function buildAmBlocks(cfg,queryText){
  const out={sys:'',tail:''};
  if(!amEnabled(cfg))return out;
  out.sys=_amInstrBlock(cfg);
  if(cfg.amRecordOnly)return out;
  const entries=await amGetEntries(cfg.id);
  if(!entries.length){out.tail='【记忆档案（共 0 条，勿向对方复述此段）】\n（目前为空）';out.dyn=out.tail;return out}
  const mode=cfg.autoMemMode||'hybrid';
  const budget=Math.max(300,Math.min(AM_BUDGET_MAX,parseInt(cfg.autoMemBudget)||1200));
  const kws=_extractKeywords(queryText);
  const head='【记忆档案（共 '+entries.length+' 条，勿向对方复述此段）】';
  let tail=head,used=head.length,stableT='',dynT='';
  const lineOf=e=>'\n'+_amFmtEntry(e);
  const append=(e,where)=>{const line=lineOf(e);if(used+line.length>budget)return false;tail+=line;used+=line.length;if(where==='s')stableT+=line;else dynT+=line;return true};
  const score=e=>_amScore((e.content||'')+' '+(e.category||''),kws);
  const recent=(a,b)=>((b.updated||b.created||0)-(a.updated||a.created||0));
  const always=entries.filter(e=>e.priority==='always').sort(recent).slice(0,3);
  const rest=entries.filter(e=>e.priority!=='always');

  if(mode==='retrieval'){
    /* Retrieval：不自动灌核心档案，只给当前话题确实命中的条目。 */
    const hit=entries.map(e=>({e:e,s:score(e)})).filter(x=>x.s>0)
      .sort((a,b)=>(b.s-a.s)||recent(a.e,b.e));
    for(const it of hit){if(!append(it.e,'d'))break}
  }else if(mode==='full'){
    /* Full：核心优先，其余按优先级/新旧尽量装，但绝不突破总预算。 */
    const rank={normal:1,low:2};
    const all=always.concat(rest.slice().sort((a,b)=>((rank[a.priority]??1)-(rank[b.priority]??1))||recent(a,b)));
    for(const e of all){if(!append(e,'s'))break}
  }else{
    /* Hybrid：最多 3 条核心 + 当前话题明显相关的非核心档案。 */
    for(const e of always){if(!append(e,'s'))break}
    const hit=rest.map(e=>({e:e,s:score(e)})).filter(x=>x.s>0)
      .sort((a,b)=>(b.s-a.s)||recent(a.e,b.e));
    for(const it of hit){if(!append(it.e,'d'))break}
  }
  out.tail=tail;
  out.stable=stableT?('【记忆档案 · 核心（'+(mode==='full'?'全量档案':'always 条目')+'，勿向对方复述此段）】'+stableT):'';
  out.dyn=dynT?('【记忆档案 · 本轮相关（勿向对方复述此段）】'+dynT):'';
  return out;
}
function _parseMemOps(text){
  const ops=[];if(!text)return{clean:text,ops:ops};
  const re=/<mem_(create|update|delete)\b([^>]*?)(?:\/>|>([\s\S]*?)<\/mem_\1\s*>)/gi;
  const clean=String(text).replace(re,function(_m,kind,attrStr,body){
    const attrs={};String(attrStr||'').replace(/(\w+)\s*=\s*(?:"([^"]*)"|'([^']*)'|[\u201c\u201d]([^\u201c\u201d]*)[\u201c\u201d]|([^\s>\/"'\u201c\u201d]+))/g,function(__,k,v1,v2,v3,v4){attrs[k]=(v1!==undefined?v1:v2!==undefined?v2:v3!==undefined?v3:v4)||'';return''});
    ops.push({kind:kind.toLowerCase(),attrs:attrs,body:String(body||'').trim()});
    return '';
  });
  let c=clean.replace(/\n{3,}/g,'\n\n');
  const d=c.toLowerCase().lastIndexOf('<mem_');
  if(d!==-1){const t=c.slice(d);if(t.length<900&&!/<\/mem_(create|update|delete)\s*>/i.test(t)&&!/^<mem_delete\b[^>]*\/>/i.test(t))c=c.slice(0,d).replace(/\s+$/,'')}
  return {clean:c,ops:ops};
}
async function procMemOps(cfg,m){
  if(!amEnabled(cfg))return;
  const p=_parseMemOps(m.content||'');
  if(!p.ops.length)return;
  const results=[];const MAXOPS=3;
  for(let i=0;i<p.ops.length;i++){
    const op=p.ops[i];
    if(i>=MAXOPS){results.push({ok:false,label:'已跳过多余的记忆操作',detail:'每轮最多 3 次'});continue}
    try{
      if(op.kind==='create'){
        const cat=AM_CATS[op.attrs.category]?op.attrs.category:'personal_context';
        const prio=AM_PRIOS.indexOf(op.attrs.priority)!==-1?op.attrs.priority:'normal';
        const content=(op.body||'').slice(0,800);/* 聊天里主动写入放宽到 800 */
        if(!content){results.push({ok:false,label:'记忆写入失败',detail:'内容为空'});continue}
        if(prio==='always'){
          const ex=await amGetEntries(cfg.id);
          if(ex.filter(e=>e.priority==='always').length>=3){results.push({ok:false,label:'记忆写入失败',detail:'always 条目已达 3 条上限'});continue}
        }
        const entry={id:_amNewId(),friendId:cfg.id,category:cat,priority:prio,content:content,created:Date.now(),updated:Date.now(),updatedBy:cfgName(cfg)};
        if(prio==='always'){results.push({ok:true,pending:'create',entry:entry,label:'待确认 · 写入核心记忆（always）· '+(AM_CATS[cat]||cat),detail:content});continue}/* always 级先出确认卡：核心条目进 system 缓存块、每位 TA 每轮都带，写不写由用户点 */
        await dbPut('autoMemory',entry);
        results.push({ok:true,label:'已写入记忆 · '+(AM_CATS[cat]||cat),detail:content});
      }else if(op.kind==='update'){
        const ex=await dbGet('autoMemory',op.attrs.id||'').catch(()=>null);
        if(!ex||ex.friendId!==cfg.id){results.push({ok:false,label:'记忆更新失败',detail:'未找到条目'});continue}
        const content=(op.body||'').slice(0,800);/* 聊天里主动写入放宽到 800 */
        if(!content){results.push({ok:false,label:'记忆更新失败',detail:'内容为空'});continue}
        const old=ex.content;
        if(ex.priority==='always'){results.push({ok:true,pending:'update',id:ex.id,content:content,label:'待确认 · 改动核心记忆（always）· '+(AM_CATS[ex.category]||ex.category),detail:'原：'+old+'\n新：'+content});continue}/* 改动 always 条目同样先确认 */
        Object.assign(ex,{content:content,updated:Date.now(),updatedBy:cfgName(cfg)});
        await dbPut('autoMemory',ex);
        results.push({ok:true,label:'已更新记忆 · '+(AM_CATS[ex.category]||ex.category),detail:'原：'+old+'\n新：'+content});
      }else if(op.kind==='delete'){
        const ex=await dbGet('autoMemory',op.attrs.id||'').catch(()=>null);
        if(!ex||ex.friendId!==cfg.id){results.push({ok:false,label:'记忆删除失败',detail:'未找到条目'});continue}
        await dbDelete('autoMemory',op.attrs.id);
        results.push({ok:true,label:'已删除记忆 · '+(AM_CATS[ex.category]||ex.category),detail:ex.content});
      }
    }catch(e){results.push({ok:false,label:'记忆操作异常',detail:String((e&&e.message)||e)})}
  }
  if(!results.length)return;
  m.content=p.clean;m.memOps=results;
  try{await dbPut('chatMessages',m)}catch(e){}
  redrawMsg(m);
}

async function _amPendResolve(m,r,act){if(!m||!r||!r.pending)return;var cfg=(typeof _cfgs!=='undefined'&&Array.isArray(_cfgs))?_cfgs.filter(function(c){return c&&c.id===m.friendId})[0]:null;
  try{if(r.pending==='create'){var e=r.entry;if(act==='skip'){Object.assign(r,{ok:false,label:'已放弃写入（always）',detail:e.content})}
    else{if(act==='normal')e.priority='normal';if(e.priority==='always'){var ex=await amGetEntries(e.friendId);if(ex.filter(function(x){return x.priority==='always'}).length>=3){Object.assign(r,{ok:false,label:'记忆写入失败',detail:'always 条目已达 3 条上限'});delete r.pending;delete r.entry;try{await dbPut('chatMessages',m)}catch(e){}try{redrawMsg(m)}catch(e){}return}}
      e.created=e.updated=Date.now();await dbPut('autoMemory',e);Object.assign(r,{ok:true,label:'已写入记忆 · '+(AM_CATS[e.category]||e.category)+(e.priority==='always'?'（always）':''),detail:e.content})}}
  else if(r.pending==='update'){if(act==='skip'){Object.assign(r,{ok:false,label:'未改动核心记忆',detail:r.detail})}
    else{var cur=await dbGet('autoMemory',r.id||'').catch(function(){return null});if(!cur){Object.assign(r,{ok:false,label:'记忆更新失败',detail:'条目已不在'})}
      else{Object.assign(cur,{content:r.content,updated:Date.now(),updatedBy:cfg?cfgName(cfg):(cur.updatedBy||'')});await dbPut('autoMemory',cur);Object.assign(r,{ok:true,label:'已更新记忆 · '+(AM_CATS[cur.category]||cur.category)+'（always）',detail:r.detail})}}}
  }catch(e){Object.assign(r,{ok:false,label:'记忆操作异常',detail:String((e&&e.message)||e)})}
  delete r.pending;delete r.entry;delete r.id;delete r.content;try{await dbPut('chatMessages',m)}catch(e){}try{redrawMsg(m)}catch(e){}try{if(typeof renderMemLib==='function'&&typeof currentPage!=='undefined'&&currentPage==='memory')renderMemLib()}catch(e){}}

