let _as=null,_editCfgId=null,_lastProv='anthropic';
const provSel=$('aset-provider');
Object.keys(PROVIDERS).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=PROVIDERS[k].name;provSel.appendChild(o)});
provSel.addEventListener('change',()=>{
  const prev=PROVIDERS[_lastProv]||{},nx=PROVIDERS[provSel.value]||{};
  const ep=$('aset-endpoint'),md=$('aset-model');
  if(!ep.value.trim()||ep.value.trim()===prev.endpoint)ep.value=nx.endpoint||'';
  if(!md.value.trim()||md.value.trim()===prev.model)md.value=nx.model||'';
  sw2($('aset-vision'),!!nx.vision);
  _lastProv=provSel.value;
});

function _modelListReq(prov,endpoint,key){
  var ep=String(endpoint||'').trim().replace(/\/+$/,'');
  var H={};
  if(prov==='gemini'||/generativelanguage\.googleapis\.com/i.test(ep)){
    var gb=ep.replace(/\/models(\/.*)?$/i,'');if(!/\/v\d+[a-z]*$/i.test(gb))gb='https://generativelanguage.googleapis.com/v1beta';
    if(key)H['x-goog-api-key']=key;
    return{url:gb+'/models?pageSize=500',headers:H,kind:'gemini'};
  }
  if(prov==='anthropic'||/api\.anthropic\.com/i.test(ep)){
    var ab=ep.replace(/\/v1\/messages.*$/i,'');if(!ab)ab='https://api.anthropic.com';
    if(key)H['x-api-key']=key;H['anthropic-version']='2023-06-01';H['anthropic-dangerous-direct-browser-access']='true';
    return{url:ab+'/v1/models?limit=1000',headers:H,kind:'anthropic'};
  }
  var ob=ep.replace(/\/(chat\/completions|completions|messages|text\/chatcompletion_v2|responses)(\?.*)?$/i,'');
  if(!ob)return null;
  ob=ob.replace(/\/models$/i,'');
  if(!/\/v\d+[a-z]*$/i.test(ob))ob+='/v1';
  if(key)H['Authorization']='Bearer '+key;
  return{url:ob+'/models',headers:H,kind:'openai'};
}

function _epTidyM(s){
  s=String(s||'').replace(/\s+/g,'');if(!s)return '';
  if(!/^https?:\/\//i.test(s))s='https://'+s.replace(/^\/+/,'');
  s=s.replace(/^(https?:\/\/)\/+/i,'$1').replace(/([^:])\/{2,}/g,'$1/').replace(/\/+$/,'');
  if(/\/messages(\?.*)?$|generateContent|\/(chat\/)?completions(\?.*)?$|\/responses(\?.*)?$|chatcompletion_v2/i.test(s))return s;
  if(/\/chat$/i.test(s))return s+'/completions';
  var o='';try{o=new URL(s).origin}catch(e){return s}
  var path=s.slice(o.length);
  if(!path)return s+'/v1/chat/completions';
  if(/\/v\d+[a-z]*$/i.test(path))return s+'/chat/completions';
  return s;
}
function _cfgFmtM(cfg){
  var p=PROVIDERS[cfg&&cfg.provider]||PROVIDERS.custom;
  if(!cfg||cfg.provider!=='custom')return p.format||'openai';
  var ep=String(cfg.endpoint||'');
  if(/\/messages(\?.*)?$/i.test(ep))return 'anthropic';
  if(/generateContent|generativelanguage\.googleapis\.com/i.test(ep))return 'gemini';
  return 'openai';
}
var _MODEL_FAM_ORDER=['Claude','GPT / OpenAI','Gemini','DeepSeek','Qwen 通义','GLM 智谱','Kimi','Doubao 豆包','Grok','Llama','Mistral','其他','非对话 / 其他用途'];
function _modelFamilyM(id){var s=String(id||'').toLowerCase();
  if(/embed|rerank|whisper|\btts\b|tts-|-tts|moderation|dall-e|image|audio|transcri|realtime|sora|veo|imagen|flux|diffusion|seedream|seedance|speech|voice|\bocr\b/.test(s))return '非对话 / 其他用途';
  if(/claude/.test(s))return 'Claude';
  if(/^(gpt|o\d|chatgpt|text-davinci|openai)/.test(s)||/gpt-/.test(s))return 'GPT / OpenAI';
  if(/gemini|gemma/.test(s))return 'Gemini';
  if(/deepseek/.test(s))return 'DeepSeek';
  if(/qwen|qwq|qvq/.test(s))return 'Qwen 通义';
  if(/glm|codegeex/.test(s))return 'GLM 智谱';
  if(/kimi|moonshot/.test(s))return 'Kimi';
  if(/doubao|\bseed\b|seed-/.test(s))return 'Doubao 豆包';
  if(/grok/.test(s))return 'Grok';
  if(/llama/.test(s))return 'Llama';
  if(/mistral|mixtral|codestral|ministral|magistral/.test(s))return 'Mistral';
  return '其他'}
function _modelListReqCustom(endpoint,key){
  var ep=_epTidyM(endpoint);if(!ep)return [];
  var o='';try{o=new URL(ep).origin}catch(e){return []}
  var path=ep.slice(o.length);
  var isAnth=/\/messages(\?.*)?$/i.test(path),isGem=/generateContent|\/v1beta\b/i.test(path);
  var base=path.replace(/\/(chat\/completions|completions|messages|responses|text\/chatcompletion_v2|embeddings)(\?.*)?$/i,'').replace(/\/models(\/[^\/]*)?(:[a-z]+)?$/i,'').replace(/\/+$/,'');
  var verB=/\/v\d+[a-z]*$/i.test(base)?base:'';
  var ver1=verB||(base+'/v1');
  var HB={},HA={'anthropic-version':'2023-06-01'},HG={};
  if(key){HB['Authorization']='Bearer '+key;HA['x-api-key']=key;HG['x-goog-api-key']=key}
  var L=[],seen={};
  var add=function(u,h,kind){var sig=kind+'|'+u+'|'+JSON.stringify(h);if(seen[sig])return;seen[sig]=1;L.push({url:o+u,headers:h,kind:kind})};
  var oa=function(){add(ver1+'/models',HB,'openai');if(base&&base!==ver1)add(base+'/models',HB,'openai');add('/v1/models',HB,'openai')};
  var an=function(){var ab=verB||'/v1';add(ab+'/models?limit=1000',HA,'anthropic');add(ab+'/models?limit=1000',Object.assign({'anthropic-version':'2023-06-01'},HB),'anthropic');add('/v1/models?limit=1000',HA,'anthropic')};
  var ge=function(){var gb=/\/v1beta$/i.test(base)?base:(verB?verB.replace(/\/v\d+[a-z]*$/i,'/v1beta'):(base+'/v1beta'));add(gb+'/models?pageSize=500',HG,'gemini');if(key)add(gb+'/models?pageSize=500&key='+encodeURIComponent(key),{},'gemini');add('/v1beta/models?pageSize=500',HG,'gemini')};
  if(isAnth){an();oa();ge()}else if(isGem){ge();oa();an()}else{oa();an();ge()}
  add('/api/pricing',{},'newapi');
  return L;
}
function _modelListParse(kind,j){
  var out=[];
  var push=function(id,name){id=String(id||'').trim();if(!id)return;out.push({id:id,name:String(name||'').trim()})};
  if(kind==='gemini'){((j&&j.models)||[]).forEach(function(m){if(!m)return;var ok=!m.supportedGenerationMethods||m.supportedGenerationMethods.indexOf('generateContent')!==-1;if(ok)push(String(m.name||'').replace(/^models\//,''),m.displayName)})}
  else{
    var arr=null;
    if(Array.isArray(j))arr=j;
    else if(j&&typeof j==='object'){
      var cand=[j.data,j.models,j.result,j.model_list,j.items,j.list];
      for(var ci=0;ci<cand.length&&!arr;ci++){var c=cand[ci];if(Array.isArray(c))arr=c;else if(c&&typeof c==='object'){if(Array.isArray(c.data))arr=c.data;else if(Array.isArray(c.models))arr=c.models}}
      if(!arr&&j.data&&typeof j.data==='object'&&!Array.isArray(j.data)){arr=Object.keys(j.data).map(function(k){var v=j.data[k];return(v&&typeof v==='object')?Object.assign({id:k},v):k})}
    }
    (arr||[]).forEach(function(m){if(typeof m==='string')push(m,'');else if(m&&typeof m==='object')push(m.id||m.model_name||m.name||m.model,m.display_name||m.displayName||'')});
  }
  var seen={};out=out.filter(function(m){if(seen[m.id])return false;seen[m.id]=1;return true});
  out.sort(function(a,b){return a.id.localeCompare(b.id)});
  return out;
}
function _modelListReset(){try{var qq=$('aset-models-q');if(qq){qq.style.display='none';qq.value=''}var w=$('aset-models-wrap');if(w)w.style.display='none';var s=$('aset-models');if(s)s.innerHTML='<option value="">— 选择模型 —</option>';var h=$('aset-models-hint');if(h){h.style.display='none';h.textContent=''}}catch(e){}}
(function _modelListWire(){
  var btn=$('aset-models-fetch'),sel=$('aset-models'),wrap=$('aset-models-wrap'),hint=$('aset-models-hint'),q=$('aset-models-q');
  if(!btn||!sel)return;
  var _busy=false,_last=[];
  function _hint(t,bad){if(!hint)return;hint.style.display=t?'':'none';hint.textContent=t||'';hint.style.color=bad?'#e08a8a':''}
  function _esc(t){return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;')}
  function _draw(list,kw){
    var cur=$('aset-model').value.trim();kw=String(kw||'').trim().toLowerCase();
    var L=kw?list.filter(function(m){return (m.id+' '+m.name).toLowerCase().indexOf(kw)!==-1}):list;
    var opt=function(m){return'<option value="'+_esc(m.id)+'"'+(m.id===cur?' selected':'')+'>'+_esc(m.id+((m.name&&m.name!==m.id)?('  ·  '+m.name):''))+'</option>'};
    var h='<option value="">— 选择模型（'+(kw?('匹配 '+L.length+' / '):'共 ')+list.length+' 个）—</option>';
    if(L.length>10){var G={},order=[];L.forEach(function(m){var f=_modelFamilyM(m.id);if(!G[f]){G[f]=[];order.push(f)}G[f].push(m)});order.sort(function(a,b){return _MODEL_FAM_ORDER.indexOf(a)-_MODEL_FAM_ORDER.indexOf(b)});h+=order.map(function(f){return'<optgroup label="'+_esc(f)+'">'+G[f].map(opt).join('')+'</optgroup>'}).join('')}
    else h+=L.map(opt).join('');
    sel.innerHTML=h;
  }
  async function _try(req,ms){/* 单次探测 → {ok,list,status,err,html,net} */
    var ac=new AbortController();var tm=setTimeout(function(){ac.abort()},ms);
    try{
      var r=await fetch(req.url,{headers:req.headers,signal:ac.signal});clearTimeout(tm);
      var tx=await r.text();var j=null;try{j=JSON.parse(tx)}catch(e){}
      var html=!j&&/^\s*<(!doctype|html)/i.test(tx);
      if(!r.ok)return{ok:false,status:r.status,html:html,err:(j&&j.error&&(j.error.message||j.error))?String(j.error.message||j.error).slice(0,80):''};
      var list=_modelListParse(req.kind,j);
      return{ok:list.length>0,list:list,status:r.status,html:html,err:list.length?'':'无模型列表'};
    }catch(e){clearTimeout(tm);var m=String((e&&e.message)||e||'');var ab=/abort/i.test(m);return{ok:false,status:0,err:ab?'超时':m,net:!ab}}
  }
  btn.addEventListener('click',async function(){
    if(_busy)return;
    var prov=provSel.value,ep=$('aset-endpoint').value,key=$('aset-key').value.trim();
    var reqs=prov==='custom'?_modelListReqCustom(ep,key):[_modelListReq(prov,ep,key)].filter(Boolean);
    if(!reqs.length){_hint('请先填写接口地址',true);return}
    _busy=true;btn.disabled=true;var old=btn.textContent;_hint('');
    var hit=null,tries=[],t0=Date.now();
    for(var i=0;i<reqs.length;i++){
      if(i&&Date.now()-t0>25000)break;
      btn.textContent=reqs.length>1?('拉取中 '+(i+1)+'/'+reqs.length+'…'):'拉取中…';
      var res=await _try(reqs[i],reqs.length>1?7000:20000);tries.push(res);
      if(res.ok){hit={req:reqs[i],list:res.list};break}
    }
    if(hit){
      _last=hit.list;_draw(_last,'');
      if(wrap)wrap.style.display='';
      if(q){q.value='';q.style.display=_last.length>10?'':'none'}
      var where=hit.req.url.replace(/^https?:\/\//,'').replace(/\?.*$/,'').slice(0,60);
      _hint(hit.req.kind==='newapi'?('已从中转站公开模型表拉取 '+_last.length+' 个（'+where+'）——该表列出站点全部模型，以你的密钥实际可用为准'):('已拉取 '+_last.length+' 个模型（'+where+'）'));
    }else{
      var msg,st=tries.map(function(t){return t.status}).filter(Boolean);
      if(tries.some(function(t){return t.status===401||t.status===403}))msg='密钥无效、无权限或余额不足（HTTP '+(st.indexOf(401)!==-1?401:403)+'）';
      else if(tries.some(function(t){return t.html}))msg='该地址返回的是网页而不是接口，请核对接口地址（通常以 /v1/chat/completions 结尾）';
      else if(tries.length&&tries.every(function(t){return t.net}))msg='无法连接，或该接口不允许浏览器跨域（CORS）——可手输模型名';
      else if(tries.length&&tries.every(function(t){return t.err==='超时'}))msg='超时——接口无响应，可手输模型名';
      else msg=(reqs.length>1?('已尝试 '+tries.length+' 个地址，均未返回模型列表'):('HTTP '+(st[0]||'—')+(tries[0]&&tries[0].err?('：'+tries[0].err):'')))+'——可手输模型名';
      _hint('拉取失败：'+msg.slice(0,140),true);
    }
    _busy=false;btn.disabled=false;btn.textContent=old;
  });
  sel.addEventListener('change',function(){if(sel.value){$('aset-model').value=sel.value;toast('模型已选：'+sel.value)}});
  if(q)q.addEventListener('input',function(){if(_last.length)_draw(_last,q.value)});
  provSel.addEventListener('change',_modelListReset);
})();
