let _apiDragMoved=false;
function _apiTouchDrag(el){
  let t0=null,dragging=false,ghostIdx=-1,sx=0,sy=0,pid=null,asRaf=0,lastY=0;
  const blockScroll=ev=>{ev.preventDefault()};
  function engage(){
    dragging=true;el.classList.add('api-dragging');
    try{el.setPointerCapture(pid)}catch(_){}
    try{navigator.vibrate&&navigator.vibrate(8)}catch(_){}
    document.addEventListener('touchmove',blockScroll,{passive:false});
    if(asRaf)cancelAnimationFrame(asRaf);
    asRaf=requestAnimationFrame(autoScroll);
  }
  function autoScroll(){/* 边缘自动滚屏：滚多少、基准 sy 就补多少，卡片视觉位置不跳；纯滚屏期指针不动也持续推进 */
    if(!dragging){asRaf=0;return}
    asRaf=requestAnimationFrame(autoScroll);
    const vh=window.innerHeight,edge=Math.max(76,vh*0.13);
    let v=0;
    if(lastY<edge)v=-Math.ceil((edge-lastY)/edge*15);
    else if(lastY>vh-edge)v=Math.ceil((lastY-(vh-edge))/edge*15);
    if(v){window.scrollBy(0,v);sy-=v;el.style.transform='translateY('+(lastY-sy)+'px) scale(1.02)'}
  }
  el.addEventListener('pointerdown',e=>{
    if(e.target.closest('.api-del'))return;
    _apiDragMoved=false;ghostIdx=-1;dragging=false;
    sx=e.clientX;sy=e.clientY;lastY=e.clientY;pid=e.pointerId;
    if(t0)clearTimeout(t0);
    t0=setTimeout(()=>{t0=null;engage()},260);
  });
  el.addEventListener('pointermove',e=>{
    lastY=e.clientY;
    if(!dragging){
      if(t0){const dx=e.clientX-sx,dy0=e.clientY-sy;if(dx*dx+dy0*dy0>100){clearTimeout(t0);t0=null}}
      return;
    }
    _apiDragMoved=true;e.preventDefault();
    el.style.transform='translateY('+(e.clientY-sy)+'px) scale(1.02)';
    const items=[...document.querySelectorAll('#api-list .api-li')];
    items.forEach(x=>x.classList.remove('drop-above','drop-below'));
    const over=items.find(x=>{if(x===el)return false;const r=x.getBoundingClientRect();return e.clientY>=r.top&&e.clientY<=r.bottom});
    if(over){
      const r=over.getBoundingClientRect();
      const above=e.clientY<r.top+r.height/2;
      over.classList.add(above?'drop-above':'drop-below');
      ghostIdx=parseInt(over.dataset.apiIdx)+(above?0:1);
    }
  });
  const fin=async()=>{
    if(t0){clearTimeout(t0);t0=null}
    document.removeEventListener('touchmove',blockScroll,{passive:false});
    if(asRaf){cancelAnimationFrame(asRaf);asRaf=0}
    if(!dragging)return;
    dragging=false;el.classList.remove('api-dragging');el.style.transform='';
    document.querySelectorAll('#api-list .api-li').forEach(x=>x.classList.remove('drop-above','drop-below'));
    const from=parseInt(el.dataset.apiIdx);
    if(ghostIdx<0||isNaN(from)){setTimeout(()=>{_apiDragMoved=false},60);return}
    let to=ghostIdx>from?ghostIdx-1:ghostIdx;ghostIdx=-1;
    if(to===from){setTimeout(()=>{_apiDragMoved=false},60);return}
    const item=_cfgs.splice(from,1)[0];
    _cfgs.splice(to,0,item);
    for(let i=0;i<_cfgs.length;i++){_cfgs[i].sortOrder=i;try{await dbPut('apiConfigs',_cfgs[i])}catch(err){}}
    renderApiList();toast('排序已更新');
    setTimeout(()=>{_apiDragMoved=false},60);
  };
  el.addEventListener('pointerup',fin);
  el.addEventListener('pointercancel',fin);
}
