/* v14：GUIDE → PWA 教程页的 ib-sw.js 模板下载（与页内展示的模板逐字一致） */
var _IB_SW_TPL="/* InternalBeyond Mobile — ib-sw.js（Service Worker 模板 · 联网优先，离线回退）\n   与手机端 HTML 放在同一目录，经 HTTPS 访问时页面会自动注册本文件。\n   只接管本站的 GET 请求；发往 AI 服务商 / 中转站的请求原样放行、绝不缓存。 */\nconst IB_CACHE='ib-cache-v2';\nself.addEventListener('install',function(){self.skipWaiting()});\nself.addEventListener('activate',function(e){e.waitUntil(caches.keys().then(function(ks){return Promise.all(ks.filter(function(k){return k!==IB_CACHE}).map(function(k){return caches.delete(k)}))}).then(function(){return self.clients.claim()}))});\nself.addEventListener('fetch',function(e){\n  if(e.request.method!=='GET')return;\n  var u=new URL(e.request.url);\n  if(u.origin!==self.location.origin)return;\n  e.respondWith(fetch(e.request).then(function(r){\n    if(r&&r.ok){var cp=r.clone();caches.open(IB_CACHE).then(function(c){c.put(e.request,cp)})}\n    return r;\n  }).catch(function(){return caches.match(e.request,{ignoreSearch:true}).then(function(m){if(m)return m;throw new Error('offline')})}));\n});";
try{var _swb=document.getElementById('pwa-sw-dl');if(_swb)_swb.addEventListener('click',function(){try{var b=new Blob([_IB_SW_TPL],{type:'text/javascript;charset=utf-8'});var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='ib-sw.js';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){try{URL.revokeObjectURL(a.href)}catch(e){}},400)}catch(e){toast('此环境暂不支持下载')}})}catch(e){}
/* 工具分区 */
async function renderApiTools(){
  await loadVT(true);await loadCfgs();
  $('vt-ep').value=_vt.endpoint||'';
  $('vt-key').value=_vt.apiKey||'';
  $('vt-model').value=_vt.model||'';
  try{_apiSrcFillM($('vt-src'),'stt');_apiSrcFillM($('ig-src'),'ig');$('vt-mpre').value='';$('ig-mpre').value=''}catch(e){}/* v178-p：①两卡的「沿用 API 配置」按当前 API 列表重填，模型下拉回落自定义 */
  const box=$('tool-ping');box.innerHTML='';
  if(!_cfgs.length){box.innerHTML='<div class="empty" style="padding:14px">没有可测试的 API 配置。</div>';return}
  _cfgs.forEach(c=>{
    const row=document.createElement('div');row.className='tool-row';
    const nm=document.createElement('div');nm.className='tool-name';
    nm.innerHTML=esc(cfgName(c))+'<div class="tool-sub">'+esc(provLabel(c))+'</div>';
    const res=document.createElement('div');res.className='tool-res';res.textContent='—';
    const btn=document.createElement('button');btn.className='btn mini';btn.textContent='测试';
    btn.addEventListener('click',async()=>{
      btn.disabled=true;res.className='tool-res';res.textContent='测试中…';
      const r=await testCfg(c);
      res.className='tool-res '+(r.ok?'ok':'bad');
      res.textContent=r.ok?('✓ '+r.ms+'ms'):('✗ '+r.err);
      btn.disabled=false;
    });
    row.appendChild(nm);row.appendChild(res);row.appendChild(btn);
    box.appendChild(row);
  });
}
$('vt-save').addEventListener('click',async()=>{
  const vt=await loadVT();
  const upd=Object.assign({},vt,{id:'voiceTrans',
    endpoint:$('vt-ep').value.trim(),
    apiKey:$('vt-key').value.trim(),
    model:$('vt-model').value.trim()||'whisper-1'});
  try{await dbPut('apiSettings',upd);_vt=upd;toast('已保存')}catch(e){toast('保存失败')}
});
async function testCfg(cfg){
  if(!cfg.apiKey)return{ok:false,err:'未填 Key'};
  const t0=Date.now();
  const ac=new AbortController();
  const tmr=setTimeout(()=>ac.abort(),20000);
  try{
    const test=Object.assign({},cfg,{streaming:false,thinkingEnabled:false,promptCache:false});
    const r=await callAI(test,[{role:'user',content:'ping'}],'',()=>{},ac.signal,{maxTokens:16});
    clearTimeout(tmr);void r;
    return{ok:true,ms:Date.now()-t0};
  }catch(err){
    clearTimeout(tmr);
    const msg=err&&err.name==='AbortError'?'超时':(err&&err.message?err.message:'失败');
    return{ok:false,err:String(msg).slice(0,60)};
  }
}
$('tool-usage-btn').addEventListener('click',async()=>{
  const box=$('tool-usage');
  box.innerHTML='<div class="empty" style="padding:14px">统计中…</div>';
  const rows=[];let totalKB=0;
  for(const s of SYNC_STORES){
    let n=0,kb=0;
    try{const arr=await dbGetAll(s);n=arr.length;kb=Math.round(JSON.stringify(arr).length/1024)}catch(e){}
    totalKB+=kb;
    rows.push('<div class="usage-row"><span>'+STORE_CN[s]+'</span><span><b>'+n+'</b> 条 · '+kb+' KB</span></div>');
  }
  rows.push('<div class="usage-row"><span>合计</span><span><b>'+totalKB+'</b> KB</span></div>');
  box.innerHTML=rows.join('');
});

/* ═══════════ Memory 页 ═══════════ */
let _mems=[],_ams=[],_editMemId=null,_detailMem=null,_memFilter='all',_memVis=[];
['meme-imp','meme-val','meme-aro'].forEach(id=>{
  $(id).addEventListener('input',e=>{
    rangeFill(e.target);
    const v=e.target.value;
    $(id+'-val').textContent=id==='meme-imp'?v:(v/100).toFixed(2);
  });
});
$('meme-vis').addEventListener('change',()=>{
  const _v=$('meme-vis').value;
  $('meme-vis-list').style.display=(_v==='only'||_v==='except')?'flex':'none'});/* private/all 都不需要勾 AI */
['meme-pin','meme-res'].forEach(id=>$(id).addEventListener('click',()=>sw2($(id),!$(id).classList.contains('on'))));
async function renderMemLib(){
  try{_mems=await dbGetAll('memories')}catch(e){_mems=[]}
  try{await _ibMemOneLineRepairM(_mems)}catch(e){}/* 本轮：#2 导入旧备份后进 Memory 页即清残留 */
  await loadCfgs();
  _mems.sort((a,b)=>((b.pinned?1:0)-(a.pinned?1:0))||((b.importance||0)-(a.importance||0))||((b.created||0)-(a.created||0)));
  const pinned=_mems.filter(m=>m.pinned).length;
  const act=_mems.filter(m=>!m.resolved).length;
  $('mem-stats').innerHTML=
    '<div class="ms-cell"><div class="ms-num">'+_mems.length+'</div><div class="ms-lab">Total</div></div>'
   +'<div class="ms-cell"><div class="ms-num">'+pinned+'</div><div class="ms-lab">Pinned</div></div>'
   +'<div class="ms-cell"><div class="ms-num">'+act+'</div><div class="ms-lab">Active</div></div>';
  /* v50-m：域分布条（照搬电脑端） */
  let dbar=$('mem-dbar');
  if(!dbar){dbar=document.createElement('div');dbar.id='mem-dbar';dbar.className='mem-dbar';$('mem-stats').after(dbar)}
  const domains=['情感','日常','创作','思考'];
  const counts=domains.map(d=>_mems.filter(m=>m.domain===d).length);
  const total=counts.reduce((a,b)=>a+b,0)||1;
  dbar.innerHTML=counts.map((n,i)=>n?'<i style="width:'+(n/total*100)+'%;background:'+DOMAIN_COLOR[domains[i]]+'"></i>':'').join('');
  
  try{
    const _ms2=await loadMS();
    const _bud=Math.max(300,(_ms2&&_ms2.budget)||2000),_cl=Math.max(40,(_ms2&&_ms2.contentLen)||200);
    const _cand=_mems.filter(m=>m.visibility!=='private');
    let _est=0;
    for(const m of _cand){
      const ln=_memLineM(m,'',_cl,[]);/* v199-p：估算行同注入行 */
      if(_est+ln.length>_bud)break;_est+=ln.length+1;
    }
    let tok=$('mem-tok');
    if(!tok){tok=document.createElement('div');tok.id='mem-tok';tok.className='mem-tok';dbar.after(tok)}
    tok.innerHTML='<div class="mem-tok-h">每次注入约 <b>'+_est+'</b> 字符（≈ <b>'+Math.round(_est*1.5)+'</b> token）</div>'
      +'<div class="mem-tok-bar"><i style="width:'+Math.min(100,Math.round(_est/_bud*100))+'%"></i></div>'
      +'<div class="mem-tok-hint">注入上限 '+_bud+' 字符 · 每条截取 '+_cl+' 字符 · 在 API 页 → 全局设置调整</div>';
  }catch(e){}
  const fbox=$('mem-filter');fbox.innerHTML='';/* v59-m：多组下拉分类，与电脑端一致 */
  /* 领域下拉 */
  const _mfDomain=[['all','全部领域'],['情感','情感'],['日常','日常'],['创作','创作'],['思考','思考']];
  const _mfDCur=(_mfDomain.find(x=>x[0]===_memFilter)||_mfDomain[0])[1];
  const dBtn=document.createElement('button');dBtn.className='mem-cat-btn';
  dBtn.innerHTML='<span>'+_mfDCur+'</span><svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>';
  dBtn.addEventListener('click',()=>actionSheet(_mfDomain.map(([k,t])=>({label:t,fn:()=>{_memFilter=k;renderMemLib()}}))));
  fbox.appendChild(dBtn);
  /* 状态下拉 */
  if(!window._memStatusFilter)window._memStatusFilter='all';
  const _mfStatus=[['all','全部状态'],['pin','置顶'],['unresolved','未解决'],['resolved','已解决']];
  const _mfSCur=(_mfStatus.find(x=>x[0]===_memStatusFilter)||_mfStatus[0])[1];
  const sBtn=document.createElement('button');sBtn.className='mem-cat-btn';
  sBtn.innerHTML='<span>'+_mfSCur+'</span><svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>';
  sBtn.addEventListener('click',()=>actionSheet(_mfStatus.map(([k,t])=>({label:t,fn:()=>{_memStatusFilter=k;renderMemLib()}}))));
  fbox.appendChild(sBtn);
  /* 排序下拉 */
  if(!window._memSort)window._memSort='created';
  const _mfSort=[['created','按时间'],['score','按权重'],['importance','按重要性']];
  const _mfSoCur=(_mfSort.find(x=>x[0]===_memSort)||_mfSort[0])[1];
  const soBtn=document.createElement('button');soBtn.className='mem-cat-btn';
  soBtn.innerHTML='<span>'+_mfSoCur+'</span><svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>';
  soBtn.addEventListener('click',()=>actionSheet(_mfSort.map(([k,t])=>({label:t,fn:()=>{_memSort=k;renderMemLib()}}))));
  fbox.appendChild(soBtn);
  /* v81-m r13：「按 AI 可见」下拉（照抄电脑端「全部AI可见」分类，任务 19） */
  if(!window._memVisFilter)window._memVisFilter='all';
  const _mfVis=[['all','全部记忆']].concat((_cfgs||[]).map(a=>[a.id,cfgName(a)]));
  const _mfVCur=(_mfVis.find(x=>x[0]===_memVisFilter)||_mfVis[0])[1];
  const vBtn=document.createElement('button');vBtn.className='mem-cat-btn';
  vBtn.innerHTML='<span>'+esc(_mfVCur)+'</span><svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>';
  vBtn.addEventListener('click',()=>actionSheet(_mfVis.map(([k,t])=>({label:t,fn:()=>{_memVisFilter=k;renderMemLib()}}))));
  fbox.appendChild(vBtn);
  drawMemList();
}
function _memVisibleToM(m,aiId){
  if(!m)return false;
  var v=String(m.visibility==null||m.visibility===''?'public':m.visibility).toLowerCase();
  if(v==='private')return false;
  if(v==='public'||v==='all')return true;
  if(v==='only')return Array.isArray(m.visibleTo)&&m.visibleTo.indexOf(aiId)!==-1;
  if(v==='except')return !(Array.isArray(m.excludeFrom)&&m.excludeFrom.indexOf(aiId)!==-1);
  return false;
}
function _memTs(m){
  if(!m)return 0;
  var v=m.created!=null?m.created:(m.createdAt!=null?m.createdAt:(m.timestamp!=null?m.timestamp:(m.time!=null?m.time:m.ts)));
  if(typeof v==='number'&&isFinite(v))return v;
  if(typeof v==='string'&&v){var n=Date.parse(v);if(!isNaN(n))return n;var d=parseInt(v,10);if(isFinite(d)&&d>0)return d}
  var mm=/(\d{13})/.exec(String(m.id||''));return mm?parseInt(mm[1],10):0;
}
$('mem-search').addEventListener('input',drawMemList);
function drawMemList(){
  const q=$('mem-search').value.trim().toLowerCase();
  const box=$('mem-list');box.innerHTML='';
  const hit=_mems.filter(m=>{
    if(_memFilter!=='all'&&m.domain!==_memFilter)return false;
    if(window._memVisFilter&&_memVisFilter!=='all'&&!_memVisibleToM(m,_memVisFilter))return false;/* v81-m r13 */
    if(typeof _memStatusFilter!=='undefined'&&_memStatusFilter!=='all'){
      if(_memStatusFilter==='pin'&&!m.pinned)return false;
      if(_memStatusFilter==='unresolved'&&m.resolved)return false;
      if(_memStatusFilter==='resolved'&&!m.resolved)return false;
    }
    if(!q)return true;
    return [m.title,m.oneLine,m.summary,m.content,(m.tags||[]).join(' ')].join(' ').toLowerCase().indexOf(q)!==-1;
  });
  if(typeof _memSort!=='undefined'&&_memSort==='score')hit.sort((a,b)=>(b.score||0)-(a.score||0));
  else if(typeof _memSort!=='undefined'&&_memSort==='importance')hit.sort((a,b)=>(b.importance||0)-(a.importance||0));
  else hit.sort((a,b)=>_memTs(b)-_memTs(a));
  hit.sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0));
  if(!hit.length){box.innerHTML='<div class="empty">'+(q||_memFilter!=='all'?'没有匹配的记忆。':'还没有记忆。<br>点下方新增，或在 Data 页导入电脑版备份。')+'</div>';return}
  hit.forEach(m=>{
    const d=document.createElement('div');d.className='mem-card'+(m.pinned?' pin':'');
    d.style.setProperty('--dom',DOMAIN_COLOR[m.domain]||'rgba(127,168,217,0.5)');
    const line=m.summary||m.content||'';/* 本轮：#2 列表只认概述（oneLine 是电脑端引言位） */
    const tags=(m.tags||[]).slice(0,3).join(' · ');
    const imp=Math.max(0,Math.min(10,m.importance||0));
    d.innerHTML='<div class="mem-title">'+(m.pinned?'<span class="mem-pin"></span>':'')+esc(m.title||'（无标题）')+'</div>'
      +(line?'<div class="mem-line">'+esc(line)+'</div>':'')
      +'<div class="mem-meta"><span class="mem-dot"></span>'+esc(m.domain||'—')
      +'<span class="mem-bar"><i style="width:'+(imp*10)+'%"></i></span>'+imp
      +(tags?'<span>'+esc(tags)+'</span>':'')
      +(m.resolved?'<span>已解决</span>':'')+(m.createdBy&&m.createdBy!=='user'&&m.createdByName?'<span>'+esc(m.createdByName)+' 写入</span>':'')+'</div><div class="mem-card-fold"></div>';/* v74-m r5：AI 写入者小签 */
    d.addEventListener('click',()=>openMemDetail(m));
    box.appendChild(d);
  });
}
function friendNick(fid){const c=[..._cfgs,..._archived].find(x=>x.id===fid);return c?cfgName(c):(fid||'')}
function openMemDetail(m){
  _detailMem=m;
  $('memd-title').textContent=m.title||'（无标题）';
  const _sm=String(m.summary||'').replace(/\s+/g,' ').trim(),_ct=String(m.content||'');
  const _dup=!!(_sm&&_ct&&_ct.replace(/\s+/g,' ').trim().indexOf(_sm)===0);
  const _se=$('memd-sum');if(_se){_se.textContent=_sm;_se.style.display=(_sm&&!_dup)?'':'none'}
  const parts=[];
  if(_ct)parts.push(_ct);
  if(m.oneLine&&String(m.oneLine).trim()!==String(m.summary||'').trim())parts.push('“'+m.oneLine+'”');/* 本轮：#2 电脑端「写一句话」只展示不编辑，排在正文后加引号；与概述同句的是旧双写残留，不重复显示 */
  $('memd-body').textContent=parts.join('\n\n')||(_sm?'':'（无内容）');
  const visTxt=m.visibility==='private'?'完全私密 · 任何 AI 都读不到':
    m.visibility==='only'?('仅可见：'+(m.visibleTo||[]).map(friendNick).join('，')):
    m.visibility==='except'?('不可见：'+(m.excludeFrom||[]).map(friendNick).join('，')):'所有 AI 可见';
  $('memd-meta').textContent=
    '领域：'+(m.domain||'—')+'　重要性：'+(m.importance!=null?m.importance:'—')
    +'\nValence：'+(m.valence!=null?Number(m.valence).toFixed(2):'—')+'　Arousal：'+(m.arousal!=null?Number(m.arousal).toFixed(2):'—')
    +'\n置顶：'+(m.pinned?'是':'否')+'　已解决：'+(m.resolved?'是':'否')+'　激活 '+(m.activationCount||0)+' 次'
    +'\n'+visTxt
    +(m.tags&&m.tags.length?'\n标签：'+m.tags.join('，'):'')
    +(m.createdByName?'\n创建者：'+m.createdByName:(m.createdBy==='user'?'\n创建者：你':''))
    +(m.created?'\n创建：'+new Date(m.created).toLocaleString('zh-CN'):'');
  openSheet('sheet-mem-detail');
}
$('memd-edit').addEventListener('click',()=>{if(!_detailMem)return;const m=_detailMem;closeSheets();openMemEditor(m)});
$('memd-del').addEventListener('click',async()=>{
  if(!_detailMem)return;
  if(!await confirmDlg('删除这条记忆？','删除'))return;
  try{await dbDelete('memories',_detailMem.id)}catch(e){toast('删除失败');return}
  closeSheets();renderMemLib();toast('已删除');
});
function fillVisList(m){
  const box=$('meme-vis-list');box.innerHTML='';
  _memVis=m?(m.visibility==='only'?(m.visibleTo||[]).slice():m.visibility==='except'?(m.excludeFrom||[]).slice():[]):[];
  _cfgs.forEach(c=>{
    const chip=document.createElement('div');chip.className='chip'+(_memVis.indexOf(c.id)!==-1?' on':'');
    chip.textContent=cfgName(c);
    chip.addEventListener('click',()=>{
      const i=_memVis.indexOf(c.id);
      if(i===-1)_memVis.push(c.id);else _memVis.splice(i,1);
      chip.classList.toggle('on',_memVis.indexOf(c.id)!==-1);
    });
    box.appendChild(chip);
  });
}
async function openMemEditor(m){
  await loadCfgs();
  _editMemId=m?m.id:null;
  $('meme-title').textContent=m?'编辑记忆':'新记忆';
  $('meme-t').value=m?(m.title||''):'';
  $('meme-c').value=m?(m.content||''):'';
  $('meme-s').value=m?(m.summary||''):'';/* v154-p：#5 */
  $('meme-domain').value=m&&['情感','日常','创作','思考'].indexOf(m.domain)!==-1?m.domain:'日常';
  $('meme-tags').value=m&&m.tags?m.tags.join('，'):'';
  const imp=m&&m.importance!=null?m.importance:5;
  $('meme-imp').value=imp;$('meme-imp-val').textContent=imp;
  const val=m&&m.valence!=null?m.valence:0.5;
  $('meme-val').value=Math.round(val*100);$('meme-val-val').textContent=Number(val).toFixed(2);
  const aro=m&&m.arousal!=null?m.arousal:0.3;
  $('meme-aro').value=Math.round(aro*100);$('meme-aro-val').textContent=Number(aro).toFixed(2);
  ['meme-imp','meme-val','meme-aro'].forEach(id=>rangeFill($(id)));
  const vis=m&&(m.visibility==='only'||m.visibility==='except')?m.visibility:'all';
  $('meme-vis').value=vis;
  $('meme-vis-list').style.display=(vis==='only'||vis==='except')?'flex':'none';
  fillVisList(m);
  sw2($('meme-pin'),!!(m&&m.pinned));
  sw2($('meme-res'),!!(m&&m.resolved));
  openSheet('sheet-mem');
}
$('mem-add').addEventListener('click',()=>openMemEditor(null));
$('meme-save').addEventListener('click',async()=>{
  const title=$('meme-t').value.trim();
  if(!title){toast('请填写标题');return}
  const vis=$('meme-vis').value;
  const pinned=$('meme-pin').classList.contains('on');
  if(pinned){
    const cnt=_mems.filter(m=>m.pinned&&m.id!==_editMemId).length;
    if(cnt>=7){toast('置顶最多 7 条');return}
  }
  const patch={
    title:title,
    content:$('meme-c').value.trim(),
    summary:$('meme-s').value.trim(),/* 本轮：#2 只存概述；oneLine 不入 patch（编辑时沿用旧值：电脑端「写一句话」原样保留，手机端不写这一格） */
    domain:$('meme-domain').value,
    tags:$('meme-tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean),
    importance:Math.max(1,Math.min(10,parseInt($('meme-imp').value)||5)),
    valence:Math.max(0,Math.min(1,(parseInt($('meme-val').value)||0)/100)),
    arousal:Math.max(0,Math.min(1,(parseInt($('meme-aro').value)||0)/100)),
    pinned:pinned,
    resolved:$('meme-res').classList.contains('on'),
    visibility:vis,
    visibleTo:vis==='only'?_memVis.slice():[],
    excludeFrom:vis==='except'?_memVis.slice():[]
  };
  try{
    let mem;
    if(_editMemId){
      const old=(await dbGetAll('memories')).find(x=>x.id===_editMemId)||{};
      mem=Object.assign({},old,patch,{id:_editMemId,editedByUser:old.createdBy&&old.createdBy!=='user'?true:(old.editedByUser||false)});
    }else{
      mem=Object.assign({
        id:'mem_'+Date.now()+'_'+Math.floor(Math.random()*10000),
        summary:'',oneLine:'',rawSource:'手动',sourceId:'',
        activationCount:0,created:Date.now(),lastActivated:Date.now(),
        createdBy:'user',createdByName:'',editedByUser:false
      },patch);
    }
    await dbPut('memories',mem);
    closeSheets();renderMemLib();toast('已保存');
  }catch(e){toast('保存失败')}
});
/* Auto Memory 汇总（按 AI 分组）*/

async function renderAmAll(){
  try{_ams=await dbGetAll('autoMemory')}catch(e){_ams=[]}
  await loadCfgs();
  drawAmAll();
}
$('am-search').addEventListener('input',drawAmAll);
let _amAllIdx=0,_amArchView=false;/* v66-m t11：Auto Memory / Archived 归档区切换（照电脑端 Memory 页横条） */
$('am-arch-toggle-m').addEventListener('click',()=>{_amArchView=!_amArchView;_amAllIdx=0;$('am-arch-toggle-m').classList.toggle('on',_amArchView);drawAmAll()});
function drawAmAll(){
  const q=$('am-search').value.trim().toLowerCase();
  const box=$('am-all');box.innerHTML='';
  const pagerBox=$('am-pager');if(pagerBox)pagerBox.innerHTML='';
  const all=_amArchView?[..._archived]:[..._cfgs];/* v66-m t11：原来把归档 AI 混在一起且无标识 */
  
  const packs=all.map(c=>({c:c,es:_ams.filter(e=>e.friendId===c.id&&(!q||String(e.content||'').toLowerCase().indexOf(q)!==-1))})).filter(p=>p.es.length);
  if(!packs.length){box.innerHTML='<div class="empty">'+(q?'没有匹配的档案。':(_amArchView?'归档区暂无 Auto Memory 档案。<br>在 API 页把某个配置归档后，其档案会以只读方式保留在这里。':'还没有 Auto Memory 档案。<br>在 Home 页 → 设置 → Auto Memory 中开启后，由对应 AI 在对话中写入。'))+'</div>';return}
  if(_amAllIdx>=packs.length)_amAllIdx=0;if(_amAllIdx<0)_amAllIdx=packs.length-1;
  if(!box._swipe){box._swipe=1;let sx=0,sy=0;
    box.addEventListener('touchstart',e=>{const t=e.touches[0];sx=t.clientX;sy=t.clientY},{passive:true});
    box.addEventListener('touchend',e=>{const t=e.changedTouches[0];const dx=t.clientX-sx,dy=t.clientY-sy;
      if(Math.abs(dx)>44&&Math.abs(dx)>Math.abs(dy)*1.4){_amAllIdx+=dx<0?1:-1;drawAmAll()}},{passive:true});
  }
  const p=packs[_amAllIdx],c=p.c;
  const sorted=p.es.slice().sort((a,b)=>((b.updated||b.created||0)-(a.updated||a.created||0)));
  const card=document.createElement('div');card.className='am-card';
  const top=document.createElement('div');top.className='am-top';
  const lens=document.createElement('div');lens.className='am-lens';setAvaEl(lens,c.avatar,cfgName(c));
  const who=document.createElement('div');who.className='am-who';
  who.innerHTML='<div class="am-nm">'+esc(cfgName(c))+'</div><div class="am-sub">'+sorted.length+' 条'+(_amArchView?' · 已归档 · 只读':'')+(packs.length>1?(' · '+(_amAllIdx+1)+'/'+packs.length):'')+'</div>';
  top.appendChild(lens);top.appendChild(who);
  card.appendChild(top);
  const flow=amFlowEl(c,sorted,undefined,_amArchView);
  if(!_amArchView)flow.querySelectorAll('.am-en').forEach((en,i)=>{/* v55-m t26：手机端恒显编辑/删除按钮；v66-m t11：归档区只读，不挂编辑/删除 */
    const e=sorted[i];if(!e)return;
    const opsEl=document.createElement('span');opsEl.className='am-ops';
    opsEl.innerHTML='<button class="am-op" data-k="e" aria-label="编辑"><svg viewBox="0 0 24 24"><path d="M4 20l4.2-1 11-11a2.1 2.1 0 0 0-3-3l-11 11z"/><path d="M13.5 6.5l3 3"/></svg></button>'
      +'<button class="am-op" data-k="d" aria-label="删除"><svg viewBox="0 0 24 24"><path d="M6 7h12M9.5 7V5.5h5V7M8 7l.8 12h6.4L16 7"/></svg></button>';
    opsEl.addEventListener('click',async ev=>{ev.stopPropagation();
      const k=ev.target.closest('.am-op');if(!k)return;
      if(k.dataset.k==='e'){openAmEdit(e.friendId,e)}
      else{if(!await confirmDlg('删除这条 Auto Memory？','删除'))return;
        try{await dbDelete('autoMemory',e.id)}catch(err){toast('删除失败');return}
        renderAmAll();toast('已删除');}
    });
    const hEl=en.querySelector('.am-en-h')||en;hEl.appendChild(opsEl);
  });
  card.appendChild(flow);
  box.appendChild(card);
  /* v66-m t11：分页点移入搜索框与档案卡之间的固定槽位（原来挂在卡片下方） */
  if(pagerBox&&packs.length>1){
    packs.forEach((_,pi)=>{const dot=document.createElement('i');if(pi===_amAllIdx)dot.className='on';dot.addEventListener('click',()=>{_amAllIdx=pi;drawAmAll()});pagerBox.appendChild(dot)});
  }
}

$('mem-export').addEventListener('click',async()=>{
  try{
    const arr=await dbGetAll('memories');
    downloadBlob(new Blob([JSON.stringify({memories:arr,exportDate:new Date().toISOString(),version:4})],{type:'application/json'}),
      'InternalBeyond_memories_'+new Date().toISOString().slice(0,10)+'.json');
    toast('已导出 '+arr.length+' 条');
  }catch(e){toast('导出失败')}
});
$('mem-import').addEventListener('click',()=>$('mem-import-file').click());
$('mem-import-file').addEventListener('change',async e=>{
  const f=e.target.files[0];e.target.value='';if(!f)return;
  let data;try{data=JSON.parse(await f.text())}catch(err){toast('文件格式错误');return}
  const arr=Array.isArray(data)?data:(Array.isArray(data.memories)?data.memories:null);
  if(!arr||!arr.length){toast('这个文件里没有记忆条目');return}
  if(!await confirmDlg('并入 '+arr.length+' 条记忆？同 id 记录以文件为准。','导入'))return;
  try{await dbPutAll('memories',arr.filter(x=>x&&typeof x==='object'));renderMemLib();toast('已导入 '+arr.length+' 条')}
  catch(err){toast('导入失败')}
});

