$('ibt-confirm').addEventListener('click',async()=>{await loadIBT();_ibt.confirm=!(_ibt.confirm!==false);sw2($('ibt-confirm'),_ibt.confirm!==false);try{await dbPut('apiSettings',_ibt)}catch(e){toast('保存失败')}});
var MCP_KEY_IN_URL=[{re:/^https?:\/\/mcp\.didichuxing\.com\//i,p:'key'},{re:/^https?:\/\/mcp\.amap\.com\//i,p:'key'}];/* v179-p：这些官方端点的 Key 放在 URL 查询串（IBMCP._rpc 按此表拼接） */
