$('import-file').addEventListener('change',async function(ev){
  var f=ev.target.files[0];ev.target.value='';if(!f)return;
  var e=_mioEl();
  if(e.ov.hidden)await _mioOpen('import');
  var data;
  try{data=JSON.parse(String(await f.text()).replace(/^\ufeff/,''))}catch(err){e.bd.innerHTML='<div class="mio-note" style="color:#c96a6a">文件格式错误：不是有效的 JSON 备份。</div>';return}
  _mioData=data;
  _mioFound=SYNC_STORES.filter(function(s){return Array.isArray(data[s])&&data[s].length});
  _mioSkipped=Object.keys(data).filter(function(k){return Array.isArray(data[k])&&data[k].length&&SYNC_STORES.indexOf(k)===-1});/* 不互通的数据跳过，记入层内与导入日志 */
  var h='';
  if(!_mioFound.length){
    h='<div class="mio-note" style="color:#c96a6a">这个备份里没有手机版可用的数据。</div>';
    if(_mioSkipped.length)h+='<div class="mio-note">已跳过（手机端不支持）：'+_mioSkipped.join('、')+'</div>';
    e.bd.innerHTML=h;e.ft.innerHTML='<button class="btn" id="mio-cancel">关闭</button>';
    $('mio-cancel').addEventListener('click',_mioClose);return;
  }
  _mioFound.forEach(function(s){h+='<div class="mio-row" data-s="'+s+'"><span class="mk-box on"></span><span class="st"></span>'+STORE_CN[s]+'<b>'+_mioData[s].length+' 条</b></div>'});
  if(_mioSkipped.length)h+='<div class="mio-note">将跳过（手机端不支持）：'+_mioSkipped.join('、')+'</div>';
  h+='<div class="mio-note">同 id 的记录会被文件内容覆盖，其余数据不受影响。点击某一行可取消勾选：本次导入将跳过该模块（默认全选）。</div>';
  e.bd.innerHTML=h;
  e.ft.innerHTML='<button class="btn" id="mio-cancel">取消</button><button class="btn primary" id="mio-go">开始导入</button>';
  $('mio-cancel').addEventListener('click',_mioClose);
  $('mio-go').addEventListener('click',_mioRunImport);
});
async function _mioRunImport(){
  if(_mioBusy||!_mioData)return;
  _mioBusy=true;var e=_mioEl();e.ft.innerHTML='<button class="btn" disabled>导入中…</button>';
  var fail=[],cnt={};
  for(var i=0;i<_mioFound.length;i++){
    var s=_mioFound[i],row=e.bd.querySelector('.mio-row[data-s="'+s+'"]'),st=row&&row.querySelector('.st');
    if(_mioSel[s]===false){if(st)st.textContent='—';continue}/* v120-p：#3 未勾选跳过 */
    var list=(_mioData[s]||[]).filter(function(x){return x&&typeof x==='object'});cnt[s]=list.length;
    try{await dbPutAll(s,list);if(st)st.textContent='✓'}
    catch(err){fail.push(STORE_CN[s]);if(row)row.classList.add('fail');if(st)st.textContent='✕'}
    list=null;_mioData[s]=null;
  }
  _about=null;_mp=null;_mpFromDb=false;_vt=null;_ms=null;_ibt=null;_out=null;_outFromDb=false;_cs=null;
  _calEvents=[];_calNotes=[];
  await loadCfgs();await loadMP();
  try{renderDataSum()}catch(err){}
  try{showSec()}catch(err){}/* v67-m d2：统一走 showSec 分发 */
  var _unsel=_mioFound.filter(function(s){return _mioSel[s]===false});
  var lbl=_mioFound.filter(function(s){return _mioSel[s]!==false}).map(function(s){return STORE_CN[s]+' '+(cnt[s]||0)+' 条'}).join('、');
  var msg='导入完成：'+lbl+(fail.length?('；失败：'+fail.join('、')):'')+(_unsel.length?('；本次未勾选：'+_unsel.map(function(s){return STORE_CN[s]}).join('、')):'')+(_mioSkipped.length?('；已跳过（手机端不支持）：'+_mioSkipped.join('、')):'');
  e.bd.insertAdjacentHTML('beforeend','<div class="mio-done">'+msg+'</div>');
  var il=$('imp-log');if(il){il.style.display='';il.textContent='上次'+msg+'（'+new Date().toLocaleString('zh-CN')+'）'}
  _mioBusy=false;_mioData=null;
  e.ft.innerHTML='<button class="btn primary" id="mio-cancel">完成</button>';
  $('mio-cancel').addEventListener('click',_mioClose);
}
async function _mioRunExport(){
  if(_mioBusy)return;
  _mioBusy=true;var e=_mioEl();e.ft.innerHTML='<button class="btn" disabled>导出中…</button>';
  try{
    var chunks=[],parts=['{'],psz=1;
    var _mioFl=function(){if(parts.length){chunks.push(new Blob(parts));parts=[];psz=0}};
    for(var i=0;i<SYNC_STORES.length;i++){
      var s=SYNC_STORES[i],row=e.bd.querySelector('.mio-row[data-s="'+s+'"]'),st=row&&row.querySelector('.st');
      if(_mioSel[s]===false){parts.push(JSON.stringify(s)+':[],');if(st)st.textContent='—';continue}
      parts.push(JSON.stringify(s)+':[');
      var n1=0;
      try{
        await dbEach(s,function(v){
          if(!v)return;
          if(s==='apiSettings'&&v.id==='ib_fsSyncDir')return;/* 同电脑版：目录句柄不进备份 */
          if(s==='chatMessages'){v=Object.assign({},v);delete v.upstreamRaw;delete v.thinkingSources}
          if(_mioNoKey&&(s==='apiConfigs'||s==='apiSettings')){v=Object.assign({},v);['apiKey','key','imageGenKey','sttKey','igKey'].forEach(function(k){if(v[k])v[k]=''})}
          var j1=JSON.stringify(v);parts.push((n1?',':'')+j1);n1++;psz+=j1.length;
          if(psz>2097152)_mioFl();
        });
        parts.push('],');
        if(st)st.textContent='✓';
      }catch(err){parts.push('],');if(row)row.classList.add('fail');if(st)st.textContent='✕'}
    }
    parts.push('"exportDate":'+JSON.stringify(new Date().toISOString())+',"version":4,"appVersion":'+JSON.stringify(IB_VER)+',"noKey":'+(!!_mioNoKey)+'}');/* v86-m r3：版本号占位＋密钥档标记 */
    _mioFl();
    var blob=new Blob(chunks,{type:'application/json'});chunks=null;
    downloadBlob(blob,'InternalBeyond_backup_'+new Date().toISOString().slice(0,10)+'_mobile'+(_mioNoKey?'_nokey':'')+'.json');
    var _unsx=SYNC_STORES.filter(function(s){return _mioSel[s]===false});
    e.bd.insertAdjacentHTML('beforeend','<div class="mio-done">导出完成：备份文件已生成（'+(blob.size/1024/1024).toFixed(2)+' MB），请在浏览器下载中查看。'+(_unsx.length?('未勾选跳过：'+_unsx.map(function(s){return STORE_CN[s]}).join('、')+'。'):'')+'</div>');
  }catch(err){e.bd.insertAdjacentHTML('beforeend','<div class="mio-done" style="border-color:rgba(200,110,110,0.4)">导出失败：'+String(err&&err.message||err).slice(0,60)+'</div>')}
  _mioBusy=false;
  e.ft.innerHTML='<button class="btn primary" id="mio-cancel">完成</button>';
  $('mio-cancel').addEventListener('click',_mioClose);
}
