var _envelopeFlapSVG='<svg class="envelope-deco" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polygon class="flap-fill" points="5,99 95,99 50,64" vector-effect="non-scaling-stroke"/></svg>';
