    var _amLen=(_amL.sys?_amL.sys.length+2:0)+(_amL.tail?_amL.tail.length+2:0);
    var budget=Math.max(2000,8000-reqBlock.length-_amLen);
    if(context.length>budget)context=context.slice(0,budget)+'…（内容过长，已截断）\n';/* 资料区超预算按电脑端 truncateContext 口径保头 */
    if(_lChat9.length){var _cb9=Math.max(600,budget-context.length-24);var _cl9=_lChat9.slice();var _ct9=_cl9.join('').length;while(_cl9.length>1&&_ct9>_cb9){_ct9-=_cl9[0].length;_cl9.shift()}if(_cl9.length===1&&_cl9[0].length>_cb9)_cl9[0]=_cl9[0].slice(-_cb9);context+='\n【你们最近的聊天记录】\n'+_cl9.join('')}/* 聊天段按剩余预算从最旧往下裁，最新对话保留 */
