      +'#ib-dbw .dbw-ico{width:74px;height:74px;margin:2px auto 10px;display:block;filter:drop-shadow(0 4px 18px rgba(226,64,64,0.5));animation:dbwPulse 2.2s ease-in-out infinite}'
