/* ═══ v51-m 话题频道侧栏（换窗）═══ */
function tpGroupLabel(ts){
  if(!ts)return '更早';
  const d=new Date(ts),n=new Date();
  const d0=new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime();
  const n0=new Date(n.getFullYear(),n.getMonth(),n.getDate()).getTime();
  const diff=Math.round((n0-d0)/86400000);
  if(diff<=0)return '今天';
  if(diff===1)return '昨天';
  if(diff<7)return '本周';
  if(d.getFullYear()===n.getFullYear())return (d.getMonth()+1)+' 月';
  return d.getFullYear()+' 年';
}
function tpRender(){
  const box=$('tp-list');if(!box)return;
  const q=(($('tp-th-search')&&$('tp-th-search').value)||'').trim().toLowerCase();
  const mq=($('tp-search').value||'').trim().toLowerCase();
  box.innerHTML='';
  const _grp=_activeCfg&&_activeCfg._group;
  $('tp-new').style.display=_grp?'none':'';
  _schSched(mq);
  if(_grp)return;
  const mk=(label,on,memOn,fn,lp)=>{
    const it=document.createElement('div');it.className='tp-item'+(on?' on':'');
    it.textContent=label;
    it.addEventListener('click',fn);
    if(lp)pressable(it,lp);
    box.appendChild(it);
  };
  if(!q||'主线对话'.includes(q)){
    /* v62-m t4：主线对话独立 UI，与频道窗分隔 */
    const mainIt=document.createElement('div');mainIt.className='tp-item tp-main'+(!_activeThread?' on':'');
    mainIt.innerHTML='<span class="tp-main-t">主线对话</span>';/* v66-m t7：去掉 MAIN 角标 */
    mainIt.addEventListener('click',()=>{tpClose();if(_activeThread)openConv(_activeCfg,null)});
    box.appendChild(mainIt);
  }
  const ts=_threads.slice().sort((a,b)=>(b.created||0)-(a.created||0))
    .filter(t=>!q||String(t.name||'').toLowerCase().includes(q));
  
  let curG=null;
  ts.forEach(t=>{
    const g=tpGroupLabel(t.created);
    if(g!==curG){curG=g;const ge=document.createElement('div');ge.className='tp-g';ge.textContent=g;box.appendChild(ge)}
    mk('# '+t.name,_activeThread&&_activeThread.id===t.id,!!t.memoryEnabled,
      ()=>{tpClose();if(!_activeThread||_activeThread.id!==t.id)openConv(_activeCfg,t)},
      ()=>{tpClose();openThreadEdit(t)});
  });
  if(!ts.length&&q){const e=document.createElement('div');e.className='hint';e.style.margin='10px 6px';e.textContent='没有匹配的话题';box.appendChild(e)}
}
function tpOpen(){
  if(!_activeCfg)return;
  const w=$('tp-wrap');w.hidden=false;
  const q=$('tp-search');if(q)q.value='';
  tpRender();
  try{openCvDrawer()}catch(e){}
  requestAnimationFrame(()=>requestAnimationFrame(()=>w.classList.add('open')));
}
function tpClose(){
  const w=$('tp-wrap');if(!w||w.hidden)return;
  w.classList.remove('open');
  setTimeout(()=>{w.hidden=true},300);
}
$('cv-ham').addEventListener('click',tpOpen);
document.querySelector('#tp-wrap .tp-mask').addEventListener('click',tpClose);
$('tp-new').addEventListener('click',()=>{tpClose();openThreadEdit(null)});
