const WS_DEFAULT_PROJ_ID='proj_icode_default',WS_USER_PROJ_ID='proj_icode_user';
let _icProj=WS_DEFAULT_PROJ_ID,_icFile=null,_icNewMode='file';
function icFmtSize(n){n=n||0;if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(2)+' MB'}
async function icEnsureFixed(){
  let p=null;try{p=await dbGet('projects',WS_DEFAULT_PROJ_ID)}catch(e){}
  if(!p)try{await dbPut('projects',{id:WS_DEFAULT_PROJ_ID,name:'ICode',isDefault:true,created:Date.now(),lastModified:Date.now()})}catch(e){}
  let u=null;try{u=await dbGet('projects',WS_USER_PROJ_ID)}catch(e){}
  if(!u)try{await dbPut('projects',{id:WS_USER_PROJ_ID,name:'User',isUser:true,created:Date.now(),lastModified:Date.now()})}catch(e){}
}
async function icFilesOf(pid){
  try{return await dbGetByIndex('projectFiles','byProject',pid)}
  catch(e){try{return (await dbGetAll('projectFiles')).filter(f=>f.projectId===pid)}catch(e2){return []}}
}
async function icMetaOf(pid){
  try{
    return await new Promise(function(res,rej){
      var out=[];var tx=db.transaction('projectFiles','readonly');var st=tx.objectStore('projectFiles');
      var src=null;try{src=st.index('byProject')}catch(e){}
      var req=src?src.openCursor(IDBKeyRange.only(pid)):st.openCursor();
      req.onsuccess=function(ev){var c=ev.target.result;if(!c){res(out);return}
        var v=c.value||{};
        if(src||v.projectId===pid){out.push({id:v.id,projectId:v.projectId,name:v.name,path:v.path,
          size:(typeof v.size==='number'&&isFinite(v.size))?v.size:(typeof v.content==='string'?v.content.length:0),
          created:v.created||0,lastModified:v.lastModified||v.created||0,lastModifiedBy:v.lastModifiedBy||''})}
        c.continue()};
      req.onerror=function(){rej(req.error)};
    });
  }catch(e){try{return (await icFilesOf(pid)).map(function(f){return {id:f.id,projectId:f.projectId,name:f.name,path:f.path,size:(typeof f.size==='number'?f.size:(typeof f.content==='string'?f.content.length:0)),created:f.created||0,lastModified:f.lastModified||f.created||0,lastModifiedBy:f.lastModifiedBy||''}})}catch(e2){return []}}
}
let _icView='projs';/* v55-m t28：两级文件管理器（项目夹 → 文件），逻辑照电脑端：项目仅 AI 可建，用户只能导入文件 */
async function renderIcode(){
  await icEnsureFixed();
  let projs=[];try{projs=await dbGetAll('projects')}catch(e){}
  projs.sort((a,b)=>{
    const w=x=>x.id===WS_DEFAULT_PROJ_ID?0:(x.id===WS_USER_PROJ_ID?1:2);
    return w(a)-w(b)||String(a.name||'').localeCompare(String(b.name||''),'zh-CN');
  });
  if(!projs.find(x=>x.id===_icProj)){_icProj=WS_DEFAULT_PROJ_ID;_icView='projs'}
  const bar=$('ic-projs'),box=$('ic-files'),cr=$('ic-crumb'),st=$('ic-stats');
  if(!bar)return;
  if(_icView==='projs'){
    $('ic-back').style.display='none';$('ic-crumb-t').innerHTML='ICode<span class="ph-cn">工作区</span>';/* v61-m t5：常驻标题块，顶层显示 ICode；v81-m r5：+中字（项目层仍只显项目名） */
    st.style.display='none';box.innerHTML='';box.className='';
    bar.style.display='';bar.innerHTML='';
    for(const pj of projs){
      let fs=[];try{fs=await icMetaOf(pj.id)}catch(e){}/* v116-p */
      let sz=0;fs.forEach(f=>sz+=(f.size||0));
      const row=document.createElement('div');row.className='li ic-prow';
      row.innerHTML='<span class="ic-fold">'+WS_ICON.folder+'</span>'
        +'<div class="li-main"><div class="ic-name">'+esc(pj.name||'项目')+((pj.isDefault||pj.isUser)?'<span class="ic-def">默认</span>':'')+'</div>'
        +'<div class="li-sub">'+fs.length+' 个文件'+(sz?(' · '+icFmtSize(sz)):'')+'</div></div>'
        +'<svg class="nw-chev" viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg>';
      row.addEventListener('click',()=>{_icProj=pj.id;_icView='files';renderIcode()});
      if(!pj.isDefault&&!pj.isUser)pressable(row,()=>icProjActions(pj));
      bar.appendChild(row);
    }
    return;
  }
  const pj=projs.find(x=>x.id===_icProj)||projs[0];
  bar.style.display='none';bar.innerHTML='';
  $('ic-back').style.display='';$('ic-crumb-t').textContent=pj.name||'项目';
  const files=(await icMetaOf(_icProj)).sort((a,b)=>(b.lastModified||0)-(a.lastModified||0));/* v116-p：文件列表只持元数据，打开时才读正文 */
  if(st){let sz=0;files.forEach(f=>sz+=(f.size||0));st.textContent=files.length?(files.length+' 个文件 · '+icFmtSize(sz)):'';st.style.display=files.length?'':'none'}
  box.innerHTML='';
  if(!files.length){box.className='';box.innerHTML='<div class="empty">此文件夹还没有文件。<br>可在上方导入，或由 AI 在对话中通过工作区指令写入。</div>';return}
  box.className='ic-list';
  files.forEach(f=>{
    const d=document.createElement('div');d.className='li';
    const nm=f.path||f.name||'未命名';
    const ext=(String(nm).match(/\.([a-z0-9]{1,5})$/i)||[])[1]||'';
    d.innerHTML='<span class="ic-tile" style="--dh:'+_icHue(ext)+'">'+esc((ext||'·').toUpperCase().slice(0,4))+'</span>'
      +'<div class="li-main"><div class="ic-name">'+esc(nm)+'</div><div class="li-sub">'+icFmtSize(f.size)+' · '+new Date(f.lastModified||f.created||Date.now()).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})+(f.lastModifiedBy?' · '+esc(f.lastModifiedBy):'')+'</div></div>';
    d.addEventListener('click',()=>openIcFile(f));
    box.appendChild(d);
  });
}
/* v53-m：扩展名 → 色相（与抽屉徽章同一套霜色明度） */
function _icHue(ext){
  ext=String(ext||'').toLowerCase();
  if(/^(js|jsx|mjs|cjs)$/.test(ext))return 42;
  if(/^(ts|tsx)$/.test(ext))return 216;
  if(/^(html?|xml|svg)$/.test(ext))return 16;
  if(/^(css|scss|less)$/.test(ext))return 255;
  if(/^(md|markdown|txt)$/.test(ext))return 205;
  if(/^(json|ya?ml|toml|csv)$/.test(ext))return 275;
  if(/^(py|rb|go|rs|java|c|h|cpp|cs|sh)$/.test(ext))return 166;
  if(/^(png|jpe?g|gif|webp|ico)$/.test(ext))return 318;
  return 210;
}
function icProjActions(pj){
  actionSheet([
    {label:'重命名项目',fn:()=>{_icNewMode='projRename';_icFile=pj;$('icn-title').textContent='重命名项目';$('icn-lab').textContent='项目名称';$('icn-name').value=pj.name||'';openSheet('sheet-icnew')}},
    {label:'删除项目及其全部文件',danger:true,fn:async()=>{
      if(!await confirmDlg('删除项目「'+(pj.name||'')+'」及其全部文件？此操作不可恢复。','删除'))return;
      const fs=await icFilesOf(pj.id);
      try{await dbDeleteMany('projectFiles',fs.map(f=>f.id));await dbDelete('projects',pj.id)}catch(e){toast('删除失败');return}
      if(_icProj===pj.id)_icProj=WS_DEFAULT_PROJ_ID;
      renderIcode();toast('已删除');
    }}
  ]);
}
async function openIcFile(f){
  if(f&&f.id&&typeof f.content==='undefined'){try{var _full=await dbGet('projectFiles',f.id);if(_full)f=_full}catch(e){}}/* v116-p：元数据行点开时才按 id 读正文 */
  _icFile=f;
  $('icf-name').textContent=f.path||f.name||'未命名';
  $('icf-meta').textContent=icFmtSize(f.size)+' · 修改于 '+new Date(f.lastModified||Date.now()).toLocaleString('zh-CN')+(f.lastModifiedBy?' · '+f.lastModifiedBy:'');
  const ta=$('icf-body');
  const isText=typeof f.content==='string';
  ta.value=isText?f.content:'';
  ta.disabled=!isText;
  ta.placeholder=isText?'':'（该文件不含可编辑文本，仅支持下载）';
  $('icf-save').style.display=isText?'':'none';
  openSheet('sheet-icfile');
}
$('icf-save').addEventListener('click',async()=>{
  const f=_icFile;if(!f)return;
  f.content=$('icf-body').value;
  try{f.size=new Blob([f.content]).size}catch(e){f.size=(f.content||'').length}
  f.lastModified=Date.now();f.lastModifiedBy='user';
  try{
    await dbPut('projectFiles',f);
    const pj=await dbGet('projects',f.projectId);if(pj){pj.lastModified=f.lastModified;await dbPut('projects',pj)}
  }catch(e){toast('保存失败');return}
  closeSheets();renderIcode();toast('已保存');
});
$('icf-dl').addEventListener('click',()=>{
  const f=_icFile;if(!f)return;
  try{
    const a=document.createElement('a');
    if(typeof f.content==='string'){a.href=URL.createObjectURL(new Blob([f.content],{type:'text/plain;charset=utf-8'}))}
    else if(f.dataUrl){a.href=f.dataUrl}
    else{toast('该文件没有可下载内容');return}
    a.download=(f.path||f.name||'file').split('/').pop();
    document.body.appendChild(a);a.click();a.remove();
  }catch(e){toast('下载失败')}
});
$('icf-more').addEventListener('click',()=>{
  const f=_icFile;if(!f)return;
  actionSheet([
    {label:'重命名',fn:()=>{_icNewMode='fileRename';$('icn-title').textContent='重命名文件';$('icn-lab').textContent='文件名（可含子目录）';$('icn-name').value=f.path||f.name||'';openSheet('sheet-icnew')}},
    {label:'删除文件',danger:true,fn:async()=>{
      if(!await confirmDlg('删除文件「'+(f.path||f.name||'')+'」？此操作不可恢复。','删除'))return;
      try{await dbDelete('projectFiles',f.id)}catch(e){toast('删除失败');return}
      closeSheets();renderIcode();toast('已删除');
    }}
  ]);
});
$('ic-back').addEventListener('click',()=>{_icView='projs';renderIcode()});

function _wsRunMode(){try{return localStorage.getItem('ib_wsRunMode')==='auto'?'auto':'ask'}catch(e){return 'ask'}}
function _wsFineOn(){try{return localStorage.getItem('ib_wsFineTools')==='1'}catch(e){return false}}/* v88-m 任务④：精细文件工具总开关（默认关） */
function _wsToggleRunMode(){try{localStorage.setItem('ib_wsRunMode',_wsRunMode()==='auto'?'ask':'auto')}catch(e){}_wsSyncRunSwitch();toast('ICode 已切换为「'+(_wsRunMode()==='auto'?'自动执行':'逐步确认')+'」')}
function _wsSyncRunSwitch(){var sw=$('ws-run-switch');if(!sw)return;var on=_wsRunMode()==='auto';sw.classList.toggle('on',on);sw.setAttribute('aria-pressed',on?'true':'false');var rr=$('ic-ai-rounds');if(rr){rr.disabled=!on;rr.style.opacity=on?'1':'.45';rr.title=on?'自动模式下允许 AI 连续执行的工作区步骤数':'Script 已关闭：当前为逐步确认模式'}}
$('ws-run-switch').addEventListener('click',_wsToggleRunMode);
function _wsFineSync(){try{var s=$('ic-fine-state');if(s){s.textContent=_wsFineOn()?'已开启':'未开启';s.classList.toggle('on',_wsFineOn())}var t=$('icf-on');if(t)sw2(t,_wsFineOn())}catch(e){}}/* v88-m 任务④ */
try{$('ic-fine-open').addEventListener('click',function(){_wsFineSync();openSheet('sheet-icfine')});$('icf-on').addEventListener('click',function(){try{localStorage.setItem('ib_wsFineTools',_wsFineOn()?'0':'1')}catch(e){}_wsFineSync();toast('精细文件工具已'+(_wsFineOn()?'开启':'关闭')+'；下一条消息重建一次提示缓存')});_wsFineSync()}catch(e){}
try{var _icCap9=$('icf-cap');if(_icCap9){_icCap9.value=String(_fileCapM());_icCap9.addEventListener('change',function(){try{localStorage.setItem('ib_fileCap',_icCap9.value)}catch(e){}toast('附件正文上限已改为 '+_icCap9.value+' 字符，下一条消息起生效')})}}catch(e){}/* v221-p：附件正文闸三档（本机） */
_wsSyncRunSwitch();
$('ic-import').addEventListener('click',()=>$('ic-import-file').click());
$('ic-import-file').addEventListener('change',async e=>{/* v55-m t28：用户侧只能导入文件（文本按原文、其他按 dataURL 存入当前文件夹） */
  const fl=[...e.target.files];e.target.value='';if(!fl.length)return;
  for(const f of fl){
    if(f.size>8*1048576){toast(f.name+'：超过 8 MB，已跳过');continue}
    const isText=/^text\/|json|xml|javascript|svg/.test(f.type)||/\.(md|txt|js|ts|json|css|html?|py|csv|ya?ml)$/i.test(f.name);
    let content='';
    try{
      if(isText)content=await f.text();
      else content=await new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(String(fr.result));fr.onerror=rej;fr.readAsDataURL(f)});
    }catch(err){toast(f.name+'：读取失败');continue}
    try{await dbPut('projectFiles',{id:'file_'+Date.now()+'_'+Math.floor(Math.random()*1e5),projectId:_icProj,path:f.name,content:content,size:f.size,created:Date.now(),lastModified:Date.now(),lastModifiedBy:'你'})}catch(err){toast(f.name+'：保存失败');continue}
  }
  renderIcode();toast('已导入');
});
$('icn-ok').addEventListener('click',async()=>{
  const v=$('icn-name').value.trim();if(!v){toast('请输入名称');return}
  const now=Date.now();
  if(false){}else if(false){}else if(_icNewMode==='projRename'){
    const pj=_icFile;pj.name=v;pj.lastModified=now;
    try{await dbPut('projects',pj)}catch(e){toast('保存失败');return}
  }else if(_icNewMode==='fileRename'){
    const f=_icFile;f.path=v;if('name' in f)f.name=v;f.lastModified=now;f.lastModifiedBy='user';
    try{await dbPut('projectFiles',f)}catch(e){toast('保存失败');return}
    $('icf-name').textContent=v;
  }
  closeSheets();renderIcode();toast('完成');
});
SEC_RENDER['icode:ws']=renderIcode;

/* ═══ v53-m API·全部聊天记录（照电脑端：总条数 / 占用 / 清空）═══ */
async function ahRefresh(){
  const ce=$('ah-count'),se=$('ah-size');if(!ce)return;
  let msgs=[];try{msgs=await dbGetAll('chatMessages')}catch(e){}
  ce.textContent='共 '+msgs.length+' 条消息';
  let sz=0;try{sz=new Blob([JSON.stringify(msgs)]).size}catch(e){}
  var vbN=0,vbSz=0;try{msgs.forEach(function(m){if(m&&m.callAudio&&m.callAudio.length){vbN+=m.callAudio.length;vbSz+=JSON.stringify(m.callAudio).length}})}catch(e){}/* 本轮：语音条占比单列，配合下方「清除通话语音条」 */
  se.textContent='占用：'+icFmtSize(sz)+(vbN?'（含通话语音条 '+vbN+' 枚 · 约 '+icFmtSize(vbSz)+'）':'');
}
(function(){const og=SEC_RENDER['api:global'];SEC_RENDER['api:global']=function(){if(og)og();ahRefresh()}})();
$('ah-clear').addEventListener('click',async()=>{
  if(!await confirmDlg('清空全部聊天记录？所有好友与话题频道的消息、以及对话摘要都会被删除，此操作不可恢复。','清空'))return;
  try{
    const ms=await dbGetAll('chatMessages');await dbDeleteMany('chatMessages',ms.map(x=>x.id));
    const ss=await dbGetAll('chatSummaries');await dbDeleteMany('chatSummaries',ss.map(x=>x.id));
  }catch(e){toast('清空失败');return}
  ahRefresh();try{renderFriends()}catch(e){}
  toast('已清空');
});


