function _ibCacheHintM(cfg,inTok,crTok){
  try{
    if(!cfg||cfg.promptCache===false)return;
    var ep=String(cfg.endpoint||''),mdl=String(cfg.model||'');
    console.info('[IB手机缓存诊断] 本轮 usage：输入 '+(inTok||0)+' tok · 缓存命中 '+(crTok||0)+' tok');
    if(crTok)return;
    var tip='';
    if(/volces\.com/i.test(ep))tip='火山方舟隐式缓存仅 doubao-seed-2.0 及之后系列与 seed-code 支持（服务端自动、不可关）；seed-1.6 / 1.5 等旧系列在 Chat 接口上没有隐式缓存（需服务端 Context API），属服务商侧限制。另需可复用前缀 ≥1024 tok，且官方注明「不保证命中」。当前模型：'+mdl;
    else if(/moonshot\.cn/i.test(ep))tip='Kimi 官方直连没有隐式缓存——Context Caching 需先调 /v1/caching 显式建缓存（按分钟计费），普通聊天接口不会自动命中；想吃自动缓存可改走阿里百炼部署的 kimi 模型。';
    else if(/bigmodel\.cn/i.test(ep))tip='智谱隐式缓存为自动开启，命中写在 usage.prompt_tokens_details.cached_tokens；官方支持列表以 GLM-5 系列为主，旧的 flash 免费档命中可能极低。当前模型：'+mdl;
    else if(/dashscope|aliyuncs/i.test(ep))tip='百炼隐式缓存自动开启（约 256 tok 起，Qwen3.7 系列约 2000 tok 起），命中概率由服务端判定、官方注明不保证 100%。';
    else if(/googleapis/i.test(ep))tip='Gemini 隐式缓存自 2.5 系列起才有；2.0-flash 等旧型号没有隐式缓存。命中字段为 usageMetadata.cachedContentTokenCount。当前模型：'+mdl;
    else if(/x\.ai/i.test(ep))tip='xAI 提示缓存为服务端自动、无开关；短对话或未达门槛时命中为 0 属正常。';
    if(tip)console.info('[IB手机缓存诊断] 命中为 0 的可能原因（'+(cfg.provider||'该服务商')+'）：'+tip);
  }catch(e){}
}
async function sendQuickText(t,extra){/* 复用 sendMsg 主干：不动输入框草稿；+extra（通话轮附带 callTone 等消息级字段） */
  const cfg=_activeCfg;if(!cfg||!t)return false;
  if(_sendKeys.has(_convKey(cfg))){
    const _qk=_convKey(cfg);let _qw=0;
    while(_sendKeys.has(_qk)&&_qw<150){await new Promise(r=>setTimeout(r,100));_qw++}
    if(_sendKeys.has(_qk)){toast('当前对话仍在传输，这条快捷消息没有发出，请稍后手动发送');return false}
  }
  if(!cfg.apiKey&&!cfg._group){toast('这个配置还没有 API Key，请到 API 页填写');return false}
  const um={id:'msg_'+Date.now()+'_u',role:'user',content:t,friendId:cfg.id,timestamp:Date.now()};
  if(extra&&extra.callTone)um.callTone=String(extra.callTone).slice(0,240);/* 通话轮声学语气随消息定格 */
  if(extra&&Array.isArray(extra.images)&&extra.images.length)um.images=extra.images;/* 手机端：视频通话轮附带画面帧（与手选图片同管线） */
  if(extra&&Array.isArray(extra.ephImages)&&extra.ephImages.length)try{window._ibcEphM={id:um.id,imgs:extra.ephImages.map(function(x){return x&&(x.dataUrl||x.url)}).filter(Boolean)}}catch(e){}/* 手机端：临时帧登记（onTurnEnd 清除） */
  if(extra&&extra.tail)try{window._ibAppTailM={id:um.id,text:String(extra.tail).slice(0,6000)}}catch(e){}
  if(extra&&extra.coread&&typeof extra.coread==='object')um.coread=extra.coread;/* v189-p：共读纸条的页码锚点（书 id / 页 / 字偏移），只落库不进 API */
  if(_activeThread)um.threadId=_activeThread.id;
  try{await dbPut('chatMessages',um)}catch(e){toast('本地保存失败');return false}
  _presTouch();
  _msgs.push(um);
  const box=convEl('cv-msgs');
  const emptyEl=box.querySelector('.empty');if(emptyEl)emptyEl.remove();
  box.appendChild(buildMsgEl(um,_msgs[_msgs.length-2]||null));
  try{_tmCollapseAll()}catch(e){}/* v97-m 任务3 */
  box.scrollTop=box.scrollHeight;
  if(cfg._group)genReplyGroup(cfg);else genReply(cfg);
  return true;/* 通话轮数只在真正发出时计数（sendOut 读此返回值） */
}

