        if(/\/chat\/completions/i.test(cfg.endpoint||''))oUrl=cfg.endpoint.replace(/\/chat\/completions[^?#]*/i,'/images/generations');
        else oUrl=new URL(cfg.endpoint).origin+'/v1/images/generations';
