function _mtNow(){
  try{
    if(!_pw||!_pw.a||_pw.a.paused||_pw.idx<0)return null;
    var it=_pw.list&&_pw.list[_pw.idx];if(!it)return null;
    return String(it.name||it.title||'').replace(/\.[a-z0-9]+$/i,'');
  }catch(e){return null}
}
function buildMusicTail(userMsg,fid){
  var ma=(_mp&&_mp.musicAi)||{};
  if(!ma.share&&!ma.ctl)return '';
  var seg=[];
  var now=_mtNow();
  if(ma.share&&now&&!(ma.mate&&fid&&fid!==ma.mate))seg.push('【正在播放】《'+now+'》');
  var rec=(_pw&&_pw.idx>=0&&_pw.list)?_pw.list[_pw.idx]:null;
  if(ma.ctl&&typeof _musicRelatedM==='function'&&_musicRelatedM(userMsg,rec)){var names=[];try{(_pw.list||[]).slice(0,12).forEach(function(it){names.push('《'+String(it.name||it.title||'').replace(/\.[a-z0-9]+$/i,'')+'》')})}catch(e){}if(names.length)seg.push('【当前歌单】'+names.join(''))}
  return seg.join('\n\n');
}
function _mtExec(op,q){
  try{
    if(!_pw)return{ok:false,label:'播放器',detail:'播放器不可用'};
    if(op==='play'&&q){
      var kw=String(q).toLowerCase(),idx=-1;
      (_pw.list||[]).some(function(it,i){var n=String(it.name||it.title||'').toLowerCase();if(n.indexOf(kw)!==-1){idx=i;return true}return false});
      if(idx<0)return{ok:false,label:'播放歌曲',detail:'歌单里没有找到「'+q+'」'};
      if(typeof _pwPlayIdx==='function')_pwPlayIdx(idx);
      return{ok:true,label:'播放歌曲',detail:'《'+String((_pw.list[idx]||{}).name||q).replace(/\.[a-z0-9]+$/i,'')+'》'};
    }
    if(op==='play'){
      if(_pw.idx<0&&(_pw.list||[]).length&&typeof _pwPlayIdx==='function'){_pwPlayIdx(0);return{ok:true,label:'播放',detail:'从歌单第一首开始'}}
      if(_pw.a&&_pw.a.paused){_pw.a.play();return{ok:true,label:'继续播放',detail:_mtNow()?('《'+_mtNow()+'》'):''}}
      return{ok:true,label:'播放',detail:'播放器已在播放'};
    }
    if(op==='pause'){if(_pw.a&&!_pw.a.paused){_pw.a.pause();return{ok:true,label:'暂停播放',detail:''}}return{ok:true,label:'暂停',detail:'播放器本来就是暂停的'}}
    if(op==='next'){var b=$('pw-next');if(b)b.click();return{ok:true,label:'下一首',detail:_mtNow()?('《'+_mtNow()+'》'):''}}
    if(op==='prev'){var b2=$('pw-prev');if(b2)b2.click();return{ok:true,label:'上一首',detail:_mtNow()?('《'+_mtNow()+'》'):''}}
    return{ok:false,label:'播放器',detail:'未知指令 '+op};
  }catch(e){return{ok:false,label:'播放器',detail:String(e&&e.message||e)}}
}

/* ── Internet Beyond：动态流核心 ── */
function _ibfAgo(ts){
  var d=Date.now()-ts;
  if(d<60000)return '刚刚';
  if(d<3600000)return Math.floor(d/60000)+' 分钟前';
  if(d<86400000)return Math.floor(d/3600000)+' 小时前';
  if(d<7*86400000)return Math.floor(d/86400000)+' 天前';
  var dt=new Date(ts);return (dt.getMonth()+1)+'月'+dt.getDate()+'日';
}
async function _ibfMaster(){
  await loadMP();var ib=_mp.ib||{};
  return ib.on!==false&&!!ib.on;
}
async function ibfAll(){
  var rows=[];try{rows=await dbGetAll('feed')}catch(e){}
  return rows.sort(function(a,b){return (b.ts||0)-(a.ts||0)});
}
function ibfVisibleTo(p,fid){
  if(!p)return false;
  var own=p.author&&p.author.type==='ai'&&p.author.fid===fid;
  var v=p.vis||'all';
  if(v==='all')return true;
  if(v==='user')return own;
  if(v==='only')return own||(Array.isArray(p.visTo)&&p.visTo.indexOf(fid)!==-1);
  if(v==='except')return own||!(Array.isArray(p.visEx)&&p.visEx.indexOf(fid)!==-1);
  return false;
}
function _ibfRerenderIfOpen(){bxRerenderFeeds()}/* v76-m r4：AI 发布/评论后同步刷新 Beyond 页与主页 Profile/Beyond 分区 */
async function ibfInsertPost(author,text,vis,imgPrompt,cfgForImg){
  var p={id:'fd_'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),ts:Date.now(),
    author:author,text:String(text||'').trim().slice(0,1000),vis:vis==='user'?'user':'all',comments:[]};
  if(!p.text)return null;
  await dbPut('feed',p);
  _ibfRerenderIfOpen();
  if(imgPrompt&&cfgForImg&&typeof _wsExecImageGen==='function'){
    _wsExecImageGen(cfgForImg,imgPrompt,'1024x1024').then(async function(r){
      if(r&&r.ok&&r.dataUrl){p.img=r.dataUrl;try{await dbPut('feed',p)}catch(e){}_ibfRerenderIfOpen()}
    }).catch(function(){});
  }
  return p;
}
async function ibfInsertComment(pid,author,text,re){/* v84-m r3：+re（回复目标）＋每帖 20 条上限（任务 10/补充逻辑） */
  var rows=await ibfAll();
  var p=rows.find(function(x){return x.id===pid});
  if(!p)return null;
  p.comments=p.comments||[];
  if(p.comments.length>=20)return 'cap';
  var cm={id:'fc_'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),ts:Date.now(),author:author,text:String(text||'').trim().slice(0,300)};/* v92-m：id 加随机尾，堵同毫秒撞 id */
  if(re&&re.name)cm.re={cid:String(re.cid||''),name:String(re.name).slice(0,24)};
  p.comments.push(cm);
  await dbPut('feed',p);
  _ibfRerenderIfOpen();
  return p;
}
var _bxReplyTo={};/* v84-m r3：pid → {cid,name} 待回复目标 */
async function ibfDeleteComment(pid,cid,fb){
  var rows=await ibfAll();var p=rows.find(function(x){return x.id===pid});if(!p)return false;
  var cs=p.comments||[];var idx=-1;
  if(cid)idx=cs.findIndex(function(c){return c&&c.id===cid});
  if(idx<0&&fb)idx=cs.findIndex(function(c){return c&&Number(c.ts||0)===Number(fb.ts||0)&&String(c.text||'')===String(fb.text||'')});
  if(idx<0)return false;
  cs.splice(idx,1);p.comments=cs;
  await dbPut('feed',p);_ibfRerenderIfOpen();return true;
}
