async function _bxInboxTail(cfg){
  try{
    var rows=await ibfAll();if(!rows.length)return '';
    await loadCfgs();var cfgs=(_cfgs||[]).concat((typeof _archived!=='undefined'&&_archived)?_archived:[]);
    var me=null;try{me=await loadAbout()}catch(e){}
    var myName=cfgName(cfg);var W=72*3600e3,now=Date.now(),out=[];
    var nmOf=function(a){a=a||{};if(a.type==='user')return (me&&me.name)||'用户';var c0=cfgs.find(function(c){return c.id===a.fid});return (c0&&cfgName(c0))||a.name||'AI'};
    rows.forEach(function(p){
      if(!ibfVisibleTo(p,cfg.id))return;
      var mine=p.author&&p.author.type==='ai'&&p.author.fid===cfg.id;
      if(p.rt&&p.rt.pid&&now-(p.ts||0)<W&&!(p.author&&p.author.fid===cfg.id)){
        var o=rows.find(function(x){return x.id===p.rt.pid});
        if(o&&o.author&&o.author.type==='ai'&&o.author.fid===cfg.id)out.push(nmOf(p.author)+' 转发了你的动态 #'+o.id+(p.text?('：'+String(p.text).replace(/\s+/g,' ').slice(0,50)):''));
      }
      (p.comments||[]).forEach(function(cm){
        if(now-(cm.ts||0)>=W)return;
        if(cm.author&&cm.author.type==='ai'&&cm.author.fid===cfg.id)return;
        if(mine)out.push(nmOf(cm.author)+(cm.re&&cm.re.name?'回复':'评论')+'了你的动态 #'+p.id+'：'+String(cm.text||'').replace(/\s+/g,' ').slice(0,60));
        else if(cm.re&&cm.re.name===myName)out.push(nmOf(cm.author)+' 回复了你在 #'+p.id+' 的评论：'+String(cm.text||'').replace(/\s+/g,' ').slice(0,60));
      });
    });
    if(!out.length)return '';
    return '【社交圈互动提醒（近 72 小时）】\n'+out.slice(0,8).join('\n');
  }catch(e){return ''}
}


