    var isU=p.author&&p.author.type==='user';
    var cfg0=!isU&&cfgs.find(function(c){return c.id===(p.author&&p.author.fid)});
    var nm=isU?((me&&me.name)||'我'):((cfg0&&cfgName(cfg0))||(p.author&&p.author.name)||'AI');
    var lines=[nm+'：'+String(p.text||'').replace(/^\u200b$/,'').trim()+((p.imgs&&p.imgs.length>1)?('（附图×'+Math.min(p.imgs.length,3)+'）'):(p.img?'（附图）':''))];/* v78-m r11 */
    (p.comments||[]).forEach(function(cm){
      var cu=cm.author&&cm.author.type==='user';
      var ccfg=!cu&&cfgs.find(function(c){return c.id===(cm.author&&cm.author.fid)});
      var cn=cu?((me&&me.name)||'我'):((ccfg&&cfgName(ccfg))||(cm.author&&cm.author.name)||'AI');
      lines.push('└ '+cn+'：'+String(cm.text||'').trim());
    });
    var txt=('【Beyond 动态】'+new Date(p.ts||Date.now()).toLocaleDateString()+'\n'+lines.join('\n')).slice(0,600);
    var flat=txt.replace(/\s+/g,' ');
    var _sm9=(/^[^。！？!?]*[。！？!?]?/.exec(String(p.text||'').replace(/\u200b/g,'').replace(/\s+/g,' ').trim())||[''])[0].trim().slice(0,80);/* 本轮：#1 概述取动态正文首句（机械截取，不走 API） */
    var mem={id:'mem_'+Date.now()+'_'+Math.floor(Math.random()*10000),
      title:(nm+'的动态：'+String(p.text||'').replace(/\s+/g,' ')).slice(0,18)+'…',
      content:txt,summary:_sm9,oneLine:'',domain:'日常',tags:['Beyond'],
      importance:5,valence:0.5,arousal:0.3,pinned:false,resolved:false,
      visibility:'public',visibleTo:[],excludeFrom:[],
      rawSource:'Beyond动态',sourceId:p.id||'',activationCount:0,created:Date.now(),lastActivated:Date.now(),
      createdBy:(isU?'user':(p.author&&p.author.fid)||''),createdByName:nm,editedByUser:false};
    await dbPut('memories',mem);
