async function buildBeyondTail(cfg){
  if(!cfg||!cfg.id)return '';
  if(!await _ibfMaster())return '';
  var pb=cfg.beyond||{};
  if(!pb.on)return '';
  var pa=(typeof mpAi==='function')?mpAi(cfg):null;
  var lim=(pa&&pa.ibfeedLimit!=null)?pa.ibfeedLimit:20;
  var seg=[];
  if(lim>0){
    var rows=(await ibfAll()).filter(function(p){return ibfVisibleTo(p,cfg.id)}).slice(0,lim);
    if(rows.length){
      var me=null;try{me=await loadAbout()}catch(e){}
      var lines=['【Beyond 最近动态】（新→旧）'];
      rows.forEach(function(p){
        var nm=p.author&&p.author.type==='user'?((me&&me.name)||'用户'):(p.author&&p.author.name)||'AI';
        var l='#'+p.id+' ｜ '+nm+' ｜ '+_ibfAgo(p.ts||0)+' ｜ '+String(p.text||'').replace(/\s+/g,' ').slice(0,(p.author&&p.author.type==='user')?1000:100)+((p.imgs&&p.imgs.length>1)?(' ｜ [配图×'+Math.min(p.imgs.length,3)+']'):(p.img?' ｜ [配图]':''))+(p.vis==='user'?'（仅用户可见）':(p.vis&&p.vis!=='all'?'（部分可见）':''));
        lines.push(l);
        (p.comments||[]).slice(-2).forEach(function(cm){
          var cn=cm.author&&cm.author.type==='user'?((me&&me.name)||'用户'):(cm.author&&cm.author.name)||'AI';
          lines.push('  └ 评论 · '+cn+'：'+String(cm.text||'').replace(/\s+/g,' ').slice(0,60));
        });
      });
      seg.push(lines.join('\n'));
    }else seg.push('【Beyond 最近动态】（新→旧）\n目前还没有动态。');
  }
  await loadMP();
  var perMe=(_mp.perAi&&_mp.perAi[cfg.id])||{};
  if(perMe.sigAI)seg.push('【Beyond 当前资料】你的个性签名当前是'+(perMe.sig?('「'+String(perMe.sig).slice(0,200)+'」'):'（暂未设置）')+'。');
  return seg.join('\n\n');
}
/* ── AI 回复标签执行：Beyond / 播放器 / 天气（照 procMemOps 模式） ── */
var _WMO={0:'晴',1:'基本晴',2:'多云',3:'阴',45:'雾',48:'冻雾',51:'毛毛雨',53:'毛毛雨',55:'毛毛雨',56:'冻毛毛雨',57:'冻毛毛雨',61:'小雨',63:'中雨',65:'大雨',66:'冻雨',67:'冻雨',71:'小雪',73:'中雪',75:'大雪',77:'雪粒',80:'阵雨',81:'阵雨',82:'强阵雨',85:'阵雪',86:'强阵雪',95:'雷阵雨',96:'雷阵雨伴冰雹',99:'雷阵雨伴冰雹'};
async function _gwEnsure(){
  try{
    await loadMP();
    var lat=null,lon=null,city='';
    if(_mp.perms&&_mp.perms.geo&&navigator.geolocation){
      try{var pos=await new Promise(function(res,rej){navigator.geolocation.getCurrentPosition(res,rej,{timeout:8000,maximumAge:600000})});lat=pos.coords.latitude;lon=pos.coords.longitude}catch(e){}
    }
    if(lat==null){var cg=null;try{cg=(typeof _ibCityGeo==='function')?await _ibCityGeo():null}catch(e){}if(cg&&isFinite(cg.lat)){lat=cg.lat;lon=cg.lng;city=cg.city||''}}
    if(lat==null)return null;
    if(!city){try{var g=await fetch('https://api.bigdatacloud.net/data/reverse-geocode-client?latitude='+lat+'&longitude='+lon+'&localityLanguage=zh');var gj=await g.json();city=(gj&&(gj.city||gj.locality||gj.principalSubdivision))||''}catch(e){}}
    var tempC=null,code=null;
    try{var r=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&current_weather=true');var j=await r.json();var cw=j&&j.current_weather;if(cw){tempC=cw.temperature;code=cw.weathercode}}catch(e){}
    return {lat:lat,lon:lon,city:city,tempC:tempC,code:code};
  }catch(e){return null}
}
async function _phoneSnapM(){
  var o=[];
  try{if(navigator.getBattery){var b=await navigator.getBattery();o.push('电量'+Math.round((b.level||0)*100)+'%'+(b.charging?'(充电中)':''))}}catch(e){}
  try{var c=navigator.connection||navigator.webkitConnection;if(c&&(c.effectiveType||c.downlink))o.push('网络'+(c.effectiveType||'')+(c.downlink?('·'+c.downlink+'Mbps'):'')+(c.saveData?'·省流量':''))}catch(e){}
  o.push(navigator.onLine?'在线':'离线');
  try{if(navigator.storage&&navigator.storage.estimate){var s=await navigator.storage.estimate();if(s&&s.quota)o.push('本站存储'+icFmtSize(s.usage||0)+'/配额'+icFmtSize(s.quota))}}catch(e){}
  try{if(navigator.deviceMemory)o.push('内存档'+navigator.deviceMemory+'GB')}catch(e){}
  try{o.push('屏幕'+screen.width+'×'+screen.height+((window.matchMedia&&matchMedia('(display-mode: standalone)').matches)?'·PWA':''))}catch(e){}
  return o.join('；').slice(0,138);
}
